insert into public.new_nutrient_interaction (id, category, nutrient, nutrient_condition, counterpart, counterpart_class, counterpart_type, outcome_type, harmful_effect, causal_ingredient, mechanism, example_products, example_scenario, severity, relation, management, evidence_level, confidence, notes, dose_dependent) values
  (1, '비타민-의약품', '비타민B3(나이아신)', '니코틴산 1g/일 이상(지질조절 용량, 서방형 포함). 니코틴아미드형이나 종합비타민의 수십 mg은 해당하지 않음', '아토르바스타틴', '스타틴(HMG-CoA 환원효소 억제제: 아토르바스타틴, 로수바스타틴, 심바스타틴 등)', 'drug', '약효증가_독성', '골격근 독성(근병증, 횡문근융해) 위험이 커짐. HPS2-THRIVE에서 니아신 군은 중대한 근골격계 이상반응이 0.7%p 더 많았음. 고령자, 당뇨, 신부전, 조절되지 않은 갑상선기능저하 환자가 특히 위험함(미국 라벨)', '니코틴산(지질조절 용량)', '니코틴산과 스타틴은 각각 근육 독성이 있어 함께 쓰면 그 위험이 더해짐. 국내 아토르바스타틴 허가사항은 니코틴산 병용 시 감량을 고려하라고 적고 있음', '리피토정·리피토플러스정(아토르바스타틴), 로수바스타틴, 심바스타틴 / 고함량 나이아신(니코틴산) 보충제', '고지혈증으로 아토르바스타틴을 먹는 60대가 혈관 건강에 좋다는 나이아신 1,000mg 보충제를 추가함', 'major', 'consult', '병용 전에 의사와 상의하고, 병용하면 스타틴 감량을 고려함(허가사항). 근육통, 무력감, 갈색 소변이 있으면 중단하고 바로 진료받으며 CK를 확인함', '식약처원문', 'high', '갑상선기능저하증이 조절되지 않는 환자는 횡문근융해 위험군임(Niaspan 라벨 5.2). 늘크크 대상층(갑상선약 복용자)에 중요함', True),
  (3, '비타민-의약품', '비타민B3(나이아신)', '니코틴산 고용량(지질조절 용량)', '메트포르민', '당뇨병 치료제(경구혈당강하제, 인슐린)', 'drug', '약효감소', '공복혈당이 오르고 당 불내성이 용량에 따라 심해져 당뇨약 효과가 상쇄됨. RCT 메타분석에서 신규 당뇨 위험이 높았고(RR 1.34, 43명당 1명 추가), HPS2-THRIVE에서는 중대한 당뇨 조절 장애가 3.7%p, 신규 당뇨 진단이 1.3%p 늘었음', '니코틴산', '니코틴산이 인슐린 저항성을 높이고 혈당을 올려(라벨: 공복혈당 상승, 당 불내성의 용량의존 증가) 혈당강하제 효과를 상쇄함', '다이아벡스정·글루코파지(메트포르민), 인슐린, DPP-4 억제제 복합제 / 나이아신 500~1000mg 보충제', '당뇨로 메트포르민을 먹는 60대가 콜레스테롤 관리용 나이아신을 먹은 뒤 당화혈색소가 올라감', 'moderate', 'monitor', '병용 시 혈당을 자주 측정하고, 혈당 변화를 의사에게 알림', 'RCT/약동학연구', 'high', null, True),
  (4, '비타민-의약품', '비타민B3(나이아신)', '지질저하 용량 니코틴산(1일 1 g 이상)', '심바스타틴', 'HMG-CoA 환원효소 억제제(스타틴: 심바스타틴·아토르바스타틴·로수바스타틴)', 'drug', '약효증가_독성', '근육병증·횡문근융해 위험이 증가한다. HPS2-THRIVE에서 서방형 니아신을 심바스타틴 40 mg에 추가하자 확정 근병증 위험비가 4.4였고, 중국인 참여자에서 특히 높았다.', '고용량 니코틴산(나이아신) 자체의 근독성과 스타틴 근독성이 더해짐', '고용량 니코틴산은 단독으로도 근육병증을 일으킬 수 있다. 스타틴의 근세포 독성과 겹치면 위험이 커지며, 아시아인에서 스타틴 노출이 높아 영향이 더 크다.', '약: 조코정20밀리그램(심바스타틴), 리피토정(아토르바스타틴), 크레스토정(로수바스타틴) / 영양제: 고용량 니코틴산(나이아신) 제품', '고지혈증으로 스타틴을 먹는 60대가 ''콜레스테롤에 좋다''며 고용량 나이아신 1 g 제품을 추가해 근육통이 생긴다.', 'moderate', 'caution', '스타틴 복용 중 1일 1 g 이상 니코틴산은 의사와 상의 없이 먹지 않는다(아토르바스타틴 허가사항: 감량 고려). 근육통·갈색뇨가 생기면 즉시 진료받는다.', '식약처원문', 'high', '일반 종합비타민의 나이아신(15~20 mg, 대개 니코틴아마이드)은 해당하지 않는다. 한국인 등 아시아인에서 위험이 더 크다는 점(HPS2-THRIVE 중국인 자료)이 대상 사용자에게 중요하다.', True),
  (5, '비타민-의약품', '비타민B3(나이아신)', '니코틴산 고용량', '알로푸리놀', '통풍치료제(요산강하제: 알로푸리놀, 페북소스타트, 프로베네시드)', 'drug', '약효감소', '혈청 요산이 올라 통풍약 효과가 상쇄되고 통풍 발작 위험이 커짐', '니코틴산', '니코틴산이 신장의 요산 배설을 줄여 요산을 올리는 것으로 알려짐(라벨에는 요산 상승만 명시)', '알로푸리놀, 페북소스타트 / 나이아신 보충제', '통풍으로 알로푸리놀을 먹는 50대 남성이 콜레스테롤 관리용 나이아신을 먹고 통풍 발작을 겪음', 'moderate', 'monitor', '통풍이 있거나 통풍약을 먹는 사람은 고용량 나이아신 전에 상담하고 요산을 확인함', '리뷰/가이드라인', 'medium', null, True),
  (6, '비타민-의약품', '비타민B3(나이아신)', '니코틴산 고용량(라벨 수치는 2000mg 기준)', '와파린', '항응고제·항혈소판제(와파린, 아스피린, 클로피도그렐 등)', 'drug', '출혈위험', '혈소판 수가 용량에 따라 줄고(2000mg에서 평균 -11%) 프로트롬빈시간이 늘어(평균 약 +4%) 출혈 위험이 커짐. HPS2-THRIVE에서 중대 출혈이 0.7%p 늘었음', '니코틴산', '니코틴산이 혈소판 수를 줄이고 응고시간을 늘려 항응고·항혈소판 효과에 더해짐', '쿠파린정·제일와파린정, 아스피린, 클로피도그렐 / 고함량 나이아신 보충제', '와파린을 먹는 70대가 나이아신 보충제를 먹은 뒤 잇몸 출혈과 멍이 늘어남', 'moderate', 'monitor', '병용 시 PT/INR과 혈소판을 확인함(라벨)', 'RCT/약동학연구', 'medium', null, True),
  (7, '비타민-의약품', '비타민B3(나이아신)', null, '이소니아지드', '항결핵제', 'drug', '영양소_흡수감소_결핍', '펠라그라(피부염, 설사, 치매). 사례-대조 연구에서 이소니아지드 노출 시 펠라그라 위험이 크게 높았음(aOR 42.6, 95% CI 13.3–136.6)', '이소니아지드', '이소니아지드가 B6(PLP)를 고갈시켜 트립토판에서 나이아신을 만드는 PLP 의존 경로(키뉴레니나아제)를 막고, 구조가 비슷해 NAD 합성과도 경쟁함. 국내 허가사항 이상반응에 펠라그라가 있음', '유한짓정100mg(이소니아지드)', '잠복결핵 치료 중인 60대 영양불량·음주자에게 햇빛 노출 부위 피부염과 설사가 생김', 'moderate', 'monitor', '영양상태가 나쁜 사람은 B6와 함께 나이아신 상태도 점검하고, 피부염·설사가 생기면 상담함', '식약처원문', 'high', '| 다른 리서처 서술: 펠라그라(나이아신 결핍: 피부염·설사·치매)가 나타날 수 있다.', False),
  (8, '비타민-의약품', '비타민B3(나이아신)', '니코틴아미드(니코틴산아미드) 성인 고용량', '카르바마제핀', '항경련제(카르바마제핀, 프리미돈)', 'drug', '약효증가_독성', '카르바마제핀 혈장농도가 올라 어지러움, 졸음, 운동실조, 복시가 생김. 프리미돈은 페노바르비탈로의 전환이 줄어듦', '니코틴아미드', '니코틴아미드가 간 시토크롬 P-450을 억제해 카르바마제핀과 프리미돈의 대사를 늦추는 것으로 추정됨(쥐 실험과 환자 3명 연구)', '테그레톨정·카마제핀정(카르바마제핀) / 나이아미정(니코틴산아미드), 피부 목적 니코틴아미드 500mg 보충제', '카르바마제핀을 먹는 60대가 피부암 예방 목적으로 니코틴아미드를 하루 1g 먹고 어지럼과 복시가 생김', 'moderate', 'monitor', '고용량 니코틴아미드를 시작하거나 끊을 때 의사에게 알리고 카르바마제핀 혈중농도를 측정해 용량을 조절함(허가사항)', '식약처원문', 'medium', '테그레톨 허가사항의 ''카르바마제핀의 혈장 농도를 상승시킬 수 있는 약물'' 항목에 들어 있음', True),
  (10, '비타민-의약품', '베타카로틴', '베타카로틴 보충제를 오를리스타트와 동시 복용', '오를리스타트', '비만치료제(리파아제 억제제)', 'drug', '영양소_흡수감소_결핍', '동시 복용 시 베타카로틴 흡수가 30% 감소했다. 1~2년 치료 중 보충제를 먹지 않은 성인에서 저베타카로틴 빈도는 6.1%(위약 1.7%)였다.', '오를리스타트의 지방 흡수 차단', '베타카로틴은 지용성이라 식이 지방과 함께 미셀로 흡수된다. 오를리스타트가 지방 분해를 막으면 흡수가 줄어든다.', '약: 제니칼캡슐120밀리그램 / 영양제: 베타카로틴 함유 눈 영양제·종합비타민', '체중 감량 중인 50대가 제니칼과 베타카로틴 눈 영양제를 아침 식사 때 함께 먹는다.', 'minor', 'separate_timing', '오를리스타트 복용과 최소 2시간 간격을 두고(예: 취침 전) 비타민 보충제를 먹는다.', '식약처원문', 'high', '| 다른 리서처 서술: 함께 먹으면 베타카로틴 흡수가 30% 줄었다. 비타민 보충을 하지 않은 성인에서 저혈중 베타카로틴 비율은 위약 1.7%, 오를리스타트 6.1%였다.', False),
  (11, '비타민-의약품', '비타민B7(비오틴)', '항경련제 장기 복용', '카르바마제핀', '항경련제(카르바마제핀, 페니토인, 페노바르비탈, 프리미돈)', 'drug', '영양소_흡수감소_결핍', '비오틴 혈중농도가 떨어짐. 장기 항경련제 치료를 받은 뇌전증 환자 264명 중 74%가 혈장 비오틴 250 ng/L 이하였음', '카르바마제핀·페니토인·페노바르비탈(비오틴 대사 촉진), 카르바마제핀·프리미돈(장 비오틴 수송 경쟁 억제)', '효소유도 항경련제가 비오틴 분해를 촉진하고(비스노르비오틴 배설 증가), 카르바마제핀과 프리미돈은 장 점막의 비오틴 수송을 경쟁적으로 억제함(Ki 4.70, 2.25 mmol/L)', '테그레톨정, 부광페니토인캡슐, 하나페노바르비탈정 / 니오틴정·올틴정 등 비오틴 5mg 정', '카르바마제핀을 오래 먹는 60대에게 탈모와 피부염이 생김', 'minor', 'monitor', '결핍 증상(탈모, 피부염)이 생기면 의사·약사와 상의해 보충함', '식약처원문', 'medium', '같은 연구에서 발프로산 단독군은 다른 항경련제군보다 비오틴 수치가 높았음. 비오틴 허가사항에는 항생제가 장내세균이 만드는 비오틴을 줄일 수 있다는 문구도 있음(대표 성분을 특정할 수 없어 행으로 만들지 않음)', True),
  (12, '비타민-의약품', '비타민A', '레티놀(비타민A) 보충제·고함량 종합비타민·대구간유. 경구 레티노이드 복용 중 모든 용량', '이소트레티노인', '경구 레티노이드(이소트레티노인, 아시트레틴, 알리트레티노인)', 'drug', '영양소_과잉_독성', '비타민A 과다증이 더 심해진다. 피부·점막 건조, 비출혈, 두통, 구역, 결막염, 고중성지방혈증, 간 이상 등이 나타날 수 있다.', '레티놀(비타민A). 레티노이드 약물과 같은 레티노산 수용체 경로에 작용한다.', '이소트레티노인·아시트레틴·알리트레티노인은 비타민A 유도체라 체내에서 비타민A와 같은 경로로 작용한다. 여기에 비타민A 보충제가 더해지면 레티노이드 부하가 누적돼 비타민A 과다증 증상이 강해진다.', '레티노이드: 니메겐연질캡슐·이소티논 등(이소트레티노인), 네오티가손캡슐(아시트레틴), 알리톡·알리가연질캡슐(알리트레티노인) / 영양제: 비타민A 단일제, 대구간유, 고함량 종합비타민', '건선으로 아시트레틴을 먹는 60대가 눈 건강용 비타민A 고함량 영양제를 함께 먹는다.', 'major', 'avoid', '경구 레티노이드 복용 중에는 비타민A 보충제와 고함량 종합비타민을 먹지 않는다. 종합비타민도 비타민A 함량을 확인한다.', '식약처원문', 'high', '세 약 모두 국내 허가사항에 명시돼 있고, 아시트레틴은 금기 항목(''비타민A 또는 다른 레티노이드를 복용중인 환자'')에도 올라 있다. 비타민A 전구체인 베타카로틴은 체내 전환이 조절되므로 같은 위험으로 보기 어렵다(출처 없음). | 다른 리서처 서술: 비타민A 과다증(두통, 두개내압 상승, 피부·점막 건조, 간독성 등)이 증강될 수 있다.', True),
  (13, '비타민-의약품', '비타민A', '장기간 고용량 레티놀 보충(하루 25,000IU 이상을 수년간)', '메토트렉세이트', '간독성이 있는 항류마티스제·면역억제제', 'drug', '약효증가_독성', '간 손상이 더해질 수 있다(이론적). 치료 목적 비타민A 장기 복용으로 생긴 간 손상 41례 분석에서 간경변을 일으킨 최소 지속 용량은 하루 25,000IU를 6년간 먹은 경우였다. 아시트레틴(비타민A 유도체)과 메토트렉세이트는 간염 위험 때문에 병용금기다.', '레티놀(비타민A). 간 성상세포에 저장되고, 과잉 시 간섬유화를 일으킨다.', '과잉 비타민A는 간 성상세포에 쌓여 섬유화를 유발한다. 메토트렉세이트도 장기 사용 시 간섬유화·간독성을 일으키므로 손상이 겹칠 수 있다. 직접 병용을 다룬 연구는 없다.', '메토트렉세이트정(류마티스관절염·건선) / 비타민A 단일제, 대구간유', '류마티스관절염으로 메토트렉세이트를 먹는 60대가 대구간유와 비타민A 영양제를 몇 년째 함께 먹는다.', 'moderate', 'caution', '메토트렉세이트 복용 중에는 비타민A 고용량 보충을 피하고, 정기 간기능검사를 받을 때 영양제 복용을 알린다.', '식약처원문', 'low', '비타민A와 메토트렉세이트의 직접 상호작용 연구는 찾지 못했다. 레티노이드(아시트레틴)+메토트렉세이트 병용금기와 비타민A 단독 간독성 근거에서 유추한 것이다.', True),
  (14, '비타민-의약품', '비타민A', '고용량 비타민A(레티놀) 보충, 특히 여드름 치료 목적으로 쓰는 경우', '미노사이클린', '테트라사이클린계 항생제(미노사이클린, 독시사이클린, 테트라사이클린)', 'drug', '기타', '두개내압 상승(가성뇌종양)이 생길 수 있다. 두통, 복시, 시신경유두부종이 나타나고, 심하면 영구 시력 손상이 남을 수 있다. 비타민A와 미노사이클린을 6주간 함께 먹은 16세에서 가성뇌종양이 생겼고 두 약을 끊자 회복됐다.', '레티놀(비타민A)과 테트라사이클린계 항생제. 각각 단독으로도 두개내압 상승을 일으킬 수 있다.', '비타민A·레티노이드와 테트라사이클린계는 각각 뇌척수액 흡수·생성에 영향을 줘 두개내압을 높이는 것으로 알려져 있다. 함께 쓰면 위험이 더해진다. 이 때문에 레티노이드와 테트라사이클린계는 DUR 병용금기다.', '미노씬캡슐(미노사이클린), 독시사이클린정 / 비타민A 단일제, 대구간유, 고함량 종합비타민', '여드름으로 미노사이클린을 먹는 20대 자녀가 피부에 좋다는 고함량 비타민A 영양제를 함께 먹는다.', 'moderate', 'caution', '테트라사이클린계 복용 중에는 고용량 비타민A 보충을 피한다. 두통, 시야장애, 복시가 생기면 즉시 중단하고 진료받는다.', '식약처원문', 'low', '식약처 허가사항과 DUR의 금기는 ''레티노이드 제제''(이소트레티노인·알리트레티노인·아시트레틴·트레티노인)와 테트라사이클린계 사이에 걸려 있다. 비타민A 보충제 자체는 증례 근거다.', True),
  (15, '비타민-의약품', '비타민A', '비타민A 보충제를 오를리스타트와 같은 시간에 먹는 경우', '오를리스타트', '지방흡수 억제 비만치료제', 'drug', '영양소_흡수감소_결핍', '비타민 보충을 하지 않은 성인에서 2회 이상 연속 저혈중 비타민A 비율은 위약 1.0%, 오를리스타트 2.2%였다. 건강인 약동학 연구에서는 비타민A 흡수가 유의하게 줄지 않았다.', '오를리스타트. 리파아제를 억제해 지방 흡수를 줄인다.', '지방 흡수가 줄면 지용성 비타민A도 일부 함께 배설될 수 있다. 다만 그 정도는 비타민E·D보다 작다.', '제니칼캡슐120mg / 비타민A 함유 종합비타민', '오를리스타트를 먹는 50대가 식사와 함께 종합비타민을 먹는다.', 'minor', 'separate_timing', '종합비타민은 오를리스타트 복용 최소 2시간 전이나 취침 전에 먹는다.', '식약처원문', 'medium', '허가사항의 약동학 항목에는 비타민A 보충제 흡수에 미치는 영향이 ''알려지지 않았다''고 적혀 있다.', False),
  (17, '비타민-의약품', '비타민B1', '루프이뇨제 장기 복용', '푸로세미드', '이뇨제(루프이뇨제: 푸로세미드, 토르세미드)', 'drug', '영양소_흡수감소_결핍', '티아민이 결핍됨. 장기 푸로세미드 치료를 받는 심부전 환자 23명 중 21명에서 결핍 지표가 높았고, 대조군은 16명 중 2명이었음. 정맥 티아민을 주자 지표가 27.0%에서 4.5%로 정상화됨. 티아민 결핍은 심부전을 악화시킬 수 있음', '푸로세미드(소변량 증가)', '루프이뇨제로 소변량이 늘면 수용성 티아민의 소변 배설이 늘어 체내 저장이 고갈됨', '라식스정(푸로세미드), 토르세미드 / 활성비타민(푸르설티아민·벤포티아민)', '심부전으로 푸로세미드를 장기 복용하는 70대가 숨참과 부종이 심해짐', 'moderate', 'monitor', '장기 복용자는 티아민 상태를 의사와 상의하고, 필요하면 보충함', '증례보고', 'medium', '소규모 파일럿 관찰연구임', True),
  (19, '비타민-의약품', '비타민B12', null, '란소프라졸', '위산 억제제(PPI·H2 차단제)', 'drug', '영양소_흡수감소_결핍', '장기간(예: 3년 이상) 매일 복용하면 음식 속 B12 흡수장애로 결핍이 생길 수 있다. 2년 이상 PPI 사용 시 B12 결핍 위험이 OR 1.65였다.', '위산·펩신 감소로 음식 단백질에서 B12가 분리되지 않음', '음식 속 B12는 위산과 펩신이 단백질에서 떼어내야 R-단백, 내인자와 결합할 수 있다. 저염산증·무위산증이면 이 단계가 막혀 흡수가 줄어든다.', '약: 란스톤캡슐·LFDT정, 넥시움정, 판토록정 등 PPI, 파모티딘 등 H2 차단제 / 영양제: 비타민B12', '위식도역류로 PPI를 5년째 먹는 70대가 기억력 저하와 손발 저림을 겪는다.', 'moderate', 'monitor', '장기 복용자에게 B12 결핍 증상이 보이면 결핍을 의심하고 측정한다. 필요하면 보충한다(결정형 B12 보충제는 위산 없이도 흡수된다).', '식약처원문', 'high', '이 행은 약이 영양소 결핍을 만드는 경우다.', False),
  (20, '비타민-의약품', '비타민B12', '메트포르민 장기·고용량 복용', '메트포르민', '당뇨병 치료제(비구아니드계)', 'drug', '영양소_흡수감소_결핍', '비타민B12 결핍이 흔하게 생김. 4.3년 RCT에서 B12가 위약 대비 평균 19% 감소했고, 결핍 절대위험이 7.2%p 늘었음(NNH 약 14). 거대적아구성빈혈과 말초신경병증이 생길 수 있으며, 당뇨병성 신경병증으로 오인되기 쉬움', '메트포르민', '메트포르민이 회장에서 칼슘에 의존하는 내인자-B12 복합체 흡수를 방해하는 것으로 알려짐. 용량과 복용 기간이 늘수록 위험이 커짐(국내 허가사항)', '글라비스정, 다이아벡스정, 글루코파지, 메트포르민 복합제(자누메트 등)', '메트포르민을 10년째 먹는 65세가 발 저림을 당뇨 합병증으로 여기고 지냄', 'moderate', 'monitor', '혈청 B12를 매년 확인하고(국내 허가사항), 결핍이면 보충함', '식약처원문', 'high', '| 다른 리서처 서술: 장기 복용 시 비타민B12 결핍(거대적혈모구빈혈, 말초신경병증 악화, 호모시스테인 상승)이 생긴다. 4.3년 RCT에서 B12 농도가 위약보다 19% 낮았고, 결핍 절대위험이 7.2%p 높았다.', True),
  (21, '비타민-의약품', '비타민B12', '위산억제제 2년 이상 장기 복용', '에스오메프라졸', '위산억제제(PPI: 오메프라졸·에스오메프라졸·란소프라졸·판토프라졸·라베프라졸, H2차단제: 파모티딘 등)', 'drug', '영양소_흡수감소_결핍', '비타민B12 결핍 위험이 커짐. 2년 이상 사용 시 PPI는 OR 1.65, H2차단제는 OR 1.25였고, PPI 1.5정/일 초과 시 OR 1.95였음', '위산·펩신 분비 억제', '음식 단백에 붙어 있는 B12는 위산과 펩신이 있어야 떨어져 나와 흡수됨. 위산억제제는 이 과정을 막아 장기 복용 시 B12를 고갈시킴', '넥시움·네메올정(에스오메프라졸), 오메프라졸, 란소프라졸, 판토프라졸, 파모티딘', '역류성식도염으로 PPI를 몇 년째 먹는 60대가 피로·빈혈·저림을 보임', 'moderate', 'monitor', '장기 복용자는 B12를 주기적으로 확인하고, 결핍이면 보충함', '식약처원문', 'high', '같은 국내 허가사항에 장기 PPI 사용 시 저마그네슘혈증 경고도 있음(미네랄 담당)', True),
  (22, '비타민-의약품', '비타민B12', '콜키신 장기 복용', '콜키신', '통풍치료제(항염)', 'drug', '영양소_흡수감소_결핍', '비타민B12 흡수불량(가역적). 콜키신으로 치료하는 가족성지중해열 환자에서 B12 결핍 사례가 더 많았음(12 vs 3)', '콜키신', '콜키신이 장 점막 기능을 바꾸고 내인자-B12 수용체를 줄여 B12 흡수를 떨어뜨림(동물에서 수용체가 용량에 비례해 가역적으로 감소)', '콜킨정(콜키신)', '통풍 예방으로 콜키신을 매일 먹는 60대 남성에게 빈혈이 생김', 'moderate', 'monitor', '장기 복용 시 B12를 확인함', '식약처원문', 'high', '| 다른 리서처 서술: 장 점막 기능 변화로 비타민B12 흡수불량(가역적)이 생긴다.', True),
  (23, '비타민-의약품', '비타민B6', '피리독신 고함량 단일제(예: 50·300mg 정) 또는 B6 고함량 복합제. 탈탄산효소억제제가 없는 레보도파 단독 요법에서 문제가 됨', '레보도파', '파킨슨병 치료제(도파민 전구체)', 'drug', '약효감소', '레보도파가 뇌에 닿기 전에 말초에서 도파민으로 대사되어 효과가 떨어지고 파킨슨 증상 조절이 나빠짐. 국내 고함량 피리독신 허가사항은 레보도파 복용자를 투여 금기로 둠', '피리독신의 활성형 PLP가 말초 도파탈탄산효소(방향족 L-아미노산 탈탄산효소)의 보조효소로 작용', 'PLP는 레보도파를 도파민으로 바꾸는 탈탄산효소의 보조인자임. B6가 많으면 장·간·혈중에서 레보도파가 빨리 도파민으로 바뀌어 혈뇌장벽을 넘는 레보도파가 줄어듦. 카르비도파·벤세라지드 같은 말초 탈탄산효소억제제가 함께 있으면 이 말초 대사가 막혀 길항이 거의 나타나지 않음', '피리독신: 뉴로비정50/300밀리그램, 고함량 비타민B 복합제 / 레보도파: 국내 단독 완제품은 검색되지 않음(원료만 있음). 복합제는 명도파정·원도파정(벤세라지드), 퍼킨씨알정·트리레보정(카르비도파)', '레보도파를 먹는 70대 파킨슨병 환자가 손저림에 좋다며 피리독신 300mg 정을 따로 사 먹음', 'major', 'avoid', '레보도파 복용자는 고함량 피리독신 단일제를 먹지 않음(국내 허가사항상 병용 금기). 탈탄산효소억제제 복합제를 먹는 경우 저용량 B6 종합비타민은 가능하지만, 고함량 제품은 반드시 의사·약사와 상의', '식약처원문', 'high', '명도파정(레보도파/벤세라지드) 허가사항은 탈탄산효소억제제와 병용하면 길항이 없어 저용량 B6 종합비타민과 함께 먹어도 된다고 적고 있음. 반면 뉴로비정(고함량 피리독신) 허가사항은 복합제를 구분하지 않고 레보도파 투여 환자를 금기로 둠. 복합제를 오래 먹으면 오히려 B6 결핍 위험이 있음(카르비도파 행 참조) | 다른 리서처 서술: 비타민B6가 레보도파 효과를 길항할 수 있다. 다만 탈탄산효소 억제제와 함께 쓰면 이 길항은 나타나지 않는다. / 피리독신이 레보도파의 말초 대사를 늘려 효과를 감소(식약처: 병용 투여하지 않음, 레보도파 투여 환자 금기).', True),
  (24, '비타민-의약품', '비타민B6', '카르비도파/레보도파를 장기간 복용하는 경우. FDA가 검토한 사례는 모두 레보도파 1일 1,000mg 초과', '카르비도파', '파킨슨병 치료제(말초 도파탈탄산효소억제제, 레보도파 복합제)', 'drug', '영양소_흡수감소_결핍', '비타민B6 결핍과 그로 인한 발작. FDA 검토에서 B6 결핍 관련 발작 14건(사망 2건)이 확인됐고, 모든 사례에서 레보도파가 하루 1,000mg을 넘었음. 경구 L-DOPA/CD 환자 18명 중 13명에서 혈장 B6가 낮았고, 78세 환자 증례에서는 B6가 측정 한계(<1 μg/dL) 아래였음', '카르비도파가 활성형 비타민B6(PLP)와 결합하고, 레보도파가 도파민으로 바뀌는 과정에서 PLP가 소모됨', 'FDA 설명에 따르면 레보도파가 도파민으로 전환될 때 B6가 소모되고, 카르비도파는 히드라진기를 통해 활성형 PLP와 결합해 B6 기능을 더 떨어뜨림. PLP가 부족하면 GABA 합성이 줄어 경련 역치가 낮아짐', '퍼킨씨알정(카르비도파/레보도파), 트리레보정(레보도파/카르비도파/엔타카폰), 해외 Sinemet·Rytary·Duopa', '카르비도파/레보도파를 하루 1,200mg 이상 수년째 먹는 70대가 갑자기 경련과 혼돈을 보임', 'major', 'monitor', '치료 시작 전과 치료 중 주기적으로 B6 수치를 확인하고, 결핍이면 의료진 판단하에 보충함(FDA 2026). 고함량 B6의 레보도파 길항 문제가 있으므로 보충 용량은 처방의가 정함', '증례보고', 'high', '2026-03-20 FDA 안전성 서한으로 미국 라벨에 경고가 추가됨. 조회 시점의 국내 퍼킨씨알정 허가사항에는 B6 결핍 경고가 없고, 피리독신으로 약효를 되돌리는 것이 효과적이지 않다는 문장만 있음. FDA 경고 대상은 카르비도파 제품이며, 벤세라지드 복합제에 같은 경고가 적용되는지는 확인하지 못함', True),
  (25, '비타민-의약품', '비타민B6', null, '이소니아지드', '항결핵제', 'drug', '영양소_흡수감소_결핍', '피리독신 결핍으로 말초신경병증(저림, 지각이상)과 경련이 생길 수 있음. 국내 허가사항 이상반응에 피리독신 결핍과 펠라그라가 있고, 신경병증이 생기면 피리독신을 투여하라고 명시함', '이소니아지드의 히드라진기가 피리독살과 결합하고 PLP 생성을 방해함', '이소니아지드는 피리독살과 히드라존을 만들어 소변으로 배설시키고, 피리독살키나아제를 방해해 활성 B6(PLP)를 고갈시킴. PLP에 의존하는 GABA 합성이 줄어 신경병증과 경련이 생김. 국내 피리독신 허가사항도 이소니아지드가 B6 요구량을 늘린다고 적음', '유한짓정100mg(이소니아지드), 결핵·잠복결핵 치료 복합 처방', '잠복결핵 치료로 이소니아지드를 9개월 먹는 60대 당뇨 환자가 발끝 저림을 호소함', 'moderate', 'monitor', '처방에 같이 나온 피리독신을 빠뜨리지 않고, 저림이나 감각이상이 생기면 바로 상담함. 과량 복용 시에는 같은 양의 피리독신을 정맥 투여함(허가사항)', '식약처원문', 'high', '같은 기전으로 나이아신 결핍(펠라그라)도 생김(별도 행) | 다른 리서처 서술: 피리독신 결핍과 말초신경병증(저림, 지각이상)이 나타날 수 있다.', False),
  (26, '비타민-의약품', '비타민B6', null, '테오필린', '기관지확장제(메틸잔틴계, 아미노필린 포함)', 'drug', '영양소_흡수감소_결핍', '혈장 PLP가 낮아짐. 테오필린을 쓰는 천식 아동은 5.3 ng/ml로 쓰지 않는 아동(9.0)보다 낮았음. 81세 증례에서 혈청 B6가 측정 한계 아래였고 테오필린 관련 발작 뒤 부분발작이 이어짐', '테오필린이 피리독살키나아제를 비경쟁적으로 억제함', '테오필린은 적혈구 피리독살키나아제를 비경쟁적으로 억제해(Ki 1.28×10^-5 mol/L) 활성형 PLP 생성을 줄임. PLP 부족은 테오필린의 경련 위험을 키울 수 있음', '테오필린 서방정, 아미노필린', '만성폐쇄성폐질환으로 테오필린을 장기 복용하는 70대에게 경련이 생김', 'moderate', 'monitor', '장기 복용 고령자는 B6 상태를 점검함. 단기 연구에서는 피리독신 10mg/일로 길항 효과가 상쇄됨', 'RCT/약동학연구', 'medium', '국내 테오필린 허가사항은 확인하지 않음', False),
  (28, '비타민-의약품', '비타민B6', '고용량 피리독신(고함량 단일제)', '페니토인', '항경련제(히단토인계. 페노바르비탈도 같은 이유로 해당)', 'drug', '약효감소', '페니토인·페노바르비탈의 효과가 약해져(혈청 농도 감소 보고) 발작 조절이 나빠질 수 있음', '고용량 피리독신(PLP)', '고용량 피리독신이 간에서 페니토인과 페노바르비탈의 대사를 촉진하는 것으로 추정됨(정확한 기전은 확립되지 않음). 1976년 Lancet 서신에서 고용량 피리독신 투여 후 두 약의 혈청 농도가 감소했다고 보고함', '페니토인: 부광페니토인캡슐, 명인페니토인정, 환인히단토인정 / 페노바르비탈: 하나페노바르비탈정 / 피리독신: 뉴로비정50·300mg', '뇌전증으로 페니토인을 먹는 60대가 신경통 완화용 고함량 B6 정제를 새로 시작함', 'moderate', 'consult', '항경련제 복용자는 고함량 B6를 시작하거나 끊을 때 의사와 상의하고, 필요하면 혈중농도를 측정함', '식약처원문', 'medium', '국내 허가사항에는 문구로만 있고 용량 기준은 없음. 원 문헌은 초록 없는 서신', True),
  (30, '비타민-의약품', '비타민B6', '고용량 피리독신', '아미오다론', '항부정맥제', 'drug', '기타', '광민감성(햇빛 과민 피부반응)이 커질 수 있음', '피리독신(자체로 광민감성 반응을 일으킬 수 있음)', '아미오다론과 피리독신 모두 광민감성 피부반응과 관련됨. 국내 허가사항에는 병용 시 광민감성이 커질 수 있다고만 적혀 있고 기전은 밝혀지지 않음', '코다론정(아미오다론) / 뉴로비정, 고함량 B6 복합제', '심방세동으로 아미오다론을 먹는 60대가 고함량 B6를 먹고 야외활동 후 심한 햇볕 발진이 생김', 'minor', 'caution', '병용 시 자외선 차단을 철저히 하고 피부반응이 생기면 상담', '식약처원문', 'low', '국내 허가사항 외 근거는 이번에 확인하지 않음', True),
  (31, '비타민-의약품', '비타민B6', null, '에티닐에스트라디올', '경구피임약·에스트로겐 제제(폐경 호르몬요법 포함)', 'drug', '영양소_흡수감소_결핍', '비타민B6 요구량이 늘고 혈중 B6가 낮아짐. 경구피임약 사용자의 B6·B12 중앙값이 비사용자보다 유의하게 낮았음(24.2 vs 32.9 nmol/l)', '에스트로겐', '에스트로겐이 트립토판-키뉴레닌 대사 등 PLP를 쓰는 경로를 활성화해 B6 요구량을 늘리는 것으로 설명됨. 국내 피리독신 허가사항에 B6 요구량을 늘리는 약으로 명시됨', '마이보라·머시론·야즈 등 경구피임약, 에스트로겐 함유 폐경 호르몬제', '폐경 호르몬제를 먹는 50대 여성이 피로·우울감을 호소함', 'minor', 'monitor', '장기 복용자는 식사·종합비타민으로 B6가 부족하지 않게 하고, 증상이 있으면 상담함', '식약처원문', 'medium', '근거 연구는 단면연구임', False),
  (35, '비타민-의약품', '비타민C', '고용량 항산화 비타민 복합(비타민C·E·베타카로틴·셀레늄)', '심바스타틴', '스타틴+나이아신 병용 지질치료', 'drug', '약효감소', '심바스타틴-나이아신 치료의 HDL 상승 효과가 둔화됨. HDL-C 증가는 25%에서 18%로, HDL2-C 증가는 42%에서 0%로 줄었고, apoA-I 증가(64%)는 항산화제 병용군에서 나타나지 않았음', '항산화 비타민 복합(비타민C 포함)', '항산화제가 나이아신·스타틴의 HDL 대사 반응(apoA-I, HDL2 증가)을 막는 것으로 보이나 정확한 기전은 밝혀지지 않음', '심바스타틴·아토르바스타틴과 나이아신 병용 / 고용량 항산화 복합 영양제', '관상동맥질환으로 스타틴과 나이아신을 먹는 60대가 고용량 항산화 복합 영양제를 추가함', 'moderate', 'caution', '지질치료 중 고용량 항산화 복합제는 의사와 상의', 'RCT/약동학연구', 'medium', 'HATS 연구. 비타민C 단독 효과는 분리되지 않음', True),
  (36, '비타민-의약품', '비타민C', '고용량(국내 주사제 허가사항은 ''고용량 투여 시'', 증례는 g 단위 복용)', '와파린', '경구 항응고제(쿠마린계)', 'drug', '약효감소', '항응고 반응이 약해져 INR이 떨어지고 혈전 위험이 생김. 증례에서는 와파린을 6mg에서 10mg으로 올려도 INR이 치료범위에 못 미쳤고, 다른 증례에서는 비타민C를 끊은 뒤 INR이 입원 10일째 15.4까지 급상승함', '고용량 아스코르브산', '기전은 분명하지 않음. 고용량 비타민C가 와파린의 흡수나 반응을 떨어뜨리는 것으로 추정됨. 식이 수준의 혈장 비타민C는 영향이 없다는 연구도 있음', '쿠파린정·제일와파린정 / 비타민C 1000mg 정, 메리트씨주 등 고용량 비타민C 주사', '와파린을 먹는 70대가 감기 예방으로 비타민C를 하루 2~3g씩 먹다가 INR이 떨어지고, 갑자기 끊자 INR이 급등함', 'moderate', 'monitor', '고용량 비타민C를 시작·중단할 때 INR을 확인하고, 먹는다면 용량을 일정하게 유지함', '식약처원문', 'medium', '국내 와파린(쿠파린정) 허가사항에는 ''비타민 C 결핍''이 항응고 작용을 바꾸는 인자로 적혀 있음. 근거는 증례 위주이고 상반된 연구(16139332)가 있음 | 다른 리서처 서술: 경구 항응고제의 반응을 약화시킬 수 있음(식약처) → 혈전 예방 효과 저하 가능.', True),
  (39, '비타민-의약품', '비타민C', '고용량 비타민C(1000 mg 정제)', '아스피린', '살리실산염(아스피린) 외 원문 열거: 철분제, 페니토인 등 항전간제, 에스트로겐 함유 경구피임약, 테트라사이클린계, 플루페나진, 오르리스타트', 'drug', '기타', '''바람직하지 않은 상호작용''이 생길 수 있다(원문은 구체적 결과를 적지 않음).', '고용량 아스코르브산(요 산성화·흡수·배설 경쟁)', '제시되는 기전: 아스피린은 비타민C의 세포 흡수를 줄이고 소변 배설을 늘린다. 고용량 비타민C는 소변을 산성화해 살리실산 재흡수를 늘릴 수 있다. 원문에는 기전 설명이 없다.', '영양제: 유한비타민씨정1000mg, 종근당비타민씨골드정1000밀리그램, 고려은단 비타민C 1000 / 약: 아스피린프로텍트정100밀리그람(기존 목록 품목)', '심혈관 예방으로 저용량 아스피린을 먹는 60대가 비타민C 1000 mg을 하루 2~3알씩 먹는다.', 'minor', 'consult', '원문에 열거된 약을 먹고 있다면 고용량 비타민C를 먹기 전에 의사·약사와 상의한다.', '식약처원문', 'low', '원문은 한 문장에 여러 약을 묶어 ''상의할 것''으로 처리했다. 개별 상호작용의 임상 근거는 대체로 약하며, 이 행은 대표로 아스피린을 적었다. 철분제와의 관계는 흡수 증가 방향이다(별도 행 참조). | 다른 리서처 서술: 국내 허가사항에 ''바람직하지 않은 상호작용''으로만 적혀 있고, 구체적인 결과는 나와 있지 않음', True),
  (40, '비타민-의약품', '비타민C', '고용량(1g 수준)', '에티닐에스트라디올', '경구피임약·에스트로겐 제제', 'drug', '약효증가_독성', '에티닐에스트라디올 생체이용률이 늘어 에스트로겐 부작용이 커질 수 있음. 국내 허가사항에는 ''바람직하지 않은 상호작용''으로 적혀 있음', '아스코르브산', '장벽에서 황산포합을 두고 경쟁해 에스트로겐의 초회통과 대사를 줄이는 것으로 추정됨(1981년 소규모 RCT)', '경구피임약(마이보라, 야즈 등), 에스트로겐 함유 호르몬제 / 비타민C 1000mg', '에스트로겐 호르몬제를 먹는 50대가 비타민C 1g을 같이 먹음', 'minor', 'caution', '고용량을 새로 시작할 때는 약사와 상의함', '식약처원문', 'low', '근거가 오래되고 소규모임', True),
  (42, '비타민-의약품', '비타민C', null, '프레드니솔론', '코르티코스테로이드', 'drug', '영양소_흡수감소_결핍', '비타민C의 산화가 늘어 체내 비타민C가 줄어들 수 있음', '코르티코스테로이드', '국내 허가사항은 코르티코스테로이드가 비타민C의 산화를 증가시킨다고만 적고 있음', '프레드니솔론정 등 경구 스테로이드', '류마티스 질환으로 스테로이드를 장기 복용하는 60대', 'minor', 'monitor', '식사로 비타민C를 충분히 섭취함', '식약처원문', 'low', null, False),
  (43, '비타민-의약품', '비타민D', '처방 활성형 비타민D를 먹으면서 일반 비타민D 영양제·고용량 비타민D 의약품을 추가로 먹는 경우(중복)', '알파칼시돌', '활성형 비타민D 제제(알파칼시돌, 칼시트리올)', 'drug', '영양소_과잉_독성', '효과가 더해져 고칼슘혈증과 비타민D 독성이 생길 수 있다. 증상은 구역, 구토, 다뇨, 갈증, 변비, 무기력이며, 장기적으로 혈관·장기 석회화와 신장결석이 생긴다.', '콜레칼시페롤(비타민D3)과 활성형 비타민D가 함께 장 칼슘 흡수를 늘린다.', '알파칼시돌은 간에서 바로 활성형(1,25-디히드록시비타민D)이 되어 장 칼슘 흡수를 강하게 늘린다. 여기에 비타민D 영양제가 더해지면 비타민D 총량과 칼슘 흡수가 과해진다.', '알파칼시돌: 원알파·네오칼시돌 등, 칼시트리올: 본키 등 / 비타민D3 영양제, 칼슘+D 복합제, 메가디쓰리·디맥정(고용량 비타민D 의약품)', '골다공증으로 알파칼시돌을 처방받은 70대 여성에게 자녀가 비타민D 5000IU 영양제를 사드려 함께 먹는다.', 'major', 'avoid', '처방의가 의도적으로 함께 쓰는 경우가 아니라면 비타민D 영양제를 따로 먹지 않는다. 함께 쓰면 혈청·소변 칼슘을 모니터링한다.', '식약처원문', 'high', '알파칼시돌 허가사항은 ''이 약을 복용하는 동안 다음의 약을 복용하지 말 것'' 항목에 비타민D와 그 유도체를 넣고 있다. 콜레칼시페롤 허가사항도 다른 비타민D 의약품과 함께 쓸 때 총 용량을 고려하라고 한다. | 다른 리서처 서술: 상가작용으로 고칼슘혈증(구역·구토·다뇨·신기능 저하·부정맥). 식약처 허가사항은 복용하지 말 것으로 명시.', True),
  (44, '비타민-의약품', '비타민D', '비타민D(콜레칼시페롤·에르고칼시페롤) 및 유도체 보충제', '칼시트리올', '활성형 비타민D 제제(칼시트리올·알파칼시돌)', 'drug', '영양소_과잉_독성', '상가작용으로 고칼슘혈증(비타민D 중독: 구역, 다뇨, 신기능 저하, 석회화)이 나타날 수 있다.', '비타민D 보충제와 활성형 비타민D 약물의 작용 중복', '칼시트리올은 비타민D3의 최종 활성형이다. 보충제 비타민D가 더해지면 비타민D 수용체 자극이 중복되어 장 칼슘·인 흡수와 뼈 흡수가 과도해진다.', '약: 로칼트롤연질캡슐, 원알파정 / 영양제: 비타민D 1000~5000 IU 건강기능식품, 비타민D 함유 칼슘제(디카맥스1000정, 칼트레이트디400정)', '신장질환으로 로칼트롤을 먹는 65세가 비타민D 고함량 영양제를 따로 먹는다.', 'major', 'avoid', '활성형 비타민D 복용 중에는 비타민D 보충제를 임의로 함께 먹지 않는다. 필요하면 처방의가 조정한다.', '식약처원문', 'high', '대상 사용자(골다공증 약 복용 50~60대)에서 흔한 중복이다.', False),
  (45, '비타민-의약품', '비타민D', '고용량 비타민D 보충으로 혈청 칼슘이 오르는 경우', '디곡신', '강심배당체(디기탈리스)', 'drug', '약효증가_독성', '고칼슘혈증이 생기면 디기탈리스 독성과 심각한 부정맥 위험이 커진다(허가사항). 디곡신 병용이나 심장질환이 있으면 고칼슘혈증의 부정맥 유발 효과가 강해질 수 있다(Vella 1999).', '비타민D로 인한 혈청 칼슘 상승. 칼슘 이온이 심근 수축과 흥분성을 더 높인다.', '디곡신은 Na+/K+-ATPase를 억제해 심근세포 안 칼슘을 늘린다. 비타민D 과잉으로 혈중 칼슘까지 오르면 세포 안 칼슘 과부하가 커져 지연후탈분극과 부정맥이 잘 생긴다.', '디고신정(디곡신) / 비타민D3 고함량 영양제, 메가디쓰리정 25000IU, 알파칼시돌', '심부전으로 디곡신을 먹는 70대가 비타민D 5000IU와 칼슘제를 매일 추가로 먹다가 두근거림과 구역을 겪는다.', 'moderate', 'monitor', '디곡신 복용자는 고용량 비타민D를 먹기 전에 의사와 상의하고, 혈청 칼슘·심전도·디곡신 농도를 확인한다.', '식약처원문', 'medium', '디곡신 허가사항에는 고칼슘혈증 환자 주의와 칼슘제 병용 주의가 있고, DUR에는 글루콘산칼슘·염화칼슘 주사[디곡신] 병용금기가 있다. 일반 용량 비타민D(1000IU 안팎)로 문제가 될 가능성은 낮다.', True),
  (47, '비타민-의약품', '비타민D', null, '오를리스타트', '비만치료제(리파아제 억제제)', 'drug', '영양소_흡수감소_결핍', '비타민D 흡수가 줄어 혈중 비타민D가 낮아질 수 있다. 1~2년 치료 중 보충제를 먹지 않은 성인에서 저비타민D 빈도는 12.0%(위약 6.6%)였다.', '오를리스타트의 지방 흡수 차단', '콜레칼시페롤은 지용성이라 식이 지방과 함께 흡수된다. 리파아제가 억제되면 흡수가 줄어든다.', '약: 제니칼캡슐120밀리그램 / 영양제: 비타민D 건강기능식품, 디카맥스1000정, 칼트레이트디400정', '골감소증으로 비타민D를 먹는 50대 여성이 제니칼을 시작한 뒤 몇 달 만에 25(OH)D가 떨어진다.', 'moderate', 'separate_timing', '지용성 비타민 함유 종합비타민을 먹고, 오를리스타트와 최소 2시간 간격(취침 전 등)을 둔다. 장기 복용 시 비타민D 수치를 확인한다.', '식약처원문', 'high', '포사맥스플러스디정 허가사항도 오르리스타트를 콜레칼시페롤 흡수 저해 약물로 적고 ''비타민 D의 추가적인 보충을 고려''하라고 한다. | 다른 리서처 서술: 비타민 보충을 하지 않은 성인에서 2회 이상 연속 저혈중 비타민D 비율은 위약 6.6%, 오를리스타트 12.0%였다. 청소년에서는 1개월 만에 평균 비타민D 농도가 기저보다 유의하게 감소했다(p<0.02).', False),
  (49, '비타민-의약품', '비타민D', '효소유도 항경련제를 오래 복용하는 경우(보충 비타민D의 효과 감소, 결핍)', '페니토인', '효소유도 항경련제(페니토인, 카르바마제핀, 페노바르비탈 등 바르비탈계)', 'drug', '영양소_흡수감소_결핍', '비타민D 대사가 빨라져 작용이 줄고, 오래 쓰면 구루병·골연화증·저칼슘혈증이 생길 수 있다. 메타분석에서 카르바마제핀 복용자의 25(OH)D 평균은 21.8 ng/mL로 대조군 28.0 ng/mL보다 낮았다(가중 평균차 4.00 ng/mL).', '페니토인·카르바마제핀·페노바르비탈. 간 CYP 효소(CYP3A4, CYP24A1 등)를 유도한다.', '효소유도 항경련제는 간 대사효소를 늘려 비타민D와 25(OH)D를 비활성 대사물로 빠르게 분해한다. 그 결과 혈중 비타민D가 낮아지고 칼슘 흡수가 줄어 뼈가 약해진다.', '히단토인정·다이란틴(페니토인), 테그레톨(카르바마제핀), 페노바르비탈정 / 비타민D3', '뇌전증으로 페니토인을 수십 년째 먹는 60대 여성이 골밀도 검사에서 골감소증 진단을 받는다.', 'moderate', 'monitor', '장기 복용자는 25(OH)D와 골밀도를 확인하고, 필요하면 의사가 보충 용량을 늘린다. 혈청 칼슘·ALP 이상 시 비타민D 투여를 검토한다(허가사항).', '식약처원문', 'high', '알파칼시돌 허가사항에도 ''바르비탈계 약물 또는 항전간제를 복용 중인 환자(용량의 증가가 필요할 수 있다.)''가 있다. 페노바르비탈 허가사항에도 비타민D 섭취 주의가 있다. | 다른 리서처 서술: 장기 복용 시 비타민D 분해가 빨라져 구루병·골연화증, 혈청 칼슘·무기인 저하, ALP 상승이 생길 수 있다.', False),
  (50, '비타민-의약품', '비타민D', '전신 스테로이드를 장기 복용하는 경우(보충 비타민D 효과 감소, 결핍)', '프레드니솔론', '전신 글루코코르티코이드(프레드니솔론, 메틸프레드니솔론, 덱사메타손)', 'drug', '영양소_흡수감소_결핍', '비타민D 효과가 줄고 결핍이 흔해진다. 미국 NHANES에서 스테로이드 사용자의 11%가 25(OH)D 10 ng/mL 미만으로, 비사용자 5%보다 많았다(교차비 2.36). 스테로이드 골다공증 위험이 더해진다.', '글루코코르티코이드. 비타민D 분해효소(24-수산화효소)를 유도하고 장 칼슘 흡수를 억제한다.', '스테로이드는 비타민D를 비활성화하는 효소를 늘리고, 장에서 비타민D 의존 칼슘 흡수를 직접 방해한다. 그래서 같은 양의 비타민D를 먹어도 효과가 떨어진다.', '소론도정(프레드니솔론), 메드롤정(메틸프레드니솔론) / 비타민D3, 칼슘+D', '류마티스질환으로 프레드니솔론을 1년 넘게 먹는 60대 여성이 비타민D를 먹는데도 25(OH)D가 낮게 나온다.', 'moderate', 'monitor', '장기 스테로이드 복용자는 25(OH)D와 골밀도를 확인하고, 의사 판단으로 비타민D·칼슘 용량을 조정한다.', '식약처원문', 'medium', '''함께 먹으면 나쁘다''기보다 ''스테로이드가 비타민D를 소모시켜 보충이 더 필요하다''는 맥락이다. 앱에서는 결핍 주의로 표시하는 것이 맞다.', True),
  (51, '비타민-의약품', '비타민D', '고용량 비타민D 보충, 특히 칼슘과 함께 먹는 경우', '히드로클로로티아지드', '티아지드계 이뇨제(ARB·ACE억제제 복합 혈압약 포함, 클로르탈리돈·인다파미드 유사계열)', 'drug', '약효증가_독성', '혈청 칼슘이 올라 고칼슘혈증이 생길 수 있다. 증상은 구역, 변비, 다뇨, 무기력, 혼동이며 심하면 부정맥·신장결석이 생긴다. 지역사회 연구에서 티아지드 관련 고칼슘혈증 발생률은 인구 10만 명당 7.7명이었다. 고령자에서 비타민D와 티아지드 병용 후 고칼슘혈증이 생긴 보고가 있다.', '비타민D(장 칼슘 흡수 증가)와 티아지드(신장 칼슘 재흡수 증가)', '비타민D는 장에서 칼슘 흡수를 늘린다. 티아지드계 이뇨제는 원위세뇨관에서 칼슘 재흡수를 늘려 소변으로 빠지는 칼슘을 줄인다. 들어오는 칼슘은 늘고 나가는 칼슘은 줄어 혈청 칼슘이 쌓인다.', '혈압약: 코디오반·네오반플러스(발사르탄/HCTZ), 아타칸플러스(칸데사르탄/HCTZ), 다이크로진(HCTZ), 후루덱스(인다파미드) / 영양제: 비타민D3 1000~5000IU, 칼슘+비타민D 복합제, 의약품 고용량 비타민D(메가디쓰리정 25000IU 등)', '발사르탄/히드로클로로티아지드 복합 혈압약을 먹는 60대 여성이 골다공증 예방으로 칼슘+비타민D와 고용량 비타민D를 함께 먹는다.', 'moderate', 'monitor', '티아지드 복용자가 고용량 비타민D나 칼슘을 먹을 때는 혈청 칼슘을 정기적으로 확인한다. 고용량 주사·정제 비타민D는 의사와 상의한다.', '식약처원문', 'high', '티아지드 관련 고칼슘혈증 환자의 상당수(2016 연구 24%)에서 원발성 부갑상선기능항진증이 나중에 진단됐다. 칼슘 단독 조합은 미네랄 담당 영역이다. | 다른 리서처 서술: 고칼슘혈증 위험 증가. 식약처 콜레칼시페롤 허가사항은 벤조티아디아진 유도체(티아지드)를 복용하지 말 것 항목에, 알파칼시돌 허가사항은 치아지드계 이뇨제를 고칼슘혈증 위험 증가로 명시.', True),
  (54, '비타민-의약품', '비타민D', '비타민D 800IU/일 보충(연구 조건)', '아토르바스타틴', 'CYP3A4 대사 스타틴(아토르바스타틴, 심바스타틴)', 'drug', '약효감소', '비타민D 800IU를 6주간 보충하자 아토르바스타틴과 활성대사체의 혈중농도가 감소했다(P<0.001). 그러나 LDL·총콜레스테롤은 오히려 낮아져 약효 감소는 나타나지 않았다.', '비타민D(25-OH 대사체). 장·간의 CYP3A4를 유도하는 것으로 추정된다.', '비타민D가 VDR을 통해 CYP3A4 발현을 늘려 아토르바스타틴 대사를 빠르게 할 수 있다. 다만 같은 연구에서 콜레스테롤 강하 효과는 유지되거나 더 좋아져, 임상적 의미는 불분명하다.', '리피토(아토르바스타틴), 조코(심바스타틴) / 비타민D3 800~1000IU', '고지혈증으로 아토르바스타틴을 먹는 60대가 비타민D 영양제를 시작한다.', 'minor', 'monitor', '함께 먹어도 되지만, 정기 지질검사로 LDL 조절이 유지되는지 확인한다.', 'RCT/약동학연구', 'low', '약동학적으로는 농도가 감소하지만 임상 결과는 반대 방향(LDL 추가 감소)이었다. ''나쁜 조합''으로 단정하기 어렵고, 낮은 우선순위로 표시하는 것이 좋다.', True),
  (56, '비타민-의약품', '비타민D', '이소니아지드를 복용하는 기간', '이소니아지드', '항결핵제(간 효소 억제)', 'drug', '영양소_흡수감소_결핍', '건강인에서 이소니아지드 투여 후 가장 활성이 큰 비타민D 대사물인 1,25-디히드록시비타민D가 47% 떨어지고, 부갑상선호르몬이 36% 올랐다.', '이소니아지드. 간 수산화효소를 억제한다.', '이소니아지드는 간 모노옥시게나제를 억제해 비타민D가 25-수산화·1-알파 수산화로 활성화되는 과정을 방해하는 것으로 보고됐다. 그 결과 활성형 비타민D가 줄고 PTH가 보상적으로 오른다.', '유한짓정(이소니아지드), 리팜피신·이소니아지드 복합제 / 비타민D3', '잠복결핵으로 이소니아지드를 9개월 먹는 50대가 골다공증 치료 중이다.', 'minor', 'monitor', '치료 기간이 길거나 골다공증이 있으면 비타민D와 칼슘 상태를 의사와 확인한다.', 'RCT/약동학연구', 'low', '소규모 건강인 연구다. 리팜피신과 기전이 달라(억제 대 유도) 행을 나눴다.', False),
  (57, '비타민-의약품', '비타민E', '고용량 비타민E 단일제(예: 400IU 연질캡슐)를 매일 복용하는 경우. 출처에 위험 용량 기준은 명시돼 있지 않다.', '와파린', '경구 항응고제', 'drug', '출혈위험', '항응고 반응이 커져 멍·잇몸출혈·위장출혈 등 출혈 위험이 늘 수 있다. 와파린을 먹는 비판막성 심방세동 환자에서 혈청 비타민E 농도가 출혈 사건을 예측했다(Pastori 2013). 1974년에는 비타민E 복용과 관련된 응고장애 증례가 보고됐다. 반면 와파린 환자에게 비타민E를 준 소규모 연구에서는 INR이 유의하게 변하지 않았다(Kim & White 1996).', '알파-토코페롤. 비타민K 작용을 방해하고 혈소판 응집을 억제한다.', '고용량 비타민E는 비타민K의 흡수와 작용을 방해해 비타민K 의존 응고인자의 활성을 떨어뜨릴 수 있다(국내 허가사항 기재). 알파-토코페롤은 혈소판 응집도 억제한다. 와파린의 응고인자 억제와 겹치면 지혈 능력이 더 약해진다.', '비타민E: 그랑페롤연질캡슐400아이유(유한양행, 일반의약품), 토코페롤 건강기능식품, 고함량 종합비타민 / 와파린: 쿠파린정', '와파린을 먹는 70대가 ''혈행 개선''용 비타민E 400IU를 매일 먹은 뒤 멍과 잇몸출혈이 잦아진다.', 'major', 'consult', '복용 전 의사·약사와 상의한다. 시작한 뒤에는 INR과 출혈 징후(멍, 잇몸출혈, 흑변)를 확인한다. 고용량 단일제는 피하는 편이 안전하다.', '식약처원문', 'high', '근거가 엇갈린다. INR 자체는 크게 변하지 않을 수 있지만 혈소판 기능 억제로 출혈 위험이 늘 수 있다는 해석이 있다. 2010년 식약청 보도자료도 와파린 복용자는 비타민E를 먹기 전에 상의하라고 안내한다. Corrigan 1974는 초록이 없어 제목만 확인했다. | 다른 리서처 서술: 항응고제의 반응이 커져 출혈 경향(멍, 잇몸·코피, 드물게 중대 출혈)이 증가할 수 있다. 1000 IU/일 12주 투여 시 비타민K 결핍 지표인 PIVKA-II가 1.7에서 11.9 ng/mL로 상승했다(항응고제 비복용 성인). / 항응고제 반응 상승(식약처) → 출혈 위험. 고용량 비타민E는 비타민K 상태 지표(PIVKA-II)를 높임.', True),
  (61, '비타민-의약품', '비타민E', '항산화 복합 보충제(비타민E, 비타민C, 베타카로틴, 셀레늄). 용량은 원문 본문 기준으로 확인하지 못했다.', '심바스타틴', '스타틴+나이아신 병용 지질치료', 'drug', '약효감소', 'HATS 연구에서 항산화제를 함께 먹으면 심바스타틴-나이아신의 HDL2 상승 효과가 사라졌다(HDL2-C 증가 42% 대 0%). 임상사건은 심바스타틴-나이아신 단독군 3%, 심바스타틴-나이아신+항산화제군 14%였다.', '비타민E 등 항산화 복합제', '항산화제가 나이아신에 의한 HDL2와 아포A-I 상승 반응을 둔화시킨 것으로 보고됐다. 정확한 기전은 밝혀지지 않았다. 지질 개선 효과가 줄면서 관상동맥 협착 퇴행 효과도 약해졌다.', '조코(심바스타틴)+나이아신 서방형 / 항산화 복합 영양제(비타민E·C·베타카로틴·셀레늄)', '관상동맥질환으로 스타틴과 나이아신을 먹는 60대가 항산화 복합 영양제를 함께 먹는다.', 'moderate', 'consult', '지질치료 중 항산화 복합제를 먹고 있다면 의사에게 알리고 지질검사로 효과를 확인한다.', 'RCT/약동학연구', 'medium', '나이아신 병용이 핵심 조건이라 스타틴 단독 복용자에게 그대로 일반화하기는 어렵다. 국내에서 나이아신 처방은 드물다. 같은 근거로 베타카로틴·셀레늄도 해당한다.', False),
  (62, '비타민-의약품', '비타민E', '고용량 알파-토코페롤 보충제를 장기 복용하는 경우', '아스피린', '항혈소판제(아스피린, 클로피도그렐, 실로스타졸 등)', 'drug', '출혈위험', '출혈 경향이 더해진다. 알파-토코페롤 보충과 아스피린을 함께 쓴 사람에서 잇몸출혈 경향이 늘었다(Liede 1998). 비타민E 보충 RCT 메타분석에서는 출혈성 뇌졸중 위험이 증가했다(통합 상대위험 1.22, 95% CI 1.00~1.48). 다만 TIA 환자에서 아스피린+비타민E와 아스피린 단독을 비교한 시험에서는 출혈성 뇌졸중 발생에 유의한 차이가 없었다.', '알파-토코페롤. 단백질키나제C 의존 경로로 혈소판 응집을 억제한다.', '알파-토코페롤이 혈소판에 들어가면 단백질키나제C 활성화를 막아 혈소판 응집이 줄어든다. 아스피린(COX-1 억제)이나 클로피도그렐(P2Y12 억제)과 효과가 겹쳐 지혈이 더 약해진다.', '항혈소판제: 아스피린프로텍트·아스트릭스(아스피린 100mg), 플라빅스(클로피도그렐), 프레탈(실로스타졸) / 비타민E: 그랑페롤 400IU, 토코페롤 건강기능식품', '스텐트 시술 뒤 아스피린과 클로피도그렐을 먹는 60대가 비타민E 고함량 영양제를 추가로 먹는다.', 'moderate', 'caution', '수백 IU 이상 고용량 단일제는 피하거나 의사와 상의한다. 멍, 잇몸출혈, 흑변을 살핀다. 수술이나 시술 전에는 복용 중단 여부를 상의한다.', 'RCT/약동학연구', 'medium', '클로피도그렐·실로스타졸과 직접 비교한 연구는 찾지 못했다. 이 약들은 같은 항혈소판 기전이라 함께 묶었고, 근거는 기전상 추정이다. Liede 1998은 ATBC 시험 참가자를 대상으로 한 하위연구다.', True),
  (63, '비타민-의약품', '비타민E', '초산 토코페롤 보충제를 오를리스타트와 동시 복용', '오를리스타트', '비만치료제(위장관 리파아제 억제제)', 'drug', '영양소_흡수감소_결핍', '오를리스타트가 초산 비타민E 보충제 흡수를 약 60% 저해했다. 1~2년 치료 중 보충제를 먹지 않은 성인에서 저비타민E 빈도는 5.8%(위약 1.0%)였다.', '오를리스타트가 지방 소화를 막아 지용성 비타민E의 미셀 흡수를 감소', '오를리스타트는 위·췌장 리파아제를 억제해 식이 지방의 약 30%를 흡수되지 않게 한다. 지방과 함께 미셀로 흡수되는 지용성 비타민도 함께 대변으로 빠져나간다.', '약: 제니칼캡슐120밀리그램 / 영양제: 그랑페롤, 비타민E 함유 종합비타민', '제니칼을 식사 때 먹는 50대가 비타민E 영양제도 같은 끼니에 먹어 흡수가 크게 줄어든다.', 'moderate', 'separate_timing', '비타민 보충제는 1일 1회, 오를리스타트 복용 최소 2시간 전 또는 취침 시처럼 최소 2시간 후에 먹는다(제니칼 허가사항).', '식약처원문', 'high', '그랑페롤 허가사항도 오르리스타트·광유성 사하제 복용자에게 ''이 약의 흡수를 저해할 수 있다''며 상의를 권고한다. | 다른 리서처 서술: 초산 비타민E 흡수가 약 60% 줄었다(허가사항). 건강인 연구에서도 Cmax 기준 약 43%, AUC 기준 약 60% 감소했다. 비타민 보충을 하지 않은 성인에서 저혈중 비타민E 비율은 위약 1.0%, 오를리스타트 5.8%였다.', False),
  (64, '비타민-의약품', '비타민E', '비타민E 의약품·보충제를 먹는 경우(용량 기준은 출처에 없음)', '에티닐에스트라디올', '에스트로겐 함유 경구피임약', 'drug', '기타', '국내 허가사항은 혈전증 발생 위험이 늘 수 있다고 적고 있다. 2010년 식약청 보도자료는 비타민E가 피임약 효능을 떨어뜨릴 수 있다고 안내한다.', '비타민E(토코페롤)', '국내 문서에 기전 설명은 없다. 혈전 소인이 있는 사람에서의 위험과 피임 효과 감소 가능성을 함께 경고하고 있다(이론적).', '경구피임약: 머시론, 야즈 등 / 그랑페롤 400IU, 비타민E 영양제', '경구피임약을 먹는 30대 딸이 갱년기 영양제 세트에 든 비타민E를 함께 먹는다.', 'minor', 'consult', '에스트로겐 피임약을 먹는 사람이나 혈전 병력·소인이 있는 사람은 비타민E 복용 전 의사·약사와 상의한다.', '식약처원문', 'low', '식약처 문서끼리 위험의 내용(혈전 위험 대 효능 감소)이 서로 다르다. 이를 뒷받침하는 임상논문은 찾지 못했다. 폐경 호르몬요법은 출처에 언급이 없다.', False),
  (66, '비타민-의약품', '비타민K', '비타민K1(필로퀴논) 보충제·비타민K 함유 종합비타민, 비타민K2(MK-7 낫토 유래, 메나테트레논) 보충제. 매일 먹는 양이 갑자기 바뀌는 경우(새로 시작하거나 중단할 때)', '와파린', '비타민K 길항 경구 항응고제', 'drug', '약효감소', 'INR이 떨어져 와파린 효과가 약해지고, 그만큼 혈전·뇌졸중 위험이 커진다. 건강인 연구에서 비타민K1은 하루 150µg부터 INR을 유의하게 낮췄고, 참가자의 25%에서는 임상적으로 의미 있는 변화였다. MK-7은 하루 45µg에서 INR 집단평균을 약 40% 낮췄다. 비타민K1 25µg이 든 종합비타민을 시작하거나 끊은 뒤 INR이 크게 떨어지거나 오른 환자 3명의 보고도 있다.', '비타민K1·K2. 간에서 응고인자 II·VII·IX·X를 활성화(감마-카르복실화)하는 보조인자로 쓰인다.', '와파린은 비타민K 에폭사이드 환원효소를 막아 활성형 비타민K가 재순환되지 못하게 하고, 그 결과 응고인자 생성을 줄인다. 보충제로 비타민K가 더 들어오면 이 차단을 우회해 응고인자가 다시 만들어지므로 INR이 내려간다. MK-7은 반감기가 길어 적은 양으로도 영향이 크다.', '와파린: 쿠파린정(하나제약), 와파린정 / 영양제: 비타민K2(MK-7) 단일제, 낫토 추출 K2, 칼슘+비타민D+K2 복합제, 비타민K 함유 종합비타민 / 의약품 K2: 메나테트레논(골다공증약)', '심방세동으로 와파린을 먹는 65세가 뼈 건강용 ''칼슘+D+K2'' 영양제를 새로 시작한 뒤 INR이 목표치 아래로 떨어진다.', 'major', 'consult', '영양제를 새로 시작하거나 끊기 전에 담당의·약사와 상의하고, 바꾼 뒤 1~2주 안에 INR을 다시 잰다. 녹색채소 등 비타민K 섭취는 끊지 말고 매일 비슷한 양으로 유지한다. 의약품 메나테트레논은 DUR 병용금기다.', '식약처원문', 'high', '식약처 DUR에 ''메나테트레논[와파린] 병용금기''가 등재돼 있다. 2020년 건강기능식품 기준·규격 개정(제2020-92호)에서 비타민K 섭취 시 주의사항이 신설됐다는 사실은 확인했으나, 주의 문구 원문(HWP 첨부)은 확인하지 못했다. Kurnik 2003은 혈중 비타민K가 매우 낮은 환자(179명 중 22명, 12%)가 소량 보충에도 민감하다고 보고했다. DOAC(리바록사반·아픽사반 등)는 비타민K 길항 기전이 아니어서 이 상호작용에 해당하지 않는다. | 다른 리서처 서술: 와파린의 항응고 효과가 약해져 INR이 떨어지고 혈전·색전 위험이 커진다. 건강인 연구에서는 비타민K1 150 µg/일부터 INR이 유의하게 낮아졌고, 참여자의 25%에서 임상적으로 의미 있는 변화가 나타났다.', False),
  (68, '비타민-의약품', '비타민K', '와파린을 안정적으로 복용하던 사람이 오를리스타트를 새로 시작하는 경우', '오를리스타트', '지방흡수 억제 비만치료제', 'drug', '영양소_흡수감소_결핍', '비타민K 흡수가 줄어 혈중 비타민K가 감소하는 경향을 보였다. 와파린 등 경구 항응고제와 함께 쓴 환자에서 프로트롬빈 감소, INR 상승, 불안정한 항응고 효과가 보고됐다.', '오를리스타트. 리파아제를 억제해 지용성 비타민K 흡수를 줄인다.', '지방 흡수를 막으면 음식·보충제의 비타민K도 덜 흡수된다. 와파린 복용자에서는 비타민K가 줄어 INR이 올라가고 출혈 위험이 생길 수 있다.', '제니칼캡슐120mg / 쿠파린정(와파린) / 비타민K 함유 종합비타민', '와파린을 먹는 60대가 체중 감량을 위해 오를리스타트를 시작한 뒤 INR이 불안정해진다.', 'moderate', 'monitor', '와파린 복용자가 오를리스타트를 시작하면 혈액응고 수치(INR)를 자주 확인한다. 종합비타민은 오를리스타트 복용 2시간 전후로 일정하게 먹는다.', '식약처원문', 'high', '건강인 12명 연구에서는 와파린 약동학·약력학 변화가 없었다. 위험은 장기 복용자의 비타민K 상태 변화에서 나온다.', False),
  (70, '비타민-의약품', '비타민K', '임신 중 효소유도 항경련제를 복용하는 산모(신생아 비타민K 결핍)', '페노바르비탈', '효소유도 항경련제(페노바르비탈, 페니토인, 카르바마제핀)', 'drug', '영양소_흡수감소_결핍', '임신 중 복용하면 신생아에게 출혈 경향이 나타날 수 있다. 분만 전 산모와 신생아에게 비타민K1 예방 투여가 권고된다.', '페노바르비탈 등. 간 효소를 유도해 비타민K 대사를 늘린다.', '효소유도 항경련제는 태반을 통과해 태아 간의 비타민K 대사를 촉진하고, 비타민K 의존 응고인자를 줄인다. 그 결과 신생아 출혈성 질환 위험이 커진다.', '페노바르비탈정(하나제약), 히단토인정, 테그레톨', '뇌전증으로 페노바르비탈을 먹는 30대 딸이 임신해 분만을 앞두고 있다.', 'moderate', 'consult', '임신 계획·임신 중이면 신경과·산과 의사와 상의해 분만 전 비타민K1 예방 투여와 신생아 관찰을 계획한다.', '식약처원문', 'medium', '50~60대 본인보다는 자녀(임신부) 상황에 해당한다. 같은 허가사항에 엽산 보충 권고도 있다(수용성 비타민 담당 영역).', False),
  (71, '비타민-의약품', '비타민B9(엽산)', '엽산 함유 비타민제나 엽산 유도체. 특히 항암 목적의 고용량 메토트렉세이트 치료 중', '메토트렉세이트', '항엽산제(항암제·면역억제제)', 'drug', '약효감소', '메토트렉세이트의 효능이 줄어들 수 있음(국내 허가사항)', '외부에서 들어온 엽산(폴산)과 엽산 유도체', '메토트렉세이트는 디히드로엽산환원효소(DHFR)를 억제해 세포 안 활성 엽산을 고갈시키고, 이로써 암세포와 면역세포 증식을 막음. 엽산이 추가로 공급되면 이 고갈이 일부 상쇄되어 약효가 떨어질 수 있음', '유한메토트렉세이트정, 엠티엑스주, 메토젝트주 / 종합비타민, 일동폴산정1밀리그램 등 엽산제', '림프종으로 고용량 메토트렉세이트 항암치료 중인 60대에게 가족이 종합비타민을 챙겨줌', 'major', 'consult', '항암 목적 치료 중에는 엽산 함유 영양제를 임의로 먹지 않고 담당의와 상의함. 류코보린 구조요법은 의료진이 시간과 용량을 정함', '식약처원문', 'high', '맥락에 따라 다름. 류마티스관절염·건선에 쓰는 주 1회 저용량 메토트렉세이트에서는 오히려 엽산을 처방해 독성을 줄임(코크란: 위장관 부작용 상대위험 26% 감소, 간수치 상승 RR 0.23). 이때 처방된 엽산은 먹고, 추가 고용량 자가 복용만 상의함(다음 행 참조) | 다른 리서처 서술: 메토트렉세이트의 효능이 감소할 수 있다(허가사항). / 엽산이 고갈되어 구내염, 위장관 부작용, 간수치 상승, 골수억제 같은 독성이 생김. 고령자는 엽산 저장량이 적어 독성 위험이 큼', True),
  (73, '비타민-의약품', '비타민B9(엽산)', '항경련제 장기 복용', '페니토인', '항경련제(페니토인, 페노바르비탈, 카르바마제핀)', 'drug', '영양소_흡수감소_결핍', '혈청 엽산이 떨어지고 엽산 결핍증(거대적아구성 변화)이 생김. 임신 중에는 엽산 결핍이 악화되어 태아 선천기형 위험이 커질 수 있음', '페니토인, 페노바르비탈, 카르바마제핀(효소유도 항경련제)', '효소유도 항경련제가 엽산의 장 흡수와 대사에 영향을 주어 엽산 저장을 고갈시킴. 국내 페니토인·페노바르비탈·카르바마제핀 허가사항 모두에 엽산 저하나 엽산 결핍이 적혀 있음', '부광페니토인캡슐, 하나페노바르비탈정, 테그레톨정(카르바마제핀)', '항경련제를 오래 먹은 60대에게 대구성 빈혈이 확인됨', 'major', 'monitor', '정기적으로 엽산과 혈구를 검사하고, 보충은 의사 지시에 따라 페니토인 농도와 함께 조절함(위 행 참조)', '식약처원문', 'high', '엽산을 보충하면 페니토인 농도가 떨어지는 위 행과 짝을 이루므로 반드시 함께 관리함 | 다른 리서처 서술: 경구 페니토인 복용 시 혈청 엽산치가 떨어질 수 있다. 반대로 엽산이 부족한 환자에게 엽산을 갑자기 보충하면 페니토인 농도가 낮아져 발작이 생길 수 있다(양방향). / 페니토인 혈중농도가 감소해 발작이 더 잦아질 수 있음(국내 엽산제 허가사항)', True),
  (79, '미네랄-의약품', '마그네슘', '마그네슘 보충제·마그네슘 함유 제산제', '시프로플록사신', '플루오로퀴놀론계 항생제(시프로플록사신·레보플록사신·목시플록사신)', 'drug', '약효감소', '항생제 흡수가 저하되어 효과가 줄 수 있다.', '마그네슘 이온(Mg2+)과 퀴놀론의 킬레이트', '마그네슘이 퀴놀론의 케토-카르복실기와 결합해 흡수되지 않는 복합체를 만든다.', '약: 씨프로바이정, 크라비트정, 아벨록스정 / 영양제·약: 마그네슘 보충제, 산화마그네슘(마그오캡슐), 마그네슘 함유 제산제', '변비로 산화마그네슘을 먹는 70대가 시프로플록사신을 같은 시간에 먹는다.', 'major', 'separate_timing', '시프로플록사신 1~2시간 전/4시간 후, 레보플록사신 전후 2시간, 목시플록사신 4시간 전/8시간 후로 마그네슘 제품과 간격을 둔다.', '식약처원문', 'high', '| 다른 리서처 서술: 알루미늄·마그네슘 제산제를 5~10분 전, 2시간 전, 4시간 전에 먹으면 시프로플록사신 상대 생체이용률이 각각 15.1%, 23.2%, 70%로 떨어졌다. 6시간 전이나 2시간 뒤에 먹은 경우에는 영향이 없었다.', False),
  (80, '미네랄-의약품', '마그네슘', '마그네슘 보충제·마그네슘 함유 제산제를 엘트롬보팍 복용 전 4시간~후 2시간 사이에 먹을 때', '엘트롬보팍', '트롬보포이에틴 수용체 작용제', 'drug', '약효감소', '다가 양이온 제산제(수산화알루미늄 1524 mg, 탄산마그네슘 1425 mg, 알긴산나트륨)와 같이 먹으면 엘트롬보팍 전신 노출이 약 70% 줄었다. 혈소판 증가 효과가 떨어질 수 있다.', '마그네슘 이온(Mg2+)과 엘트롬보팍의 킬레이트', '엘트롬보팍은 마그네슘 같은 다가 양이온과 결합해 흡수되지 않는 복합체를 만든다.', '약: 레볼레이드정 / 영양제·일반약: 마그네슘 영양제, 마그밀정, 칼슘·마그네슘 복합제, 제산제', '레볼레이드를 먹는 60대가 수면 개선용 마그네슘 영양제를 약과 같이 복용', 'major', 'separate_timing', '마그네슘 함유 제품 복용 최소 2시간 전 또는 4시간 뒤에 엘트롬보팍을 먹는다(국내 허가사항).', '식약처원문', 'high', '정량 수치는 알루미늄·마그네슘 복합 제산제에서 나왔다.', False),
  (81, '미네랄-의약품', '마그네슘', '마그네슘 함유제제(제산제·사하제·보충제), 특히 장기 투석 환자', '칼시트리올', '활성형 비타민D 제제(칼시트리올·알파칼시돌)', 'drug', '영양소_과잉_독성', '고마그네슘혈증(저혈압, 서맥, 근력 저하, 의식 저하)이 나타날 수 있다.', '활성형 비타민D가 장 마그네슘 흡수를 늘린 상태에서 마그네슘 섭취, 그리고 투석 환자의 배설 불능', '활성형 비타민D는 장의 2가 양이온 흡수를 높인다. 신장 배설이 거의 없는 투석 환자에서는 마그네슘이 축적된다.', '약: 로칼트롤연질캡슐, 원알파정 / 영양제·약: 마그오캡슐(산화마그네슘), 마그네슘 보충제, 마그네슘 제산제', '투석 중인 70대가 로칼트롤을 먹으면서 변비약으로 산화마그네슘을 계속 먹는다.', 'major', 'avoid', '투석 환자는 활성형 비타민D 투여 기간 동안 마그네슘 함유제제를 함께 쓰지 않는다.', '식약처원문', 'high', '원알파정은 투석 여부와 관계없이 ''마그네슘 함유제제''를 복용하지 말 것 항목에 적었다. | 다른 리서처 서술: 장기 투석 환자에서 고마그네슘혈증이 생길 수 있다(근력 저하, 저혈압, 서맥 등). 칼시트리올 이상반응에도 고마그네슘혈증이 적혀 있다.', True),
  (83, '미네랄-의약품', '마그네슘', '마그네슘 보충제(산화마그네슘), 마그네슘 함유 변비약·제산제(수산화마그네슘)를 같이 먹을 때', '독시사이클린', '테트라사이클린계 항생제(미노사이클린, 테트라사이클린 포함)', 'drug', '약효감소', '항생제 흡수가 줄어 효과가 떨어진다(감염 치료 실패, 내성 위험).', '마그네슘 이온(Mg2+)이 테트라사이클린과 킬레이트 결합', '마그네슘은 2가 양이온이라 테트라사이클린계와 흡수되지 않는 킬레이트를 만든다. 수산화·산화마그네슘은 위 pH도 올려 약의 녹는 정도를 바꿀 수 있다.', '약: 독시마이신엔정, 미노씬캡슐 / 영양제·일반약: 마그밀정(수산화마그네슘), 마그오캡슐(산화마그네슘), 칼슘·마그네슘 복합 영양제', '변비로 마그밀을 매일 먹는 60대가 독시사이클린을 처방받고 저녁에 함께 복용', 'moderate', 'separate_timing', '마그네슘제와 2시간 이상 간격을 둔다. 항생제 복용 기간에는 마그네슘 변비약을 다른 계열로 바꾸는 것을 약사와 상의한다.', '식약처원문', 'high', '마그네슘 일반의약품(마그밀정·마그오캡슐) 허가사항에는 테트라사이클린계와 ''병용투여하지 않는다''로 더 강하게 적혀 있다. | 다른 리서처 서술: 테트라사이클린계 흡수가 저하되어 효과가 떨어진다.', False),
  (84, '미네랄-의약품', '마그네슘', '마그네슘 함유 제산제·변비약(수산화마그네슘·탄산마그네슘, 산화마그네슘)을 레보티록신과 같이 계속 먹을 때', '레보티록신', '갑상선호르몬제', 'drug', '약효감소', '레보티록신 용량은 그대로인데 제산제·변비약을 같이 먹은 갑상선저하 환자 2명에서 TSH가 크게 오르고 T4가 낮아졌으며, 끊자 회복됐다(증례). 레보티록신이 부족해질 수 있다.', '수산화알루미늄·수산화마그네슘·탄산마그네슘 복합 제산제의 레보티록신 흡착', '시험관 연구에서 알루미늄·마그네슘 복합 제산제는 용량에 비례해 레보티록신을 흡착했다. 같은 연구에서 산화마그네슘 단독은 흡착과 연관이 없어 성분별 차이가 있다.', '약: 씬지로이드정 등 / 영양제·일반약: 마그밀정(수산화마그네슘), 마그오캡슐(산화마그네슘), 알루미늄·마그네슘 제산제, 마그네슘 영양제', '갑상선약을 먹는 60대가 변비 때문에 산화마그네슘을 아침에 같이 먹기 시작한 뒤 피로가 심해짐', 'moderate', 'separate_timing', '레보티록신과 마그네슘 제산제·변비약은 몇 시간 간격을 둔다. 복용을 시작하거나 끊으면 TSH를 확인한다.', '증례보고', 'low', '국내 레보티록신 허가사항은 ''알루미늄 함유 제산제''만 적고 마그네슘은 적지 않았다. 근거는 증례 2건과 시험관 연구이며, 산화마그네슘 단독은 시험관에서 흡착이 없었다.', False),
  (85, '미네랄-의약품', '마그네슘', '마그네슘 보충제·마그네슘 함유 제산제/완하제를 같은 시간대에 복용', '리세드로네이트', '경구 비스포스포네이트(리세드로네이트·이반드로네이트·알렌드로네이트)', 'drug', '약효감소', '비스포스포네이트 흡수가 줄어 골다공증 치료 효과가 떨어진다.', '마그네슘 이온(Mg2+)이 비스포스포네이트와 킬레이트', '2가 양이온인 마그네슘이 포스포네이트기와 결합해 장 흡수를 막는다.', '약: 악토넬정, 본비바정 / 영양제: 마그네슘 보충제, 산화마그네슘(마그오캡슐), 칼슘·마그네슘 복합제', '근육 경련으로 마그네슘을 먹는 60대가 골다공증약과 마그네슘을 같은 아침에 먹는다.', 'moderate', 'separate_timing', '비스포스포네이트는 아침 공복에 물로만 먹고, 마그네슘 제품은 제품별로 정한 시간(30분~2시간 이상)이 지난 뒤에 먹는다.', '식약처원문', 'high', null, False),
  (87, '미네랄-의약품', '마그네슘', '마그네슘 보충제·마그네슘 함유 제산제·변비약을 비스포스포네이트 복용 직후 먹을 때', '알렌드로네이트', '비스포스포네이트계 골다공증 치료제(리세드로네이트, 이반드로네이트)', 'drug', '약효감소', '비스포스포네이트 흡수가 줄어 골다공증 치료 효과가 떨어진다.', '마그네슘 이온(Mg2+)과 비스포스포네이트의 결합', '마그네슘은 2가 양이온이라 비스포스포네이트 인산기와 결합해 흡수를 막는다.', '약: 포사맥스정, 악토넬정, 본비바정 / 영양제·일반약: 칼슘·마그네슘 복합제, 마그밀정, 마그네슘 영양제', '골다공증약 복용일 아침에 60대가 칼슘·마그네슘 영양제를 같이 먹음', 'moderate', 'separate_timing', '비스포스포네이트 복용 후 알렌드로네이트·리세드로네이트는 최소 30분, 이반드로네이트는 최소 1시간 지나서 마그네슘제를 먹는다.', '식약처원문', 'high', null, False),
  (88, '미네랄-의약품', '마그네슘', '마그네슘 함유제제(영양제·산화마그네슘 변비약·제산제)', '알파칼시돌', '활성형 비타민D 제제', 'drug', '영양소_과잉_독성', '고마그네슘혈증(식약처 허가사항: 복용하지 말 것 항목). 알파칼시돌은 고마그네슘혈증 환자에게도 금기.', '마그네슘 이온', '활성형 비타민D가 장의 마그네슘 흡수도 늘려, 마그네슘 제제를 함께 먹으면 혈중 마그네슘이 오를 수 있다. 신기능이 떨어진 사람은 배설이 느려 위험이 크다.', '뉴알파정·알파디(알파칼시돌) + 마그밀 등 산화마그네슘 변비약, 마그네슘 영양제', '신기능이 떨어진 70대가 알파칼시돌을 먹으면서 변비 때문에 산화마그네슘을 매일 복용', 'moderate', 'avoid', '마그네슘 함유 변비약·영양제는 처방의와 상담, 신기능 저하자는 혈청 마그네슘 확인', '식약처원문', 'high', '영역 4와 중복 가능.', False),
  (89, '미네랄-의약품', '마그네슘', null, '에스오메프라졸', '프로톤펌프억제제(PPI: 에스오메프라졸·오메프라졸·란소프라졸·판토프라졸 등)', 'drug', '영양소_흡수감소_결핍', '3개월 이상(특히 1년 이상) 복용 시 저마그네슘혈증이 생기며, 중대한 경우 강직·부정맥·발작이 나타난다. 메타분석에서 PPI 사용자의 저마그네슘혈증 위험비는 1.43이었다.', 'PPI가 장 상피의 TRPM6/7 채널을 통한 능동 마그네슘 흡수를 저해', '위산 억제로 장 내강 pH가 바뀌면 TRPM6/7을 통한 마그네슘 능동 흡수가 줄어든다. 이뇨제·디곡신과 함께 쓰면 위험과 결과(부정맥)가 커진다.', '약: 넥시움정20·40밀리그램, 란스톤캡슐, 오메프라졸 복합제 / 영양제: 마그네슘 보충제', '역류성식도염으로 넥시움을 2년째 먹고 이뇨제도 먹는 70대가 다리 경련과 두근거림을 겪는다.', 'moderate', 'monitor', '장기 복용이 예상되거나 디곡신·이뇨제를 함께 먹는 사람은 치료 시작 시와 주기적으로 혈청 마그네슘을 측정한다. 저마그네슘혈증이면 보충하고 PPI 중단을 검토한다.', '식약처원문', 'high', '이 행은 약이 영양소 결핍을 만드는 경우다. 마그네슘 보충제 자체가 해롭다는 뜻은 아니다. | 다른 리서처 서술: 장기 PPI 사용으로 저마그네슘혈증이 생길 수 있고, 강직, 부정맥, 발작 같은 중대한 이상반응이 보고됐다. 중증 저마그네슘혈증은 저칼슘혈증과 저칼륨혈증도 일으킬 수 있다. 메타분석에서 PPI 사용자의 저마그네슘혈증 위험비는 1.43이었다.', False),
  (91, '미네랄-의약품', '마그네슘', '수산화마그네슘(·수산화알루미늄) 제산제를 로수바스타틴과 동시 복용할 때', '로수바스타틴', 'HMG-CoA 환원효소 억제제(스타틴)', 'drug', '약효감소', '수산화알루미늄·수산화마그네슘 제산제와 같이 먹으면 로수바스타틴 혈장 농도가 약 50% 줄었다. 제산제를 2시간 뒤에 먹으면 완화됐다. 임상적 관련성은 연구되지 않았다.', '수산화마그네슘·수산화알루미늄 제산제(흡착 또는 결합 추정)', '제산제 성분이 장 안에서 로수바스타틴에 흡착·결합해 흡수를 줄이는 것으로 추정된다. 허가사항에 기전 설명은 없다.', '약: 크레스토정(로수바스타틴) / 영양제·일반약: 알루미늄·마그네슘 제산제, 마그밀정', '고지혈증으로 크레스토를 먹는 60대가 저녁 식후 속쓰림 제산제를 함께 복용', 'minor', 'separate_timing', '제산제는 로수바스타틴 복용 2시간 뒤에 먹는다.', '식약처원문', 'low', '근거는 복합 제산제이며 마그네슘 단독 보충제(산화마그네슘 등)에 그대로 적용되는지는 확인되지 않았다.', False),
  (93, '미네랄-의약품', '마그네슘', '알루미늄·마그네슘 함유 제산제나 마그네슘 보충제를 세프디니르와 같이 먹을 때', '세프디니르', '경구 3세대 세팔로스포린 항생제', 'drug', '약효감소', '세프디니르 흡수가 떨어져 항생 효과가 줄 수 있다(정량 수치는 확인 못 함).', '마그네슘·알루미늄 이온과 세프디니르의 결합', '세프디니르는 금속 이온과 킬레이트를 만드는 성질이 있어 마그네슘·알루미늄 제산제와도 흡수가 줄어든다.', '약: 세프다나캡슐 등 세프디니르 제제 / 영양제·일반약: 제산제, 마그밀정, 마그네슘 영양제', '세프디니르를 먹는 50대가 속쓰림 때문에 제산제를 바로 같이 먹음', 'minor', 'separate_timing', '세프디니르를 먹고 2시간 이상 지난 뒤 제산제를 먹는다(국내 허가사항).', '식약처원문', 'medium', '허가사항은 제산제 기준이며 마그네슘 단독 보충제 연구는 찾지 못했다.', False),
  (94, '미네랄-의약품', '셀레늄', '셀레늄 함유 미네랄 보충제·종합비타민을 엘트롬보팍과 가까운 시간에 먹을 때', '엘트롬보팍', '트롬보포이에틴 수용체 작용제', 'drug', '약효감소', '엘트롬보팍이 셀레늄도 킬레이트화한다고 허가사항에 적혀 있어 흡수가 줄 수 있다. 셀레늄 보충제는 μg 단위라 실제 영향은 작을 것으로 보이며 정량 근거는 없다.', '셀레늄과 엘트롬보팍의 킬레이트(허가사항 기재)', '엘트롬보팍은 다가 양이온을 킬레이트화하는 구조를 가지며, 허가사항은 셀레늄을 그 대상에 포함한다.', '약: 레볼레이드정 / 영양제: 셀레늄 영양제, 셀레늄 함유 종합비타민', '레볼레이드를 먹는 60대가 항산화 영양제(셀레늄)를 같은 시간에 복용', 'minor', 'separate_timing', '다른 미네랄 보충제와 마찬가지로 엘트롬보팍 2시간 전 또는 4시간 뒤로 나눈다.', '식약처원문', 'low', '셀레늄이 국내 의약품 허가사항에 상호작용 대상으로 명시된 드문 예이다.', False),
  (96, '미네랄-의약품', '아연', '아연 보충제·아연 함유 종합비타민', '시프로플록사신', '플루오로퀴놀론계 항생제(시프로플록사신·레보플록사신·목시플록사신)', 'drug', '약효감소', '항생제 흡수가 줄어든다. 아연 함유 종합비타민과 함께 먹으면 시프로플록사신 AUC가 14.5에서 11.3 µg·h/mL로 감소했다.', '아연 이온(Zn2+)과 퀴놀론의 킬레이트', '2가 금속 양이온인 아연이 퀴놀론과 복합체를 만들어 장 흡수를 줄인다.', '약: 씨프로바이정, 크라비트정, 아벨록스정 / 영양제: 아연 보충제, 아연 함유 종합비타민·면역 영양제', '감기 예방용 아연 영양제를 먹는 50대가 요로감염으로 시프로플록사신을 함께 먹는다.', 'moderate', 'separate_timing', '아연 함유 제품은 시프로플록사신 복용 4시간 후(또는 1~2시간 전)에, 레보플록사신 전후 2시간을 피해 먹는다. 목시플록사신은 4시간 전 또는 8시간 후.', '식약처원문', 'high', 'Polk 1989 연구는 종합비타민의 어느 성분이 원인인지는 추가 연구가 필요하다고 적었다. | 다른 리서처 서술: 아연 함유 종합비타민을 7일간 먹은 뒤 같이 복용하면 시프로플록사신 AUC가 14.5에서 11.3 μg·h/mL로 줄었다. 철분제보다는 감소 폭이 작다.', False),
  (97, '미네랄-의약품', '아연', '아연 함유 미네랄 보충제·종합비타민을 엘트롬보팍 전후로 가깝게 먹을 때', '엘트롬보팍', '트롬보포이에틴 수용체 작용제', 'drug', '약효감소', '엘트롬보팍이 아연과 킬레이트를 만들어 흡수가 줄고 혈소판 증가 효과가 떨어질 수 있다(아연 단독 수치는 없음).', '아연 이온(Zn2+)과 엘트롬보팍의 킬레이트', '엘트롬보팍은 아연을 포함한 다가 양이온을 킬레이트화한다. 복합체는 흡수가 잘 되지 않는다.', '약: 레볼레이드정 / 영양제: 아연 영양제, 아연 함유 종합비타민', '레볼레이드를 먹는 50대가 아침에 아연 함유 종합비타민을 같이 복용', 'moderate', 'separate_timing', '미네랄 보충제 복용 최소 2시간 전 또는 4시간 뒤에 엘트롬보팍을 먹는다(국내 허가사항).', '식약처원문', 'medium', null, False),
  (99, '미네랄-의약품', '아연', '아연 보충제·아연 함유 종합비타민', '독시사이클린', '테트라사이클린계 항생제(독시사이클린·미노사이클린)', 'drug', '약효감소', '테트라사이클린계 흡수가 저하되어 효과가 떨어진다.', '아연 이온과 테트라사이클린의 킬레이트', '아연이 테트라사이클린과 금속 킬레이트를 만들어 장 흡수를 줄인다.', '약: 국제독시사이클린캡슐, 미노씬캡슐 / 영양제: 아연 보충제, 아연 함유 종합비타민', '면역용 아연 영양제를 먹는 50대가 독시사이클린 치료를 시작한다.', 'minor', 'separate_timing', '아연 함유 제품과 2시간 이상 간격을 둔다.', '식약처원문', 'medium', '| 다른 리서처 서술: 황산아연(아연 45 mg)을 같이 먹으면 테트라사이클린의 혈중 농도·AUC·소변 배설이 약 30% 줄었다. 같은 연구에서 독시사이클린 흡수에는 유의한 영향이 없었다.', False),
  (103, '미네랄-의약품', '요오드', '아미오다론 복용 중 요오드 함유 보충제(해조 추출물, 고함량 요오드)를 추가할 때', '아미오다론', '클래스III 항부정맥제', 'drug', '기타', '아미오다론 100 mg 정 한 알에 하루 요오드 권장량의 250배가 들어 있어 갑상선기능저하·항진증을 일으킬 수 있다. 요오드 보충이 더해지면 요오드 부하가 늘어난다(이론).', '아미오다론 분자 속 요오드 + 보충제 요오드', '아미오다론은 대사되면서 많은 무기 요오드를 내놓고, 갑상선 조직에 직접 독성도 있다. 추가 요오드 섭취는 이미 과부하인 갑상선에 부담을 더할 수 있다.', '약: 코다론정(아미오다론) / 영양제: 요오드·해조류(켈프) 보충제, 요오드 함유 종합비타민', '심방세동으로 아미오다론을 먹는 70대가 갑상선에 좋다는 해조류 요오드 보충제를 복용', 'minor', 'consult', '아미오다론 복용 중에는 요오드 보충제를 따로 먹기 전에 의사와 상의한다. 정기 갑상선 기능(usTSH) 검사를 유지한다.', '식약처원문', 'low', '보충제 요오드가 아미오다론 갑상선 이상을 실제로 늘린다는 직접 연구는 찾지 못했다. 근거는 아미오다론의 요오드 함량과 갑상선 독성(허가사항·리뷰)이다.', True),
  (106, '미네랄-의약품', '철분', '철분제·철 함유 종합비타민을 같은 시간대에 복용', '시프로플록사신', '플루오로퀴놀론계 항생제(시프로플록사신·레보플록사신·목시플록사신)', 'drug', '약효감소', '항생제 혈중농도가 크게 떨어진다. 황산제일철과 함께 먹으면 시프로플록사신 AUC가 14.5에서 5.4 µg·h/mL로 감소했고, 최고농도가 많은 균주의 MIC90 아래로 떨어졌다.', '철 이온(Fe2+/Fe3+)과 퀴놀론의 킬레이트', '철 이온이 퀴놀론의 케토-카르복실기와 결합해 흡수되지 않는 복합체를 만든다.', '약: 씨프로바이정, 크라비트정, 아벨록스정 / 영양제: 철분제(훼럼포유연질캡슐 등), 철 함유 종합비타민·임산부 영양제', '빈혈로 철분제를 먹는 60대가 폐렴으로 레보플록사신을 처방받아 아침에 함께 먹는다.', 'major', 'separate_timing', '시프로플록사신은 철분제 복용 1~2시간 전 또는 4시간 후에 먹는다. 레보플록사신은 전후 2시간, 목시플록사신은 철 제제 투여 4시간 전 또는 8시간 후에 먹는다. 짧은 항생제 기간에는 철분제를 잠시 쉬는 것도 방법이다.', '식약처원문', 'high', '| 다른 리서처 서술: 황산제일철을 같이 먹으면 시프로플록사신 AUC가 14.5에서 5.4 μg·h/mL로 줄었고, 최고 농도가 원래 감수성인 여러 균의 MIC90보다 낮았다. 감염 치료가 실패할 수 있다.', False),
  (107, '미네랄-의약품', '철분', '철분제·철 함유 종합비타민', '독시사이클린', '테트라사이클린계 항생제(독시사이클린·미노사이클린·테트라사이클린)', 'drug', '약효감소', '테트라사이클린계 흡수가 저하되어 항생 효과가 떨어진다.', '철 이온과 테트라사이클린의 킬레이트', '테트라사이클린은 다가 금속 양이온과 강하게 결합한다. 철과 결합하면 흡수되지 않고, 철 흡수도 함께 줄어든다.', '약: 국제독시사이클린하이클레이트수화물캡슐100밀리그램, 미노씬캡슐50mg / 영양제: 철분제, 철 함유 종합비타민', '여드름·로사세아로 독시사이클린을 장기 복용하는 50대가 철분제를 아침에 함께 먹는다.', 'moderate', 'separate_timing', '양이온 함유 약물과는 2시간 이상 간격을 두고 투여한다(허가사항).', '식약처원문', 'high', 'Neuvonen 1974 논문은 PubMed에 초록이 없어 제목만 확인했다. | 다른 리서처 서술: 황산제일철을 같이 먹으면 테트라사이클린·옥시테트라사이클린·메타사이클린·독시사이클린의 흡수가 심하게 떨어져 항생 효과가 줄어든다. 철 흡수도 함께 줄 수 있다.', False),
  (108, '미네랄-의약품', '철분', '황산제일철 등 철분제 동시 복용', '레보도파', '파킨슨병 치료제(레보도파 복합제)', 'drug', '약효감소', '황산제일철이 레보도파의 최고 혈장농도와 AUC를 30~50% 낮춘다(허가사항). 건강인 연구에서는 최고농도가 55%, AUC가 51% 감소했다.', '철 이온(소장에서 Fe3+로 산화)이 레보도파의 카테콜 구조와 킬레이트', '소장 pH에서 2가 철이 3가로 빠르게 산화되고, 3가 철은 레보도파의 카테콜기와 강하게 결합한다. 결합체는 흡수되지 않는다.', '약: 마도파에취비에스캡슐125, 퍼킨정 / 영양제: 철분제, 철 함유 종합비타민', '파킨슨병 환자인 70대가 빈혈로 철분제를 시작한 뒤 약효가 빨리 떨어지는(wearing-off) 증상이 늘어난다.', 'moderate', 'caution', '철분제와 레보도파는 동시에 먹지 말고 시간 간격을 둔다(원문에 구체 시간 없음). 철분제 시작 후 운동 증상 변화를 관찰한다.', '식약처원문', 'high', '| 다른 리서처 서술: 황산제일철 325 mg을 같이 먹으면 정상인에서 레보도파 최고 농도가 55%, AUC가 51% 줄었다. 파킨슨 환자에서는 레보도파 AUC가 30%, 카르비도파 AUC가 75% 넘게 줄었다. 국내 허가사항은 Cmax·AUC가 30~50% 준다고 적고 있다. 일부 환자는 증상 조절이 나빠질 수 있다.', False),
  (109, '미네랄-의약품', '철분', '철분제(황산제일철 등)를 레보티록신과 동시 복용', '레보티록신', '갑상선호르몬제', 'drug', '약효감소', '레보티록신 흡수가 감소한다. 황산제일철 300 mg을 12주 동시 복용하자 TSH가 1.6에서 5.4 mU/L로 올랐고, 14명 중 9명에서 갑상선기능저하 증상이 늘었다.', '철 이온(Fe2+/Fe3+)이 티록신과 결합', '철과 티록신이 장 안에서 녹지 않는 복합체(시험관에서 보라색 침전)를 만들어 티록신 흡수를 막는다.', '약: 씬지로이드정 / 영양제·약: 철분제(훼럼포유연질캡슐, 볼그레액 등), 철 함유 종합비타민·임산부 영양제', '빈혈로 철분제를 처방받은 50대가 아침 갑상선약과 철분제를 함께 먹은 뒤 피로가 심해진다.', 'moderate', 'separate_timing', '철분제는 레보티록신 복용 후 4시간 뒤에 먹는다(식약처 안내). 철분제를 시작한 뒤 TSH를 다시 확인한다.', '식약처원문', 'high', '씬지로이드 허가사항은 철분제제에 대해 구체적 시간 없이 ''투여간격에 주의''라고 적었다. 4시간은 식약처 대국민 안내 문구다. | 다른 리서처 서술: 철이 레보티록신의 흡수를 줄여 갑상선 호르몬 효과가 떨어질 수 있다(식약처: 2~3시간 이상 간격). / 황산제일철 300 mg을 12주간 레보티록신과 동시에 먹자 TSH가 1.6에서 5.4 mU/L로 올랐고, 14명 중 9명에서 갑상선저하 증상·징후가 늘었다.', False),
  (110, '미네랄-의약품', '철분', '철분제·철 함유 종합비타민을 같은 시간대에 복용', '리세드로네이트', '경구 비스포스포네이트(리세드로네이트·이반드로네이트·알렌드로네이트)', 'drug', '약효감소', '비스포스포네이트 흡수가 줄어 골다공증 치료 효과가 떨어진다.', '다가 양이온인 철 이온이 비스포스포네이트와 킬레이트', '철(Fe2+/Fe3+)도 칼슘처럼 포스포네이트기와 결합해 흡수되지 않는 복합체를 만든다.', '약: 악토넬정35밀리그람, 악토넬EC정, 본비바정 / 영양제: 철분제, 철 함유 종합비타민', '빈혈약과 골다공증약을 함께 처방받은 70대가 아침에 두 약을 한꺼번에 먹는다.', 'moderate', 'separate_timing', '비스포스포네이트를 아침 공복에 먼저 먹고, 철분제는 30분~2시간 이상(제품별 허가사항) 뒤에 먹는다.', '식약처원문', 'high', null, False),
  (112, '미네랄-의약품', '철분', '철분제 동시 복용', '세프디니르', '경구 3세대 세팔로스포린 항생제', 'drug', '약효감소', '철분제가 세프디니르 흡수를 약 1/10까지 떨어뜨린다. 동시 복용 시 AUC가 10.3에서 0.78 µg·h/mL로 감소했다.', '철 이온과 세프디니르의 킬레이트', '세프디니르는 철 이온과 킬레이트 복합체를 만들어 위장관 흡수가 제한된다. 철분 3시간 뒤 투여에도 후반부 흡수가 일부 줄었다.', '약: 옴니세프캡슐100밀리그램·세립소아용 / 영양제: 철분제, 철 강화 분유·종합비타민', '철분제를 먹는 60대 여성이 부비동염으로 세프디니르를 처방받아 아침에 함께 먹는다.', 'moderate', 'separate_timing', '함께 먹지 않는 것이 좋다. 부득이하면 세프디니르 복용 후 3시간 이상 지나서 철분제를 먹는다.', '식약처원문', 'high', '철과 함께 먹으면 대변이 붉은색을 띨 수 있다(국외 라벨 정보, 국내 원문은 미확인). | 다른 리서처 서술: 철분제를 같이 먹으면 세프디니르 AUC가 10.3에서 0.78 μg·h/mL로 줄었다. 국내 허가사항은 흡수가 약 1/10까지 떨어진다고 적고 있어 감염 치료가 실패할 수 있다. 철 첨가 분유·경장영양제와 함께 쓰면 변이 붉게 나올 수 있다.', False),
  (113, '미네랄-의약품', '철분', '철분제·철 함유 종합비타민을 비스포스포네이트와 동시 복용할 때', '알렌드로네이트', '비스포스포네이트계 골다공증 치료제(리세드로네이트, 이반드로네이트)', 'drug', '약효감소', '비스포스포네이트 흡수가 방해받아 골다공증 치료 효과가 떨어진다. 철분제 쪽 허가사항도 디포스폰산 염류의 흡수가 감소한다고 적고 있다(정량 수치는 확인 못 함).', '철 이온(다가 양이온)이 비스포스포네이트 인산기와 결합', '철도 칼슘처럼 다가 양이온이라 비스포스포네이트와 결합해 흡수되지 않는 복합체를 만든다.', '약: 포사맥스정, 악토넬정, 본비바정 / 영양제: 훼로바-유서방정, 철분 영양제, 철 함유 종합비타민', '빈혈 치료 중인 70대 여성이 주 1회 골다공증약을 먹는 날 아침 철분제를 함께 복용', 'moderate', 'separate_timing', '비스포스포네이트를 아침 공복에 먼저 먹고, 30분~1시간 이상(이반드로네이트는 1시간) 지난 뒤, 가능하면 철분제 허가사항대로 2~3시간 이상 간격을 두고 철분제를 먹는다.', '식약처원문', 'high', '철 단독의 약동학 수치는 찾지 못했다. 근거는 국내 허가사항(비스포스포네이트·철분제 양쪽)이다.', False),
  (114, '미네랄-의약품', '철분', 'PPI·H2 차단제를 장기(2년 이상) 복용하면서 음식·철분제로 비헴철을 섭취할 때', '에스오메프라졸', '프로톤펌프억제제(오메프라졸, 란소프라졸, 판토프라졸, 라베프라졸 등) 및 H2 차단제', 'drug', '영양소_흡수감소_결핍', 'PPI를 7일 먹자 식사 속 비헴철 흡수가 줄어 혈청 철 곡선 아래 면적이 2145에서 1059로 떨어졌다(혈색소증 환자). 2년 이상 PPI 사용은 철결핍 위험 증가(aOR 2.49), H2 차단제는 aOR 1.58과 연관됐다. 철분제 효과가 떨어지고 철결핍성 빈혈이 생길 수 있다.', '위산 억제(약 성분)에 따른 비헴철(Fe3+)의 용해·환원 저하', '음식과 영양제 속 비헴철은 위산에서 녹고 2가 철로 환원돼야 잘 흡수된다. PPI가 위산을 강하게 억제하면 이 과정이 줄어 철 흡수가 감소한다.', '약: 넥시움정(에스오메프라졸), 오메프라졸·란소프라졸·판토프라졸 제제, 파모티딘 / 영양제: 철분제, 철 함유 종합비타민', '역류성 식도염으로 PPI를 수년째 먹는 60대가 철분제를 먹어도 빈혈 수치가 잘 오르지 않음', 'moderate', 'monitor', 'PPI를 장기 복용하면서 철분제를 먹는다면 혈색소·페리틴을 주기적으로 확인하고, 반응이 없으면 의사와 상의한다.', 'RCT/약동학연구', 'medium', '국내 PPI 허가사항에서 철 흡수 감소 문구는 찾지 못했다(위 산도 변화로 흡수가 바뀌는 약물 일반 문구만 있음). 근거는 논문이다. H2 차단제 × 철은 이 행에 통합했다.', True),
  (115, '미네랄-의약품', '철분', '철 함유 미네랄 보충제를 엘트롬보팍 복용 전 4시간~복용 후 2시간 사이에 먹을 때', '엘트롬보팍', '트롬보포이에틴 수용체 작용제(면역혈소판감소증·재생불량빈혈)', 'drug', '약효감소', '엘트롬보팍 흡수가 줄어 혈소판 수 증가 효과가 떨어질 수 있다. 다가 양이온 제산제 병용 시 노출이 약 70% 줄었다는 허가사항 수치는 알루미늄·마그네슘 제산제 연구에서 나왔다.', '철 이온(다가 양이온)과 엘트롬보팍의 킬레이트', '엘트롬보팍은 철·칼슘·알루미늄·마그네슘·셀레늄·아연 같은 다가 양이온을 킬레이트화한다. 복합체가 되면 흡수가 크게 줄어든다.', '약: 레볼레이드정(엘트롬보팍) / 영양제: 철분제, 철 함유 종합비타민', '혈소판감소증으로 레볼레이드를 먹는 60대가 아침 식후 종합비타민·철분제를 같이 복용', 'moderate', 'separate_timing', '미네랄 보충제 복용 최소 2시간 전 또는 복용 4시간 뒤에 엘트롬보팍을 먹는다(국내 허가사항).', '식약처원문', 'medium', '철 단독 약동학 수치는 없고, 허가사항이 계열 전체 다가 양이온에 적용된다.', False),
  (117, '미네랄-의약품', '철분', '철염(비헴철) 경구 보충', '란소프라졸', '프로톤펌프억제제(PPI)', 'drug', '영양소_흡수감소_결핍', '위산이 억제되어 철염 흡수가 감소하고, 철분제 효과가 떨어질 수 있다.', '위산 감소로 3가 철이 흡수 가능한 2가 철로 환원·용해되지 않음', '비헴철은 산성 환경에서 녹고 2가로 환원되어야 십이지장 DMT1으로 흡수된다. PPI가 위 pH를 높이면 이 과정이 줄어든다.', '약: 란스톤캡슐, 넥시움정 / 영양제: 철분제(훼럼포유연질캡슐 등)', 'PPI를 매일 먹는 60대 여성이 철결핍성 빈혈로 철분제를 먹는데 수치가 잘 오르지 않는다.', 'minor', 'caution', '철분제 반응이 나쁘면 PPI 복용을 의사에게 알린다. 비타민C와 함께 먹거나 다른 제형을 고려한다.', '식약처원문', 'medium', '혈색소증 환자에서는 PPI가 오히려 철 흡수를 줄여 유익할 수 있다(Gut 2007).', False),
  (119, '미네랄-의약품', '철분', '철분제와 알로푸리놀 다량 투여', '알로푸리놀', '요산생성억제제(통풍 치료제)', 'drug', '영양소_과잉_독성', '동물실험에서 알로푸리놀 다량 투여와 철분제를 병용하자 간 철분 축적이 증가했다.', '알로푸리놀(잔틴산화효소 억제)이 철 대사·저장에 영향을 주는 것으로 추정', '잔틴산화효소는 페리틴 철 동원(환원)에 관여할 수 있어, 이를 억제하면 간에 철이 쌓인다는 가설이 있다. 사람에서는 확인되지 않았다.', '약: 자이로릭정(알로푸리놀) / 영양제: 철분제', '통풍으로 알로푸리놀을 먹는 60대 남성이 빈혈이 없는데도 철분 영양제를 장기간 먹는다.', 'minor', 'caution', '철 결핍이 확인되지 않았다면 알로푸리놀 복용 중 철분제를 임의로 장기 복용하지 않는다.', '식약처원문', 'low', '근거는 동물실험뿐이며 임상 의미는 불명확하다.', True),
  (130, '미네랄-의약품', '칼슘', '칼슘 영양제·칼슘 함유제제 임의 추가', '알파칼시돌', '활성형 비타민D 제제. 칼시트리올 포함', 'drug', '영양소_과잉_독성', '고칼슘혈증 위험 증가(식약처 허가사항: 복용하지 말 것 항목).', '칼슘 이온', '활성형 비타민D가 장 칼슘 흡수를 크게 높인 상태에서 칼슘 부하가 더해져 혈청 칼슘이 정상 범위를 넘는다.', '뉴알파정·알파디(알파칼시돌) + 칼슘제·칼슘 영양제·탄산칼슘 제산제', '알파칼시돌을 먹는 70대가 뼈에 좋다며 칼슘 영양제를 따로 매일 2정 추가', 'major', 'avoid', '처방의가 함께 처방한 경우가 아니면 칼슘 영양제를 임의로 추가하지 않음. 병용 시 혈청 칼슘 모니터링', '식약처원문', 'high', '실제 진료에서는 칼슘 상태에 따라 모니터링하며 병용하기도 함. 영역 4와 중복 가능.', False),
  (131, '미네랄-의약품', '칼슘', '칼슘 보충제·유제품·고칼슘 식사', '엘트롬보팍', '트롬보포이에틴 수용체 작용제(혈소판감소증 치료)', 'drug', '약효감소', '다가 양이온 함유 제산제와 함께 먹으면 엘트롬보팍 노출이 약 70% 감소했다. 유제품이 포함된 고열량·고지방 식사는 AUC를 59%, Cmax를 65% 낮췄다.', '칼슘(및 철·마그네슘·셀레늄·아연·알루미늄) 등 다가 양이온과의 킬레이트', '엘트롬보팍은 다가 양이온을 킬레이트화한다. 장 안에서 결합하면 흡수되지 않아 혈소판 증가 효과가 떨어진다.', '약: 레볼레이드정25·50밀리그램 / 영양제: 칼슘제, 철분제, 아연·셀레늄 함유 종합비타민, 우유·치즈', 'ITP로 레볼레이드를 먹는 60대가 아침에 칼슘·종합비타민과 우유를 함께 먹는다.', 'major', 'separate_timing', '다가 양이온 함유 제품(제산제, 유제품, 미네랄 보충제)을 먹기 최소 2시간 전 또는 먹고 최소 4시간 뒤에 엘트롬보팍을 먹는다.', '식약처원문', 'high', '원문은 철분, 칼슘, 알루미늄, 마그네슘, 셀레늄, 아연을 모두 열거한다. 이 행은 칼슘을 대표로 적었다. | 다른 리서처 서술: 유제품을 포함한 고칼슘·고지방 식사와 같이 먹으면 엘트롬보팍 AUC가 59%, Cmax가 65% 줄었다. 혈소판 수가 오르지 않아 출혈 위험이 남을 수 있다.', False),
  (132, '미네랄-의약품', '칼슘', '칼슘 함유제제를 무절제하게 복용할 때', '칼시트리올', '활성형 비타민D 제제(칼시트리올·알파칼시돌)', 'drug', '영양소_과잉_독성', '고칼슘혈증 위험이 증가해 신기능 저하, 신결석, 혈관·연조직 석회화가 생길 수 있다. 성인 1일 칼슘섭취 권장량은 약 800 mg이며 1,000 mg을 초과해서는 안 된다(로칼트롤 허가사항).', '활성형 비타민D가 장 칼슘 흡수를 최대화한 상태에서 추가 칼슘 섭취', '칼시트리올·알파칼시돌은 신장 조절을 거치지 않고 장 칼슘 흡수를 직접 높인다. 칼슘제를 더하면 흡수량이 급증해 고칼슘혈증이 생기고, 티아지드 이뇨제는 소변 칼슘 배설을 줄여 위험을 더한다.', '약: 로칼트롤연질캡슐0.25마이크로그람, 원알파정(알파칼시돌) / 영양제: 칼슘제, 디카맥스1000정, 칼트레이트디400정', '골다공증으로 원알파정을 처방받은 70대가 약국에서 산 칼슘·비타민D 복합제를 추가로 먹는다.', 'major', 'avoid', '원알파 복용 중에는 칼슘 함유제제를 함께 먹지 않는다(복용하지 말 것 항목). 로칼트롤은 처방된 칼슘 지침만 따르고 임의 칼슘제를 피한다. 정기적으로 혈청 칼슘을 측정한다.', '식약처원문', 'high', '원알파정 허가사항은 ''칼슘 함유제제 또는 치아지드계 이뇨제''를 같은 ''복용하지 말 것'' 항목에 함께 적었다. | 다른 리서처 서술: 칼슘 흡수가 크게 늘어 고칼슘혈증과 고칼슘뇨증이 생긴다. 만성 고칼슘혈증은 전신 혈관 석회화, 신석회증, 연조직 석회화와 신기능 저하로 이어질 수 있다. 증례에서 탄산칼슘 1 g 하루 3회, 칼시트리올, 비타민D3, 클로르탈리돈을 함께 먹은 환자의 혈청 칼슘이 23 mg/dL였다.', True),
  (133, '미네랄-의약품', '칼슘', '칼슘 보충제·칼슘 함유 제산제·종합비타민미네랄을 약과 2시간 안에 같이 복용할 때. 식사 중 칼슘(우유·유제품 포함)도 영향을 줌', '독시사이클린', '테트라사이클린계 항생제(미노사이클린, 테트라사이클린 포함)', 'drug', '약효감소', '항생제 흡수가 줄어 혈중 농도가 치료 농도 아래로 떨어지면 감염 치료가 실패하거나 내성이 생길 수 있다. 리뷰에서는 우유·유제품, 다가 양이온 제산제, 철염과 동시에 먹으면 테트라사이클린계 흡수가 50~90% 이상 줄 수 있다고 정리한다.', '칼슘 이온(Ca2+)이 테트라사이클린 분자와 킬레이트 결합', '테트라사이클린계는 Fe, Al, Mg, Ca 같은 다가 금속 양이온과 결합해 잘 녹지 않거나 흡수되지 않는 킬레이트 복합체를 만든다. 장 안에서 이 복합체가 생기면 약이 혈액으로 들어가지 못하고 대변으로 나간다.', '약: 독시마이신엔정, 국제독시사이클린하이클레이트캡슐, 미노씬캡슐(미노사이클린) / 영양제: 칼슘·마그네슘·비타민D 복합 영양제, 디카맥스1000정(칼슘 일반의약품), 종합비타민미네랄', '잇몸 염증으로 독시사이클린을 처방받은 50대가 아침 식후 칼슘·비타민D 영양제를 같이 삼킴', 'moderate', 'separate_timing', '칼슘 함유 제품과 2시간 이상 간격을 둔다(국내 허가사항). 약은 우유·유제품과 함께 먹지 않는다.', '식약처원문', 'high', '독시사이클린·미노사이클린은 구형 테트라사이클린보다 음식 영향이 적은 편이지만, 국내 허가사항은 양이온 함유 약물과 2시간 이상 간격을 요구한다. 칼슘 일반의약품 허가사항에도 ''경구용 테트라사이클린계 제제'' 병용 금지가 적혀 있다. | 다른 리서처 서술: 테트라사이클린계 흡수가 저하되어 효과가 떨어진다.', False),
  (134, '미네랄-의약품', '칼슘', '칼슘제를 디곡신과 함께 쓸 때(특히 혈청 칼슘이 높아질 정도의 고용량, 비타민D 병용, 정맥 칼슘)', '디곡신', '강심배당체(심부전·심방세동)', 'drug', '약효증가_독성', '칼슘제를 같이 쓰면 디기탈리스 중독이 생기기 쉽다(국내 허가사항). 고칼슘혈증은 디곡신의 부정맥 유발 작용을 키워 서맥성 부정맥 같은 증상성 리듬 이상을 일으킬 수 있다.', '세포 내 칼슘 증가(칼슘 이온)와 디곡신의 Na+/K+-ATPase 억제 효과 상승', '디곡신은 Na+/K+-ATPase를 억제해 심근 세포 안의 칼슘을 늘린다. 혈중 칼슘까지 높아지면 칼슘 과부하로 전도 장애와 부정맥 위험이 커진다.', '약: 디고신정(디곡신) / 영양제: 칼슘·비타민D 영양제, 디카맥스1000정 등 칼슘 일반의약품', '심방세동으로 디곡신을 먹는 70대 부모에게 자녀가 고용량 칼슘·비타민D 영양제를 사드림', 'moderate', 'consult', '디곡신 복용 중이면 칼슘제를 시작하기 전에 의사·약사와 상의한다(칼슘 일반의약품 허가사항). 혈청 칼슘과 맥박 이상을 확인한다.', '식약처원문', 'medium', '정상 칼슘 수치에서 일반 용량 경구 칼슘제만으로 디곡신 중독이 생긴 근거는 약하다. 위험은 주로 고칼슘혈증이나 정맥 칼슘 상황이다. 증례는 악성종양 고칼슘혈증 환자였다. | 다른 리서처 서술: 디기탈리스 중독(부정맥, 오심, 시야 이상)이 생기기 쉽다.', True),
  (135, '미네랄-의약품', '칼슘', '칼슘제(탄산칼슘 등)를 레보티록신과 동시 복용', '레보티록신', '갑상선호르몬제', 'drug', '약효감소', '레보티록신 흡수가 지연·감소해 갑상선기능저하 조절이 나빠진다. 칼슘 1200 mg/일 동시 복용 3개월 동안 평균 TSH가 1.6에서 2.7 mIU/L로 올랐고, 20%는 정상범위를 넘었다.', '칼슘 이온(탄산칼슘)이 위산 환경에서 레보티록신을 흡착·결합', '레보티록신은 산성 위 환경에서 탄산칼슘 표면에 흡착되어 녹지 않는 복합체를 만든다. 그 결과 소장 흡수가 줄어 혈중 T4가 감소하고 TSH가 오른다.', '약: 씬지로이드정, 신지록신정 / 영양제: 칼슘제, 칼슘·비타민D 복합제(디카맥스1000정, 칼트레이트디400정), 칼슘 함유 종합비타민', '갑상선약을 먹는 60대 여성이 아침 공복에 갑상선약과 칼슘제를 함께 삼킨다.', 'moderate', 'separate_timing', '칼슘제는 레보티록신 복용 최소 4시간 뒤에 먹는다(허가사항 ''최소 4시간 간격'', 식약처 안내 ''약 복용 후 4시간 후'').', '식약처원문', 'high', '식약처 안내(2022)는 콩 식품도 같은 이유로 4시간 간격을 권고한다. | 다른 리서처 서술: 탄산칼슘(원소 칼슘 1200 mg/일)을 3개월간 레보티록신과 같이 먹으면 유리T4가 17에서 15 pmol/L로 떨어지고 TSH가 1.6에서 2.7 mIU/L로 올랐으며, 20%가 TSH 정상범위를 넘었다(최고 7.8 mIU/L). 칼슘 500 mg 단회 병용 시에는 탄산·구연산·초산칼슘 모두 흡수를 약 20~25% 줄였다. 갑상선저하증이 다시 나타날 수 있다.', False),
  (136, '미네랄-의약품', '칼슘', '칼슘제 또는 다량의 우유를 산화마그네슘과 함께 장기 복용', '산화마그네슘', '제산·완하제(마그네슘염)', 'drug', '영양소_과잉_독성', '우유-알칼리 증후군(고칼슘혈증, 고질소혈증, 알칼리증)이 나타날 수 있다.', '칼슘의 과잉 흡수와 알칼리 제제(산화마그네슘)로 인한 대사성 알칼리증의 상승작용', '알칼리증은 신장의 칼슘 재흡수를 늘리고, 고칼슘혈증은 다시 중탄산 배설을 줄이는 악순환을 만든다. 그 결과 신기능 저하와 고칼슘혈증이 진행한다.', '약: 마그오캡슐250·500mg(산화마그네슘) / 영양제: 칼슘제(탄산칼슘), 칼슘·비타민D 복합제, 다량의 우유', '변비로 산화마그네슘을 매일 먹는 70대 여성이 골다공증용 칼슘제와 우유를 많이 먹는다.', 'moderate', 'caution', '함께 복용 시 충분히 관찰하고, 구역·식욕부진·의식저하 등 고칼슘혈증 증상이 나타나면 투여를 중지한다. 신기능 저하자는 특히 주의한다.', '식약처원문', 'high', '기존 수집된 마그밀정에도 같은 문구가 있다(중복 아님: 마그오는 58개 목록에 없음).', True),
  (137, '미네랄-의약품', '칼슘', '칼슘 보충제·칼슘 강화음료·유제품 단독 섭취와 동시 복용', '시프로플록사신', '플루오로퀴놀론계 항생제(시프로플록사신·레보플록사신·목시플록사신)', 'drug', '약효감소', '항생제 흡수가 줄어 치료 실패나 내성 위험이 생긴다. 칼슘 강화 오렌지주스와 함께 먹으면 시프로플록사신 Cmax가 41%, AUC가 38% 감소했다.', '칼슘 이온(Ca2+)이 퀴놀론의 케토-카르복실기와 킬레이트', '퀴놀론은 3-카르복실·4-케토기로 금속 양이온과 킬레이트를 만든다. 이 복합체는 흡수되지 않는다.', '약: 씨프로바이정250밀리그램, 제일크라비트정(레보플록사신), 아벨록스정400밀리그람 / 영양제: 칼슘제, 칼슘 강화 주스, 우유·요구르트', '방광염으로 시프로플록사신을 처방받은 50대 여성이 아침 약을 칼슘제·우유와 함께 먹는다.', 'moderate', 'separate_timing', '시프로플록사신은 칼슘제 복용 1~2시간 전 또는 4시간 이후에 먹고, 레보플록사신은 전후 2시간을 피한다. 우유·칼슘 강화음료만으로 약을 삼키지 않는다(식사 중 칼슘은 영향이 작음).', '식약처원문', 'high', '씨프로바이 허가사항상 고용량 칼슘 보충제 영향은 ''임상적으로 관련성이 없는 것으로 보인다''는 아벨록스(목시플록사신) 문구처럼 성분마다 차이가 있다. 목시플록사신은 칼슘 영향이 작다. | 다른 리서처 서술: 탄산칼슘 850 mg 4정을 5분 전에 먹으면 시프로플록사신의 상대 생체이용률이 대조군의 약 60%로 떨어졌다. 칼슘 강화 오렌지주스와 함께 먹었을 때는 Cmax가 41%, 24시간 AUC가 38% 줄었다. 혈중 농도가 낮아지면 치료 실패와 내성 위험이 커진다.', False),
  (138, '미네랄-의약품', '칼슘', '칼슘 보충제·칼슘 함유 제산제를 같은 시간대에 복용', '알렌드로네이트', '경구 비스포스포네이트(알렌드로네이트·리세드로네이트·이반드로네이트)', 'drug', '약효감소', '원래도 1% 미만인 비스포스포네이트 흡수가 더 줄어 골다공증 치료 효과가 떨어진다. 알렌드로네이트를 아침 식사와 동시에 먹으면 생체이용률이 85% 넘게 줄었다.', '칼슘 이온(Ca2+)이 비스포스포네이트의 포스포네이트기와 결합', '비스포스포네이트는 2가 양이온과 잘 결합하는 구조다. 칼슘과 장 안에서 녹지 않는 복합체를 만들어 흡수되지 않는다.', '약: 포사맥스70밀리그램정, 포사맥스플러스디정, 악토넬정35·150밀리그램, 본비바정150밀리그램 / 영양제: 칼슘제, 디카맥스1000정, 칼트레이트디400정', '골다공증 주 1회 약을 먹는 60대 여성이 같은 날 아침 약과 칼슘제를 함께 삼킨다.', 'moderate', 'separate_timing', '비스포스포네이트는 아침 공복에 물로만 먹는다. 칼슘제와 다른 약은 알렌드로네이트 후 최소 30분, 이반드로네이트 후 최소 1시간 뒤에 먹는다. 리세드로네이트는 첫 음식 30분 전 또는 음식 섭취 2시간 이상 뒤에 먹는다.', '식약처원문', 'high', '칼슘·비타민D 보충 자체는 비스포스포네이트 치료에 필요하므로 끊으라는 뜻이 아니다. 시간만 떼면 된다. | 다른 리서처 서술: 리세드로네이트 복용 뒤 칼슘 600 mg/비타민D 400 IU 보충제를 먹으면 리세드론산 흡수율이 약 38% 줄었다. 알렌드로네이트는 원래 생체이용률이 1% 미만이라 식사와 동시에 또는 식후 2시간에 먹으면 85% 넘게 줄어든다. 골밀도 개선과 골절 예방 효과가 떨어진다.', False),
  (139, '미네랄-의약품', '칼슘', '칼슘 함유 제산제(탄산칼슘 등)', '페니토인', '항경련제(히단토인계)', 'drug', '약효감소', '페니토인 혈중농도가 감소해 발작 조절이 나빠질 수 있다. 탄산칼슘은 페니토인 AUC를 유의하게 낮췄다.', '칼슘(탄산칼슘)이 페니토인 흡수를 방해(흡착·용해도 변화)', '제산제가 위장 pH와 페니토인 용해도를 바꾸고 약물을 흡착해 흡수량과 흡수 속도를 줄인다.', '약: 환인히단토인정(페니토인) / 영양제·약: 탄산칼슘 칼슘제, 칼슘 함유 제산제', '뇌전증으로 페니토인을 먹는 60대가 속쓰림에 칼슘 제산제를 같은 시간에 자주 먹는다.', 'moderate', 'caution', '칼슘 함유 제산제·칼슘제와 페니토인은 시간 간격을 두고(보통 2시간 이상), 필요하면 혈중농도를 확인한다.', '식약처원문', 'medium', null, False),
  (140, '미네랄-의약품', '칼슘', '칼슘 보충제(특히 탄산칼슘 1 g 이상)와 비타민D를 장기간 함께 먹을 때. 신기능 저하, 부갑상선 질환, 활성형 비타민D 복용자에서 위험 증가', '히드로클로로티아지드', '티아지드계·유사 이뇨제(클로르탈리돈, 인다파미드), ARB·ACE억제제와의 고혈압 복합제 포함', 'drug', '영양소_과잉_독성', '티아지드가 소변으로 나가는 칼슘을 줄여 혈청 칼슘이 오른다. 증례에서 61세 남성이 탄산칼슘 1200 mg/일과 비타민D 1000 IU를 장기간 먹으면서 티아지드·ACE억제제를 복용하다 고칼슘혈증 위기, 신부전, 대사성 알칼리증으로 응급 투석을 받았다. 다른 증례에서는 혈청 칼슘이 23 mg/dL까지 올랐다(칼슘-알칼리 증후군).', '보충제 칼슘 + 티아지드의 신장 칼슘 재흡수 증가', '티아지드는 원위세뇨관에서 칼슘 재흡수를 늘려 소변 칼슘 배설을 줄인다. 여기에 칼슘·비타민D 보충이 더해지면 칼슘이 쌓여 고칼슘혈증, 탈수, 신기능 저하가 서로를 악화시킨다.', '약: 다이크로짇정(히드로클로로티아지드), 코자플러스정(로사르탄/HCTZ), 미카클로정(텔미사르탄/클로르탈리돈), 인다파미드 제제 / 영양제: 칼슘·비타민D 영양제, 디카맥스디정', '고혈압 복합제(ARB+이뇨제)를 먹는 60대 여성이 골다공증 예방으로 고용량 칼슘·비타민D를 매일 복용', 'moderate', 'monitor', '칼슘 보충이 필요하면 혈청 칼슘을 모니터링하고 용량을 조절한다(국내 허가사항). 구역, 변비, 피로, 혼동 같은 고칼슘혈증 증상이 생기면 진료를 받는다.', '식약처원문', 'high', '단독 티아지드 국내 허가사항(다이크로짇정)에는 칼슘염 문구가 없고 복합제 허가사항에 있다. 대부분은 일시적이지만 부갑상선항진증 환자에서는 지속될 수 있다.', True),
  (144, '미네랄-의약품', '크롬', '피콜린산크롬(혈당·다이어트 영양제)을 레보티록신과 동시 복용할 때', '레보티록신', '갑상선호르몬제', 'drug', '약효감소', '정상인 7명에게 레보티록신 1 mg과 피콜린산크롬을 같이 주었을 때 혈청 티록신 AUC가 유의하게(p<0.05) 줄었다. 장기 병용 시 갑상선저하 조절이 나빠질 수 있다.', '피콜린산크롬(크롬 3가)과 레보티록신의 장관 내 불용성 복합체 형성 추정', '연구진은 장 안에서 레보티록신과 녹지 않는 복합체가 생겨 흡수가 줄어든다고 추정한다. 정확한 결합 기전은 밝혀지지 않았다.', '약: 씬지로이드정 등 / 영양제: 피콜린산크롬 함유 혈당 영양제·체지방 감소 영양제', '갑상선약을 먹는 50대가 혈당 관리용 크롬 영양제를 아침에 같이 복용', 'minor', 'separate_timing', '크롬 영양제와 레보티록신은 몇 시간 간격을 둔다(논문 권고). 병용을 시작한 뒤 TSH를 확인한다.', 'RCT/약동학연구', 'medium', '정상인 7명 단회 투여 연구 하나뿐이고 국내 허가사항에는 크롬 언급이 없다.', False),
  (145, '미네랄-의약품', '크롬', '크롬 건강기능식품(당뇨병이 있는 경우)', '메트포르민', '당뇨병 치료제(혈당강하제 전반)', 'drug', '기타', '당뇨병 환자가 크롬을 먹으면 혈당 조절에 영향을 줄 수 있어 전문가 상담이 필요하다(원문은 질환 기준이며 결과를 명시하지 않음). 혈당강하제와 함께라면 저혈당 가능성이 이론적으로 있다.', '크롬(3가)이 인슐린 신호 전달을 증강한다고 제시됨', '크롬은 ''체내 탄수화물, 지방, 단백질 대사에 관여''(고시 기능성 내용)하며 인슐린 작용을 돕는 것으로 제시된다. 혈당강하제와 함께 쓰면 혈당 하강 효과가 더해질 수 있다(이론적).', '약: 글루코파지정, 다이아벡스정, 설포닐우레아·인슐린 / 영양제: 크롬 함유 혈당 건강기능식품, 크롬 함유 종합비타민', '당뇨약을 먹는 60대가 ''혈당 관리''용 크롬 건강기능식품을 추가로 먹는다.', 'minor', 'consult', '당뇨병이 있으면 크롬 제품을 먹기 전에 의사·약사와 상담하고, 시작 후 혈당을 관찰한다.', '식약처원문', 'low', '주의: 식약처 원문은 ''당뇨병이 있는 경우''라는 질환 기준 문구이며 특정 약물을 지목하지 않는다. 메트포르민은 대표 예시로만 적었다. 같은 고시(제2020-92호)는 칼륨에 ''신장질환, 위장관질환 등이 있는 경우 섭취 전 전문가와 상담'', 베타카로틴에 ''흡연자는 섭취 시 전문가와 상담''을 신설했다(약물 조합이 아니라 행으로 만들지 않음).', False),
  (146, '미네랄-의약품', '크롬', '크롬 보충제(특히 피콜린산크롬 하루 200 μg 초과)를 혈당강하제와 함께 먹을 때', '인슐린', '인슐린·경구 혈당강하제(설포닐우레아, 메트포르민 등)', 'drug', '약효증가_독성', '메타분석에서 크롬 보충은 HbA1c를 0.55%, 공복혈당을 1.15 mmol/L 낮췄다. 당뇨약과 함께 쓰면 혈당이 추가로 떨어져 저혈당 가능성이 이론적으로 있다. 같은 메타분석에서 위약 대비 이상반응 증가는 없었다.', '3가 크롬의 인슐린 신호 증강 작용', '크롬은 인슐린 수용체 신호를 도와 포도당 이용을 늘리는 것으로 생각된다. 혈당강하제의 효과에 더해지면 혈당이 예상보다 더 내려갈 수 있다.', '약: 인슐린 주사, 글리메피리드 등 설포닐우레아, 메트포르민 / 영양제: 피콜린산크롬 혈당 영양제, 크롬 함유 종합비타민', '인슐린을 맞는 60대 당뇨 환자가 혈당에 좋다는 크롬 영양제를 새로 시작', 'minor', 'monitor', '크롬 보충제를 시작하면 혈당을 평소보다 자주 재고, 저혈당 증상이 있으면 의사와 약 용량을 상의한다.', '이론적', 'low', '크롬 병용으로 저혈당이 생긴 직접 보고는 찾지 못했다(NIH ODS 접근 차단으로 ODS 인용 근거도 확인 못 함). 혈당 개선 효과 자체도 연구마다 엇갈린다.', True),
  (147, '비타민-비타민', '비타민B3(나이아신)', '니코틴산 형태 고용량(수백 mg~g), 특히 서방형. 직구 나이아신 단일제 + 종합비타민·B군 중복', '비타민B3(나이아신)', '다른 나이아신 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '홍조·가려움, 위장장애, 간독성. 무작위 이중맹검 비교에서 서방형 니아신(500→3,000 mg/일 증량) 23명 중 12명(52%)에서 간독성, 즉시형은 0명.', '니코틴산(서방형은 간 대사 경로 포화로 간독성 증가)', '니코틴산은 피부 혈관의 프로스타글란딘 분비로 홍조를 일으킨다. 서방형은 천천히 흡수되며 간의 아미드화 경로로 주로 대사되어 간세포 독성이 커진다.', '해외 직구 나이아신 500 mg(플러시·노플러시) + 고함량 B군·종합비타민', '콜레스테롤에 좋다는 말을 듣고 직구 서방형 나이아신 500 mg을 하루 여러 알 먹는 60대', 'moderate', 'caution', '고용량 니코틴산은 의사 관리 없이 복용하지 않음. 제품 합산 확인, 피로·식욕저하·황달 시 간기능 검사', 'RCT/약동학연구', 'medium', '국내 건강기능식품의 나이아신 함량은 대개 낮아 문제는 주로 직구 고용량 제품. 니코틴아미드는 홍조가 거의 없음. 스타틴 병용 근육병증은 다른 영역. 한국인 나이아신 상한섭취량 원문 미확인.', True),
  (148, '비타민-비타민', '베타카로틴', '보충제 고용량(시험에서는 하루 30 mg) + 레티놀 고용량(25,000 IU) 병용, 흡연자·과거 흡연자·석면 노출자', '비타민A', '지용성 비타민(기성형 레티놀)', 'supplement_nutrient', '기타', '흡연자 등 18,314명 대상 CARET 시험에서 베타카로틴 30 mg + 레티놀 25,000 IU 4년 복용 군의 폐암 RR 1.28(1.04~1.57), 전체 사망 RR 1.17, 폐암 사망 RR 1.46. 이득이 없고 해로워 시험이 21개월 조기 중단됨.', '고용량 베타카로틴(+레티놀) 보충제', '흡연으로 산화 스트레스가 큰 폐 조직에서 고용량 베타카로틴이 산화 분해산물을 만들고 레티노산 신호를 교란해 발암을 촉진한다는 가설이 제시됨. 기전은 확정되지 않음.', '베타카로틴 함유 눈 영양제, 베타카로틴+레티놀 함유 종합비타민, 간유', '담배를 피우는 50대 아버지에게 자녀가 눈 영양제(베타카로틴)와 종합비타민을 함께 사드림', 'major', 'avoid', '흡연자·최근 금연자·석면 노출자는 베타카로틴과 고용량 비타민A 보충제를 피함(채소·과일로 먹는 것은 해당 없음). 종합비타민은 베타카로틴이 없거나 적은 제품 선택', '식약처원문', 'high', '비흡연자에서 위험 증가 근거는 없음. 식약처는 2020-92호 고시로 베타카로틴 등의 ''섭취 시 주의사항''을 신설했으나, 그 문구 원문(첨부 hwp)은 열어보지 못함.', True),
  (149, '비타민-비타민', '베타카로틴', '장기 고용량 보충(하루 15~60 mg, 9개월)', '비타민E', '지용성 비타민(항산화)', 'supplement_nutrient', '영양소_흡수감소_결핍', '무작위 이중맹검 시험에서 베타카로틴 장기 복용 시 혈장 α-토코페롤이 점진적으로 감소, 9개월째 기저 대비 최대 40% 감소. 15~60 mg 모든 용량에서 비슷한 감소.', '고용량 베타카로틴', '카로티노이드와 토코페롤은 장 미셀·킬로미크론과 지단백 운반 경로를 공유해 흡수·조직 분포에서 경쟁한다. 고용량 베타카로틴이 비타민E를 소모시키거나 흡수를 줄이는 것으로 추정.', '고함량 베타카로틴 영양제·눈 영양제 + 비타민E 영양제·종합비타민', '눈 건강용 베타카로틴 고함량 제품을 1년 가까이 먹는 50대', 'minor', 'caution', '베타카로틴은 고용량 단일제 장기 복용을 피하고 식품 위주로', 'RCT/약동학연구', 'low', '45명 소규모 시험이며 임상적 비타민E 결핍 증상은 보고되지 않음.', True),
  (150, '비타민-비타민', '비타민A', '같은 성분 중복: 레티놀 형태 합계가 성인 상한(3,000 μg RAE, 약 10,000 IU) 초과, 임신 가능 여성은 하루 5,000 IU 이상', '비타민A', '다른 비타민A 함유 제품(간유·종합비타민·눈 영양제 중복)', 'supplement_nutrient', '영양소_과잉_독성', '기형 유발: 보충제로 하루 10,000 IU 초과 섭취 시 두개신경능 기형 유병비 4.8, 보충 비타민A 약 10,000 IU/일에서 역치. 간독성: 41례 분석에서 하루 25,000 IU 6년 복용으로 간경변 발생. 골다공증·골절 위험 증가(별도 행).', '기성형 비타민A(레티놀, 레티닐팔미테이트·아세테이트)', '레티놀은 간 성상세포에 저장되며 배출이 느려 장기간 과량이면 간 섬유화·간경변을 일으킨다. 레티노산은 배아 발생 유전자를 조절해 임신 초기 과량 시 신경능 유래 조직 기형을 유발한다.', '아이간유연질캡슐 등 간유, 멀티비타원프리미엄정 등 종합비타민, 눈 영양제(비타민A), 해외 고함량 비타민A 직구 제품', '임신을 준비하는 30대 딸이 종합비타민 + 간유 + 눈 영양제를 동시에 먹음', 'major', 'avoid', '레티놀 형태 비타민A는 모든 제품 합산해 상한 미만, 보충은 하루 5,000 IU를 넘지 않게. 임신 가능 여성은 레티놀 고함량 제품 중복을 피하고 베타카로틴 형태 선택', '식약처원문', 'high', '베타카로틴 형태는 필요량만 전환되어 기형·간독성 위험이 낮음(흡연자 폐암은 별도 행).', True),
  (151, '비타민-비타민', '비타민A', '레티놀(레티닐팔미테이트 등 기성형 비타민A) 고용량. 간유+종합비타민+눈 영양제 중복으로 하루 1.5~2 mg(약 5,000~6,600 IU) 이상 장기', '비타민D', '지용성 비타민(장 칼슘 흡수·골대사 조절)', 'supplement_nutrient', '기타', '비타민A가 비타민D의 칼슘 흡수 작용을 약화시켜 골 건강에 불리할 수 있다. 교차시험에서 레티닐팔미테이트 15 mg은 1,25(OH)2D3에 의한 혈청 칼슘 상승을 2.3%에서 1.4%로 줄임. 관찰연구에서 레티놀 1 mg/일 증가마다 고관절 골절 위험 68% 증가(Melhus), 레티놀 2,000 μg/일 이상 RR 1.89(Feskanich). 식약처 간유 허가사항: 장기 고용량 비타민A는 폐경 후 여성 골다공증 위험 증가.', '레티놀·레티노산(베타카로틴에서 전환된 것은 해당 적음)', '레티노산과 활성형 비타민D는 모두 핵수용체 파트너인 RXR을 공유해 신호가 서로 간섭한다. 고용량 레티놀은 장 칼슘 흡수에 대한 비타민D 반응을 둔화시키고 파골세포 활성을 높여 골밀도를 낮출 수 있다.', '아이간유연질캡슐 등 간유, 레티놀 함유 종합비타민·눈 영양제 + 비타민D 단일제(디맥정 등)·칼슘D 복합제', '골다공증 예방으로 비타민D를 먹는 60대 여성이 간유·종합비타민·눈 영양제를 함께 먹어 레티놀이 상한 근처까지 쌓임', 'moderate', 'caution', '비타민A는 레티놀 형태 합계를 줄이고(성인 상한 3,000 μg RAE), 폐경 후 여성·골다공증 위험군은 베타카로틴 형태 제품을 선택. 간유+종합비타민 중복 확인', '식약처원문', 'medium', 'Johansson 2001은 9명 단기 교차시험, 골절 연구는 관찰연구라 인과는 확정되지 않음. 베타카로틴은 골절 위험과 유의한 연관 없음(Feskanich).', True),
  (152, '비타민-비타민', '비타민B6', '같은 성분 중복: 고함량 B군 + 마그네슘·B6 복합제 + 종합비타민 합산 하루 50 mg 이상 장기(식약처), 수백 mg~g 고용량', '비타민B6', '다른 비타민B6(피리독신) 함유 제품', 'supplement_nutrient', '영양소_과잉_독성', '말초 감각신경병증(손발 저림·감각이상·보행실조). 식약처: 하루 50 mg 이상 장기 투여 시 말초신경병증 보고, 하루 500 mg~2 g 장기 복용 시 감각신경병. 1983년 NEJM 7례: 고용량 피리독신 후 심한 감각신경 장애, 중단 후 호전.', '피리독신(피리독신염산염)', '과량의 피리독신이 활성형 PLP 효소 결합을 경쟁적으로 방해하거나 후근신경절 감각신경세포에 직접 독성을 주는 것으로 추정된다. 복용 중단 후 회복에 수개월이 걸릴 수 있다.', '뉴로비정(피리독신 50/300 mg), 고함량 비타민B군 일반의약품, 마그네슘+B6 영양제, 종합비타민', '피로 때문에 고함량 B군 영양제와 마그네슘·B6 복합제, 종합비타민을 함께 먹는 50대가 손발 저림을 당뇨 신경병증으로 오인', 'moderate', 'caution', '모든 제품의 B6 함량 합산, 장기 고용량 피하기. 손발 저림이 생기면 중단하고 혈중 B6(PLP) 확인', '식약처원문', 'high', '호주 TGA는 여러 B6 제품을 함께 먹어 50 mg 미만에서도 신경병증이 생긴 보고가 있다고 경고했다고 알려졌으나 TGA 페이지가 열리지 않아 원문 미확인. 한국인 B6 상한섭취량 수치 원문 미확인.', True),
  (153, '비타민-비타민', '비타민C', '같은 성분 중복: 비타민C 1,000 mg 정제 + 발포 비타민 + 종합비타민 등 보충 하루 1,000 mg 이상, 수산칼슘 결석 병력', '비타민C', '다른 비타민C 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '수산칼슘 신장결석. 대규모 코호트에서 남성 보충 비타민C 1,000 mg/일 이상 HR 1.19(1.01~1.40), 총 비타민C 최고 범주 HR 1.43(여성은 연관 없음). 식약처: 수산결석 환자는 1일 1 g 이상 복용 금지, 과량 시 신장결석. 고용량 시 설사 등 위장장애(한국인 상한 설정 근거).', '아스코르브산이 체내에서 수산(옥살산)으로 대사', '흡수된 비타민C 일부가 옥살산으로 바뀌어 소변으로 나가고, 소변 옥살산이 늘면 칼슘과 결합해 수산칼슘 결석이 생긴다. 흡수되지 못한 고용량은 삼투성 설사를 일으킨다.', '유한비타민씨정1000mg, 고려은단 비타민C1000, 메가도스 제품, 발포 비타민, 종합비타민', '결석 병력이 있는 50대 남성이 메가도스로 비타민C 1,000 mg을 하루 3~6알씩 먹음', 'moderate', 'caution', '보충 비타민C 합계 확인(한국인 성인 상한 2,000 mg/일), 결석 병력자는 1 g 이상 피하기, 물 충분히', '식약처원문', 'high', '여성에서는 유의한 연관이 없었음(Ferraro 2016, 관찰연구).', True),
  (154, '비타민-비타민', '비타민C', '고용량 비타민C를 B12와 같은 시각에 복용', '비타민B12', '수용성 비타민(코발라민)', 'supplement_nutrient', '영양소_흡수감소_결핍', '1974년 시험관 연구가 비타민C가 식사 속 B12를 파괴한다고 보고했으나, 1976년 두 독립 실험실 재현 연구에서 유해 영향이 없었다. 사람에서 결핍을 일으킨다는 근거는 없음.', '아스코르브산(환원제)', '시험관에서 비타민C가 코발라민을 분해한다는 가설. 표준 분석법으로는 재현되지 않아 측정 방법 문제로 해석됨.', '비타민C 1,000 mg + B12 함유 B군 복합제', 'B12 결핍으로 B12를 먹는 60대가 비타민C 1,000 mg을 같이 삼킴', 'minor', 'caution', '임상적 대처 필요성은 낮음. 걱정되면 1~2시간 간격', '이론적', 'low', '근거 강도 확인 결과: 원 보고(Herbert & Jacob 1974, 초록 없음)는 반박됨. 흔한 ''같이 먹지 말라'' 주장은 근거가 약함.', True),
  (155, '비타민-비타민', '비타민D', '같은 성분 중복: 비타민D 단일제(1,000~5,000 IU) + 종합비타민 + 칼슘·D 복합제 + 고용량 비타민D 주사·경구액', '비타민D', '다른 비타민D 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '비타민D 중독에 따른 고칼슘혈증(구역·구토·다뇨·갈증·부정맥·급성신부전·신장결석). 비타민D 중독 보고의 75%가 2010년 이후이며 다수가 고용량 일반 판매 제품·비허가 제제 사용 등 예방 가능한 원인.', '콜레칼시페롤(비타민D3)·에르고칼시페롤 과량 → 25(OH)D 과잉', '비타민D는 지용성이라 지방조직에 축적되고, 과량 시 25(OH)D가 수용체를 직접 자극해 장 칼슘 흡수와 뼈 흡수를 모두 높인다. 여러 제품을 합치면 본인이 모르는 사이 상한을 넘기기 쉽다.', '디맥정(콜레칼시페롤), 디3베이스 경구액, 비타민D 1,000/2,000/5,000 IU 영양제, 종합비타민, 칼슘·D 복합제, D3베이스주 등 고용량 주사', '병원에서 비타민D 주사를 맞은 60대가 집에서 비타민D 5,000 IU 영양제와 칼슘·D 복합제를 계속 먹음', 'moderate', 'monitor', '모든 제품의 비타민D 함량을 합산. 주사를 맞았으면 경구 고용량은 상담 후 조정. 장기 고용량 복용 시 25(OH)D·혈청 칼슘 측정', '식약처원문', 'high', '식약처 콜레칼시페롤 허가사항은 다른 비타민D 제제 복용 시 용량 조절과 하루 500 IU 이상 투여 시 칼슘·신기능 모니터링을 요구. 한국인 비타민D 상한섭취량 수치 원문은 이번에 확인하지 못함.', True),
  (156, '비타민-비타민', '비타민E', '고용량 보충(라벨상 ''고용량'', 연구는 하루 1,000 IU RRR-α-토코페롤 12주)', '비타민K', '지용성 비타민(응고인자 감마-카르복실화 보조인자)', 'supplement_nutrient', '출혈위험', '고용량 비타민E가 비타민K의 흡수와 작용을 저해해 응고 기능이 떨어질 수 있다. 무작위 시험에서 1,000 IU/일 12주 후 미카르복실화 프로트롬빈(PIVKA-II)이 1.7→11.9 ng/mL(류마티스 환자), 1.8→5.3 ng/mL(건강 남성)로 상승.', '고용량 α-토코페롤(및 그 대사체)이 비타민K 의존 카르복실화를 방해하고 흡수 경로에서 경쟁', '비타민E와 비타민K는 모두 지용성으로 장에서 미셀·킬로미크론 경로를 공유한다. 고용량 토코페롤 대사체가 비타민K 의존 감마-카르복실화효소를 저해해 응고인자가 덜 활성화된 형태(PIVKA-II)가 늘어난다.', '그랑페롤연질캡슐400IU, 고함량 토코페롤 직구 제품(400~1,000 IU) + 비타민K2(MK-7) 뼈 영양제·칼슘K2 복합제', '뼈 건강 때문에 칼슘·비타민K2 복합제를 먹는 60대 여성이 항산화 목적으로 비타민E 1,000 IU를 추가', 'moderate', 'caution', '비타민E는 고용량(400 IU 이상) 장기 보충을 피함. 흡수장애·간질환 등으로 비타민K가 부족하기 쉬운 사람, 항응고제 복용자는 상담. 멍·코피·잇몸 출혈 증가 시 중단', '식약처원문', 'medium', '응고 정상 성인에서는 PIVKA-II 상승만 확인되었고 실제 출혈 사건은 보고되지 않음. 와파린 복용자는 별도 행 참고. | 다른 리서처 서술: 고용량 비타민E가 비타민K의 흡수와 작용을 저해해 비타민K 상태가 나빠질 수 있다(PIVKA-II 상승).', True),
  (157, '비타민-비타민', '비타민E', '고용량 보충', '비타민A', '지용성 비타민', 'supplement_nutrient', '영양소_흡수감소_결핍', '고용량 비타민E가 체내에 저장된 비타민A를 고갈시킬 수 있다고 식약처 허가사항에 적혀 있다(수치 없음).', '고용량 α-토코페롤', '지용성 비타민끼리 미셀 흡수 경로를 공유해 경쟁하고, 고용량 토코페롤이 레티놀 저장·동원에 영향을 줄 수 있다는 가설. 사람 대상 정량 근거는 확인하지 못함.', '그랑페롤연질캡슐400IU + 비타민A 함유 종합비타민·눈 영양제', '눈 건강 때문에 비타민A 영양제를 먹는 50대가 비타민E 400 IU를 추가', 'minor', 'caution', '비타민E 고용량 장기 보충을 피하고, 필요하면 권장 수준으로 함께 복용', '식약처원문', 'low', '식약처 라벨 문구 외에 사람 대상 연구를 찾지 못함. | 다른 리서처 서술: 고용량 비타민E가 체내에 저장된 비타민A를 고갈시킬 수 있다(원문 표현).', True),
  (158, '비타민-비타민', '비타민B9(엽산)', '합성 엽산(폴산) 고용량. 엽산 1 mg 정제 또는 여러 제품 합산 하루 0.5~1 mg 이상을 비타민B12 결핍 상태에서 장기 복용', '비타민B12', '수용성 비타민(코발라민). 결핍 상태(악성빈혈, 위축성 위염, 메트포르민·위산억제제 장기 복용 등)', 'supplement_nutrient', '기타', 'B12 결핍이 있는 사람이 고용량 엽산을 먹으면 빈혈(혈액 수치)만 좋아져 결핍이 가려지고, 신경 손상(말초신경병증, 척수 변성, 인지저하)은 계속 진행할 수 있다. 미국 노인 1,459명 분석에서 B12가 낮은 군의 혈청 엽산 고농도는 빈혈 OR 3.1(95% CI 1.5~6.6), 인지장애 OR 2.6(1.1~6.1)과 연관.', '엽산(폴산)이 B12와 무관하게 DNA 합성을 회복시켜 거대적아구성 빈혈만 교정함', 'B12 결핍 시 메틸말로닐-CoA·메티오닌 합성 경로가 막혀 빈혈과 신경 손상이 함께 생긴다. 고용량 엽산은 빈혈 경로만 우회 교정하므로 혈액검사로 결핍을 발견하기 어려워지고, 일부 연구자는 엽산이 B12 수요를 늘려 신경 증상을 악화시킨다고 본다.', '녹십자폴산정·신신폴산정(폴산 1 mg), 맘스폴릭정1000, 엽산 영양제 + 엽산 함유 종합비타민', '메트포르민을 10년째 먹는 60대가 ''혈액에 좋다''며 엽산 1 mg 정제와 종합비타민을 같이 먹어 빈혈 수치는 정상인데 손발 저림과 건망증이 심해짐', 'major', 'consult', '엽산 고용량 복용 전 B12(가능하면 메틸말론산) 검사. 결핍이면 B12를 함께 보충. 50세 이상, 메트포르민·PPI 장기 복용자는 B12 정기 확인. 보충 엽산 합계 하루 1 mg 이하 유지', '식약처원문', 'high', '식약처 폴산정 허가사항은 B12 결핍 악성빈혈 환자에게 금기이며, 악성빈혈 환자에는 B12 병용과 은폐 주의를 명시. ''빈혈을 가린다''를 넘어 신경학적 악화를 촉진한다는 주장(Reynolds 2016)은 논쟁 중. Morris 2007은 관찰연구(인과 아님). | 다른 리서처 서술: 엽산이 빈혈 수치만 개선해 B12 결핍(악성빈혈)을 가린다. 그 사이 신경 손상(말초신경병증·인지 저하)은 진행되어 진단과 치료가 늦어진다. B12가 낮은 고령자에서 높은 혈청 엽산은 빈혈·인지장애와 연관되었다. / 엽산이 빈혈 수치만 개선해 B12 결핍 진단을 가리고, 그동안 신경증상(저림, 보행장애)은 계속 진행함', True),
  (159, '비타민-미네랄', '비타민C', '비타민C를 셀레늄(아셀렌산나트륨) 제제와 동시 복용', '셀레늄', '셀레늄 제제(아셀렌산나트륨, 의약품 셀레나제)', 'supplement_nutrient', '영양소_흡수감소_결핍', '환원제인 비타민C가 아셀렌산나트륨을 침전시켜 셀레늄 제제가 효과를 내지 못한다.', '아스코르브산(환원제)이 셀레나이트(SeO3 2-)를 불용성 원소 셀레늄으로 환원', '비타민C가 위장관에서 셀레나이트를 0가 원소 셀레늄으로 환원하면 침전이 생기고 흡수되지 않는다.', '약: 셀레나제100마이크로그램퍼오랄액·셀레나제티퍼오랄액(아셀렌산나트륨) / 영양제: 고려은단·유한 비타민C 1000 등 고함량 비타민C', '셀레늄 결핍으로 셀레나제 액을 처방받은 60대가 아침에 비타민C 1000 mg과 함께 먹는다.', 'moderate', 'separate_timing', '함께 먹지 말고, 비타민C를 먹으려면 셀레나제와 약 4시간 간격을 둔다.', '식약처원문', 'high', '셀레노메티오닌 등 유기 셀레늄 건강기능식품에도 같은 상호작용이 있는지는 확인하지 못했다. 인체 74Se 연구(AJCN 1989)는 비타민C 섭취가 부족하면 셀레나이트 흡수·보유가 오히려 줄었다고 보고했으므로, 문제는 ''동시 섭취 시 화학적 침전''에 국한된다. | 다른 리서처 서술: 식약처 허가사항: 비타민C 같은 환원제가 아셀렌산나트륨을 침전시켜 셀레늄 흡수가 떨어지므로 함께 복용하지 말고 약 4시간 간격을 둘 것.', False),
  (160, '비타민-미네랄', '비타민C', '하루 200 mg 이상을 철분제와 함께. 특히 혈색소침착증·철 과잉 소인이 있거나 빈혈 진단 없이 장기 복용', '철분', '무기질(비헴철 보충제)', 'supplement_nutrient', '영양소_과잉_독성', '식약처 허가사항: 비타민C 200 mg 이상과 함께 먹으면 철 흡수가 증가. 철 과부하(혈색소침착증) 환자에서는 간·심장·췌장 철 침착이 악화될 수 있다. 증례: 1년간 고용량 비타민C를 먹은 청년이 급속히 진행한 심근병증으로 사망, 부검에서 혈색소침착증 확인.', '아스코르브산이 3가 철을 2가 철로 환원·킬레이트화해 비헴철 흡수를 높임', '비헴철은 2가 형태로 DMT1을 통해 흡수되는데, 비타민C는 철을 환원하고 가용성 복합체를 만들어 흡수를 높인다. 철 배설 경로가 없는 몸에서 철 흡수 조절이 고장 난 혈색소침착증 환자는 철이 장기에 쌓인다.', '훼로바-유서방정·볼그레·철분 영양제 + 유한비타민씨정1000mg·고려은단 비타민C1000 등 고용량 비타민C', '빈혈 검사 없이 ''피로 회복''용으로 철분제와 비타민C 1,000 mg을 수년간 함께 먹는 50대 남성(혈색소침착증 미진단)', 'moderate', 'caution', '빈혈·페리틴 확인 후 철분 복용. 혈색소침착증·철 과잉·잦은 수혈자는 철분제와 고용량 비타민C 보충을 피하고 상담', '식약처원문', 'medium', '철 결핍성 빈혈 치료 중에는 흡수를 돕는 유익한 조합이다. 하루 전체 식사 기준으로는 비타민C의 흡수 증가 효과가 단일 식사보다 훨씬 작다(Cook 2001). 한국인에게 유전성 혈색소침착증은 드묾. 식약처 철분제 허가사항은 혈색소증 환자를 복용 금지 대상으로 명시. | 다른 리서처 서술: 철분 흡수가 증가한다. 일반인에게는 유익할 수 있지만 혈색소증·철과잉 환자에게는 철 축적을 악화시킬 수 있다.', True),
  (161, '비타민-미네랄', '비타민C', '고용량(연구는 하루 1,500 mg, 64일)', '구리', '미량 무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '젊은 남성이 비타민C 1,500 mg/일을 64일 먹자 혈청 세룰로플라스민 활성이 모든 측정 시점에서 유의하게 감소(정상 범위 안), 중단 20일 후 혈청 구리가 유의하게 상승.', '아스코르브산이 구리 흡수·세룰로플라스민 산화효소 활성을 방해', '비타민C가 2가 구리를 1가로 환원해 장 흡수와 체내 이용에 영향을 주고, 세룰로플라스민의 페록시다아제 활성을 낮추는 것으로 추정된다. 동물에서 먼저 확인된 길항 관계.', '비타민C 1,000 mg 이상 메가도스 제품 + 구리 함유 종합비타민', '감기 예방으로 비타민C 1,000~2,000 mg을 매일 먹는 50대', 'minor', 'caution', '비타민C 메가도스 장기 복용은 피하고, 이미 구리가 부족하기 쉬운 경우(아연 고용량 복용, 위 수술) 함께 주의', 'RCT/약동학연구', 'medium', '변화는 정상 범위 안이어서 임상적 구리 결핍은 보고되지 않음.', True),
  (162, '비타민-미네랄', '비타민D', '비타민D 보충 + 칼슘 보충제 장기 병용, 특히 고용량·여러 제품 중복, 신장결석 병력·신기능 저하', '칼슘', '무기질(칼슘 보충제·탄산칼슘 제산제)', 'supplement_nutrient', '영양소_과잉_독성', '고칼슘혈증·고칼슘뇨증·신장결석. WHI 시험(칼슘 1 g+비타민D 400 IU, 7년)에서 요로결석 HR 1.17(1.02~1.34). 재분석 메타분석에서 칼슘(±비타민D) 심근경색 RR 1.24(1.07~1.45). 칼슘-알칼리 증후군 증가의 주원인으로 일반의약품 칼슘·비타민D 보충제가 지목됨.', '비타민D가 장 칼슘 흡수를 높이고, 여기에 칼슘 부하가 더해짐', '활성형 비타민D가 장 칼슘 흡수와 뼈 칼슘 동원을 늘려 혈중·요중 칼슘이 오르고, 소변 칼슘 증가로 수산칼슘·인산칼슘 결석이 생긴다. 혈중 칼슘이 급격히 오르면 혈관 석회화·심혈관 사건과의 연관도 제기된다.', '디카맥스디플러스정·디카맥스디정 등 칼슘·비타민D 복합 일반의약품, 칼슘·마그네슘·비타민D 영양제, 디맥정(콜레칼시페롤), 종합비타민', '골다공증 약과 함께 처방받은 칼슘·D 복합제 외에 홈쇼핑 칼슘·마그네슘·D 영양제를 따로 더 먹는 60대 여성', 'moderate', 'monitor', '식사 포함 칼슘 총량을 따져 보충제는 필요한 만큼만(1회 500 mg 이하로 나눠). 비타민D·칼슘 함유 제품 합산. 신장결석 병력이면 상담. 장기 복용 시 혈청·요 칼슘 검사', '식약처원문', 'high', '칼슘 보충제와 심혈관 위험의 연관은 연구마다 결과가 다르고 논쟁 중. 결석 위험은 WHI에서 일관되게 관찰됨.', True),
  (163, '비타민-미네랄', '비타민E', '하루 체중 kg당 10 IU 이상(어린이), 철분제 투여 중', '철분', '무기질(철분제)', 'supplement_nutrient', '기타', '식약처 허가사항: 철결핍성 빈혈 어린이의 철분제 반응을 늦출 수 있고, 철을 공급받는 저체중 영아에게 비타민E 결핍성 용혈성 빈혈을 일으킬 수 있음. 철분제 허가사항도 비타민E 제제 복용자는 상담 대상으로 명시.', '고용량 토코페롤, 그리고 철의 산화 작용', '철은 지질 과산화를 촉진해 적혈구막의 비타민E를 소모시키고, 반대로 고용량 비타민E는 철분제에 대한 조혈 반응을 지연시키는 것으로 기술된다. 정확한 기전은 출처에 없음.', '그랑페롤연질캡슐 등 비타민E + 훼로바-유 등 철분제·어린이 철분 시럽', '손주에게 철분 시럽을 먹이는 60대 조부모가 비타민E도 함께 먹임', 'minor', 'consult', '철결핍 빈혈 치료 중인 어린이·영아에게 비타민E를 따로 줄 때는 소아과 상담', '식약처원문', 'medium', '주로 어린이·영아에 해당. 성인 근거는 찾지 못함. | 다른 리서처 서술: 철결핍성빈혈 어린이의 철분제 반응을 늦춘다. 반대로 철분 공급을 받는 저체중 영아에게는 비타민E 결핍성 용혈성 빈혈을 일으킬 수 있다.', True),
  (164, '비타민-미네랄', '비타민B9(엽산)', '엽산 보충(400 μg 격일), 아연 섭취가 낮은 식사', '아연', '미량 무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '남성 8명 대사연구에서 엽산 보충군은 저아연 기간 대변 아연이 유의하게 많았고, 모든 기간 요중 아연 배설이 약 50% 줄어 아연 항상성 변화(흡수 저해 시사). 아연 고섭취 기간에는 차이 없음.', '폴산(합성 엽산)', '엽산이 장관에서 아연과 불용성 킬레이트를 만들어 흡수를 방해할 수 있다고 저자들이 추정.', '엽산 영양제·임산부 엽산 + 아연 영양제', '엽산을 먹는 사람이 아연이 부족한 식사를 계속하는 경우', 'minor', 'caution', '특별한 조치 근거는 약함. 아연 섭취가 낮은 사람은 식사로 아연 보충', 'RCT/약동학연구', 'low', '소규모 단일 연구. 이후 재현 근거를 찾지 못함.', True),
  (165, '미네랄-미네랄', '망간', '망간 보충제를 철과 동시에, 또는 철 결핍 상태에서 망간 고용량', '철분', '무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '망간이 수용액과 식사 모두에서 철 흡수를 경쟁적으로 억제. 반대로 페리틴이 낮은(철 결핍) 여성은 망간 흡수가 가장 많아 망간이 과다 흡수될 수 있다.', '2가 망간 이온', '망간과 철은 같은 2가 금속 수송체(DMT1)를 쓰기 때문에 서로 흡수를 경쟁한다. 철이 부족하면 수송체가 늘어나 망간 흡수도 함께 늘어난다.', '망간 함유 관절 영양제(글루코사민·콘드로이틴 복합), 종합미네랄 + 철분제', '관절 영양제(망간 함유)를 먹는 빈혈 있는 60대 여성이 철분제를 같은 시간에 복용', 'minor', 'separate_timing', '철분 치료 중에는 망간 함유 제품과 시간 간격. 철 결핍자는 망간 고함량 제품을 피함', 'RCT/약동학연구', 'medium', '망간 과잉 신경독성은 주로 직업 노출·간질환에서 보고되며 보충제 수준 근거는 이번에 찾지 못함.', True),
  (166, '미네랄-미네랄', '셀레늄', '같은 성분 중복: 셀레늄 단일제 + 종합비타민·항산화 복합제 합산 상한(400 μg/일) 초과, 또는 함량 오류 제품. 장기 200 μg/일', '셀레늄', '다른 셀레늄 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '셀레늄 중독(설사 78%, 피로 75%, 탈모 72%, 관절통, 손발톱 변형): 표시량의 200배가 든 액상 보충제로 10개 주 201명 발생, 섭취량 중앙값 41,749 μg/일. 200 μg/일 7.7년 무작위 시험에서 2형 당뇨 HR 1.55(1.03~2.33).', '셀레늄(아셀렌산나트륨·셀레늄 효모 등)', '과량 셀레늄은 황 함유 단백질(케라틴 등)에 잘못 끼어들어 모발·손톱을 손상하고 산화 스트레스를 일으킨다. 장기 고용량은 인슐린 신호에 영향을 주는 것으로 추정된다.', '셀레나제 등 셀레늄 제제, 셀레늄 효모 영양제, 항산화 복합제, 종합비타민', '갑상선에 좋다고 셀레늄 200 μg 영양제와 셀레늄 든 항산화 복합제, 종합비타민을 함께 먹는 50대', 'moderate', 'caution', '모든 제품 셀레늄 합산해 상한(400 μg/일) 미만. 장기 200 μg 이상 고용량은 당뇨 위험을 고려해 필요성 상담. 탈모·손톱 변화·마늘 냄새 입냄새 시 중단', '식약처원문', 'high', null, True),
  (167, '미네랄-미네랄', '아연', '보충제로 하루 50 mg 이상을 수주~수개월(한국인 상한 35 mg/일 초과). 아연 단일제 + 종합비타민·면역 영양제 중복', '구리', '미량 무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '구리 결핍으로 빈혈(철분제에 반응 없음)·호중구감소·척수병증(보행실조)·말초신경병증. 아연 50 mg/일 6주에 적혈구 SOD 감소(Fischer), 10주에 적혈구 SOD·페리틴 감소(Yadrick). 체계적 고찰 37례: 아연 약 50 mg~1,500 mg 이상/일, 거의 모두 빈혈, 모든 환자 혈청 구리 감소. 구리결핍 척수병증 11명 중 7명 혈청 아연 높음.', '아연이 장 상피세포의 메탈로티오네인을 유도해 구리를 붙잡음', '과량 아연은 장 상피세포에서 메탈로티오네인 합성을 크게 늘린다. 메탈로티오네인은 구리와 더 강하게 결합해 구리를 세포 안에 가두고, 상피세포가 탈락할 때 구리가 대변으로 빠져나가 몸 전체 구리가 고갈된다.', '아연 50 mg 직구 제품, 아연+비타민C 면역 영양제, 아연 트로키, 종합비타민', '감기 예방으로 아연 50 mg 직구 제품을 수개월 + 종합비타민을 먹던 60대가 빈혈이 생겨 철분제를 먹어도 낫지 않고 다리가 저리고 휘청거림', 'major', 'avoid', '보충 아연 합계를 상한(35 mg/일) 미만으로. 장기 고용량 복용자는 혈청 구리·세룰로플라스민 검사. 원인 불명 빈혈·호중구감소·보행장애 시 아연 복용력 확인', 'RCT/약동학연구', 'high', '구리 결핍 신경 손상은 구리 보충 후에도 일부만 회복될 수 있음. 의치 접착제(아연 함유)도 원인으로 보고됨.', True),
  (168, '미네랄-미네랄', '아연', '초고용량(황산아연으로 아연 142 mg/일)', '마그네슘', '무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '대사병동 연구에서 아연 142 mg/일이 마그네슘 흡수와 마그네슘 균형을 유의하게 감소(칼슘 섭취량 3군 합산).', '과량 아연 이온', '2가 양이온끼리 장관 흡수에서 경쟁하는 것으로 해석. 같은 연구진은 같은 용량 아연이 칼슘 흡수도 낮춘다고 보고.', '아연 고함량 직구 제품(50 mg 여러 알) + 마그네슘 영양제', '아연을 하루 100 mg 이상 임의로 먹는 50대', 'minor', 'caution', '아연은 상한(35 mg/일) 이내로', 'RCT/약동학연구', 'low', '상한의 4배 수준 초고용량에서의 소규모 대사연구. 일반 보충 용량에서의 의미는 불확실.', True),
  (169, '미네랄-미네랄', '요오드', '같은 성분 중복: 켈프·다시마 정제 + 요오드 함유 종합비타민(주로 해외 제품) + 해조류 많은 식단. 갑상선 질환자·고령·갑상선종', '요오드', '다른 요오드 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '요오드 유발 갑상선기능항진(빈맥성 부정맥·심부전), 기존 갑상선 질환 악화. 72세 여성이 켈프 정제 복용 중 갑상선기능항진, 중단 6개월 후 소실. 요오드 유발 갑상선중독 8례(평균 60.6세) 중 1례가 켈프 정제. 해조 보충제 분석에서 요오드 함량이 과잉을 일으킬 수준.', '과량 요오드(켈프 등 해조 추출물)', '자율성 결절이나 갑상선종이 있으면 과량 요오드를 받은 갑상선이 조절 없이 호르몬을 과다 생산한다(조드-바제도 현상). 반대로 자가면역 갑상선염에서는 요오드 과잉이 기능저하를 일으킬 수 있다.', '켈프·다시마 환, 해조칼슘, 요오드 함유 해외 종합비타민', '갑상선기능저하로 레보티록신을 먹는 60대가 ''갑상선에 좋다''는 다시마 환과 요오드 함유 종합비타민을 추가', 'moderate', 'consult', '갑상선 질환자는 요오드·해조 보충제 전 상담. 한국인은 식사 요오드가 이미 많으므로 보충제 중복을 피하고 TSH 확인', '증례보고', 'medium', '한국인 요오드 상한섭취량 수치 원문은 이번에 확인하지 못함. Henzen 1999는 독일어 논문(영문 초록 확인).', True),
  (170, '미네랄-미네랄', '철분', '같은 성분 중복: 철분제 + 철 함유 종합비타민 + 철 강화 제품, 빈혈 진단 없는 장기 복용. 어린이 우발 복용', '철분', '다른 철 함유 제품(중복 섭취)', 'supplement_nutrient', '영양소_과잉_독성', '만성 과량 시 혈철소침착증·혈색소침착증(간·췌장·심장 철 침착), 위장장애. 6세 이하 어린이가 철 함유제제를 과량 삼키면 중독사 가능(식약처 경고).', '무기철(황산제일철 등)', '사람은 철을 적극적으로 배설하는 경로가 없어, 흡수된 철이 필요량을 넘으면 페리틴·헤모시데린으로 장기에 쌓여 산화 손상을 일으킨다.', '훼로바-유서방정, 헤모큐, 볼그레, 철분 영양제, 철 함유 종합비타민', '빈혈 검사 없이 철분제와 철 함유 종합비타민을 수년간 먹는 60대, 또는 손주가 할머니 철분제를 사탕인 줄 알고 삼킴', 'major', 'caution', '빈혈·페리틴 확인 후 필요 기간만 복용, 철 함유 제품 중복 확인, 어린이 손이 닿지 않게 보관', '식약처원문', 'high', '한국인 철 상한섭취량 수치 원문은 이번에 확인하지 못함.', True),
  (171, '미네랄-미네랄', '철분', '공복에 무기철(황산제일철)과 무기아연(황산아연)을 철:아연 2:1 이상으로 동시에 고용량', '아연', '미량 무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '철:아연 비율 1:1은 아연 흡수를 약간, 2:1~3:1은 상당히 저해(헴철은 영향 없음). 반대로 아연:철 5:1(15 mg/3 mg) 수용액에서는 철 흡수 56% 감소(햄버거 식사와 함께는 영향 없음). 아연 50 mg 단독 보충은 페리틴을 낮춤.', '2가 철 이온과 아연 이온', '두 2가 금속 이온이 장관 내에서, 그리고 일부 수송 경로(DMT1 등)에서 경쟁한다는 해석. 음식과 함께 먹으면 경쟁 효과가 거의 사라진다.', '훼로바-유·볼그레 등 철분제 + 아연 영양제, 철·아연 함유 종합비타민', '빈혈로 철분제를 먹는 50대가 면역용 아연 영양제를 같은 공복 시간에 함께 삼킴', 'minor', 'separate_timing', '고용량 철과 아연 보충제는 2시간 이상 간격을 두거나 식사와 함께. 종합비타민은 균형 잡힌 비율 제품', 'RCT/약동학연구', 'medium', '식사 중 강화 수준에서는 영향이 관찰되지 않음(Whittaker 1998).', True),
  (172, '미네랄-미네랄', '칼슘', '칼슘 300~600 mg을 철분제 또는 철 함유 식사와 동시에', '철분', '무기질(철분제·비헴철·헴철)', 'supplement_nutrient', '영양소_흡수감소_결핍', '칼슘 300~600 mg은 철 흡수를 50~60% 줄이고 헴철 흡수도 유의하게 줄임. 식사와 함께 먹으면 모든 칼슘제가 철분제 흡수를 저해, 공복에서도 구연산칼슘·인산칼슘(칼슘 600 mg)은 철 흡수를 49%·62% 감소. 식약처 철분제 허가사항은 칼슘염 병용 금지.', '칼슘 이온이 장 점막 세포의 철 전달을 억제', '칼슘은 장 상피세포 안에서 철이 혈액 쪽으로 넘어가는 과정(점막 전달)을 방해하는 것으로 해석된다. 그래서 비헴철뿐 아니라 헴철 흡수도 줄어든다.', '디카맥스 등 칼슘제·칼슘 영양제 + 훼로바-유·볼그레·철분 영양제, 철과 칼슘이 함께 든 종합비타민', '빈혈 치료로 철분제를 처방받은 50대 여성이 아침에 칼슘제와 한 번에 삼킴', 'moderate', 'separate_timing', '철분제와 칼슘제는 2시간 이상 간격(철은 공복이나 식간, 칼슘은 다른 끼니). 빈혈 치료 중이면 철 단일제를 따로', '식약처원문', 'high', '장기 연구에서는 철 상태에 미치는 영향이 단회 흡수 연구보다 작다는 보고도 있으나, 빈혈 치료 중에는 분리 복용 권고. | 다른 리서처 서술: 철 흡수가 줄어 철결핍성 빈혈 치료 효과가 떨어진다. 칼슘 300~600 mg에서 철 흡수가 50~60% 감소했다.', True),
  (173, '미네랄-미네랄', '칼슘', '같은 성분 중복: 칼슘 함유 일반의약품 + 칼슘 영양제 + 탄산칼슘 제산제(+비타민D)로 보충 칼슘이 많은 경우', '칼슘', '다른 칼슘 함유 제품(칼슘염·탄산칼슘 제산제)', 'supplement_nutrient', '영양소_과잉_독성', '칼슘-알칼리 증후군(고칼슘혈증·대사성 알칼리증·급성 신손상). 이 증후군은 고칼슘혈증 입원 원인 3위이며 폐경 후·임신 여성이 고위험. 칼슘 보충제 사용은 심근경색 위험 소폭 증가와 연관(메타분석).', '탄산칼슘(칼슘 + 알칼리)', '과량 칼슘이 혈중 칼슘을 높이면 신장이 수분·중탄산을 덜 배출해 알칼리증이 생기고, 알칼리증이 다시 칼슘 재흡수를 늘리는 악순환이 일어나 신기능이 떨어진다.', '디카맥스디플러스정 등 칼슘 일반의약품 + 칼슘·마그네슘 영양제 + 탄산칼슘 함유 제산제', '골다공증 칼슘제를 먹는 60대 여성이 속쓰림에 탄산칼슘 제산제를 자주 먹고 칼슘 영양제도 따로 먹음', 'moderate', 'caution', '칼슘 함유 제품(제산제 포함) 합산, 보충제는 필요한 만큼만. 구역·변비·갈증·혼동 시 혈청 칼슘 확인', '식약처원문', 'medium', '식약처 허가사항의 ''칼슘염 복용하지 말 것''은 이미 칼슘이 든 제품에 다른 칼슘염을 더하지 말라는 취지로 해석(문구 자체는 이유를 명시하지 않음). 한국인 칼슘 상한 원문 미확인(2025 개정 논문 존재 확인만).', True),
  (174, '미네랄-미네랄', '칼슘', '고용량 칼슘 보충(하루 1,000 mg 추가)', '마그네슘', '무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '일부 성인 연구에서 고칼슘 섭취가 마그네슘 이용을 낮춘다는 보고가 있으나, 무작위 이중맹검 연구(청소년 여아, 칼슘 1,000 mg 추가)에서는 마그네슘 흡수율 50% 대 55%로 차이가 없었다.', '칼슘', '칼슘과 마그네슘이 장과 신장에서 일부 수송 경로를 공유한다는 이론적 경쟁. 사람에서 일관된 근거는 없음.', '칼슘·마그네슘 복합 영양제, 칼슘제 + 마그네슘 영양제', '칼슘제와 마그네슘 영양제를 함께 먹으며 흡수가 떨어질까 걱정하는 60대', 'minor', 'caution', '특별한 분리 복용 근거는 약함. 마그네슘 결핍 위험군(이뇨제·PPI 장기 복용)은 혈중 마그네슘 확인', 'RCT/약동학연구', 'low', '시드 조합 근거 확인 결과 ''흡수 경쟁'' 주장은 근거가 약하고 상충함. 노인 성인 대상 연구는 찾지 못함.', True),
  (175, '미네랄-미네랄', '칼슘', '탄산칼슘 600 mg을 식사·아연과 함께, 또는 하루 칼슘 섭취를 고용량으로 늘린 경우', '아연', '미량 무기질', 'supplement_nutrient', '영양소_흡수감소_결핍', '폐경 후 여성(59~86세)에서 칼슘 468 mg/일 추가 시 아연 순흡수·균형이 약 2 mg/일 감소. 탄산칼슘 600 mg을 식사와 함께 먹으면 아연 흡수가 50% 감소. 식약처 아연 제제 허가사항은 칼슘염 병용 금지.', '칼슘(특히 인산칼슘·탄산칼슘)', '장관 내에서 칼슘·인산·피트산과 아연이 불용성 복합체를 만들고, 흡수 경로에서도 경쟁하는 것으로 추정된다. 칼슘제에 아연을 추가하면 이 영향이 상쇄되었다.', '칼슘제·칼슘·마그네슘 영양제 + 아연 영양제·라이트징크시럽(황산아연)', '골다공증 예방 칼슘제를 매 끼니 먹는 60대 여성이 아연 영양제를 같은 식사 때 함께 복용', 'minor', 'separate_timing', '아연 보충이 목적이면 칼슘제와 다른 시간에. 고용량 칼슘 복용 노인은 아연 섭취 확인', '식약처원문', 'high', null, True),
  (176, '비타민-기타영양제', '베타카로틴', '베타카로틴과 루테인을 같은 시각에 고용량으로 복용', '루테인', '카로티노이드(눈 건강 기능성 원료, 지아잔틴 포함 제품 다수)', 'supplement_nutrient', '영양소_흡수감소_결핍', '같은 용량을 함께 투여하면 베타카로틴이 혈청 루테인 AUC를 대조의 54~61%로 낮춤. 루테인이 베타카로틴에 주는 영향은 사람마다 달랐음(5명 감소, 3명 증가).', '베타카로틴', '카로티노이드끼리 장에서 미셀 편입과 흡수 수송체(SR-BI 등)를 두고 경쟁하고, 혈청 청소에도 서로 영향을 준다.', '루테인·지아잔틴 눈 영양제 + 베타카로틴 함유 종합비타민·눈 영양제', '황반변성 예방으로 루테인을 먹는 60대가 베타카로틴 고함량 종합비타민을 같은 아침에 복용', 'minor', 'separate_timing', '루테인 효과를 원하면 고용량 베타카로틴 제품과 다른 끼니에 복용하거나 중복 제품 정리', 'RCT/약동학연구', 'medium', '8명 단회 투여 약동학 연구. 장기 임상 결과(시력)에 미치는 영향은 확인되지 않음.', True),
  (177, '비타민-기타영양제', '비타민E', '고용량 비타민E(400 IU 이상) + 오메가3 고용량·은행잎추출물 등 항혈소판 작용 영양제', '오메가3 지방산', '항혈소판 작용 영양제(EPA·DHA, 은행잎추출물 등)', 'supplement_nutrient', '출혈위험', '비타민E 단독 보충 메타분석(9개 RCT, 118,765명)에서 출혈성 뇌졸중 RR 1.22(1.00~1.48), 1,250명당 1명 추가. 오메가3는 혈소판 응집을 줄이지만 수술 중·후 출혈을 늘리지 않았다(체계적 고찰). 둘을 함께 먹었을 때 출혈이 늘어난다는 직접 근거는 찾지 못함.', 'α-토코페롤(혈소판 기능·비타민K 길항), EPA·DHA(혈소판 응집 억제)', '비타민E는 혈소판 응집과 비타민K 의존 응고를 약화시키고, 오메가3·은행잎은 혈소판 기능을 억제한다. 작용이 더해질 수 있다는 이론적 우려.', '그랑페롤 등 비타민E + 오메가3(rTG 고함량)·은행잎추출물(징코) 영양제', '혈행 개선을 위해 오메가3와 은행잎 영양제를 먹는 60대가 비타민E 400 IU도 추가', 'minor', 'caution', '건강한 사람에게 특별한 분리 필요는 없음. 항응고제·항혈소판제 복용자, 수술·발치 전에는 상담. 비타민E 고용량은 피함', '이론적', 'low', '근거 약함: 조합 자체의 출혈 증가 근거 없음. 지시에 따라 ''근거 확실한 것만''의 기준엔 못 미치지만 이론적 조합으로 기록.', True);
insert into public.new_nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) values
  (1, 1, '식약처_의약품허가', '리피토정10밀리그램(아토르바스타틴칼슘삼수화물) 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200410090', null, null, '니코틴산 : 니코틴산과 병용하는 경우 골격근 효과의 위험이 증가될 수 있으므로 이 약의 감량을 고려해야 한다.', 'quote_ok'),
  (2, 1, '논문', 'Effects of extended-release niacin with laropiprant in high-risk patients (HPS2-THRIVE, N Engl J Med 2014)', 'https://pubmed.ncbi.nlm.nih.gov/25014686/', '25014686', null, 'did not significantly reduce the risk of major vascular events but did increase the risk of serious adverse events', 'pmid_ok_quote_ok'),
  (3, 1, '해외정부기관', 'NIASPAN (niacin extended-release) Prescribing Information, US FDA label 2022', 'https://www.accessdata.fda.gov/drugsatfda_docs/label/2022/020381s055lbl.pdf', null, null, 'Caution should be used when prescribing niacin (1 gm/day) with statins as these drugs can increase risk of myopathy/rhabdomyolysis', 'skipped'),
  (5, 3, '논문', 'Niacin therapy and the risk of new-onset diabetes: a meta-analysis of randomised controlled trials (Heart 2016)', 'https://europepmc.org/article/MED/26370223', '26370223', null, 'Niacin therapy was associated with a RR of 1.34 (95% CIs 1.21 to 1.49) for new-onset diabetes', 'pmid_ok_quote_ok'),
  (6, 3, '논문', 'Effects of extended-release niacin with laropiprant in high-risk patients (HPS2-THRIVE, N Engl J Med 2014)', 'https://pubmed.ncbi.nlm.nih.gov/25014686/', '25014686', null, 'did not significantly reduce the risk of major vascular events but did increase the risk of serious adverse events', 'pmid_ok_quote_ok'),
  (7, 3, '해외정부기관', 'NIASPAN (niacin extended-release) Prescribing Information, US FDA label 2022', 'https://www.accessdata.fda.gov/drugsatfda_docs/label/2022/020381s055lbl.pdf', null, null, 'Diabetic patients may experience a dose-related increase in glucose intolerance.', 'skipped'),
  (8, 4, '식약처_의약품허가', '조코정20밀리그램(심바스타틴) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200807527', null, null, '10) 니코틴산(1일 1g 이상) : 이 약과 단독으로 투여시 근육병증을 유발할 수 있는 지질저하 용량(1일 1g 이상)의 니코틴산을 병용투여하였을 때 근육병증/횡문근융해가 관찰되었다.', 'quote_ok'),
  (9, 4, '식약처_의약품허가', '리피토정10밀리그램(아토르바스타틴칼슘삼수화물) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200410090', null, null, '19) 니코틴산 : 니코틴산과 병용하는 경우 골격근 효과의 위험이 증가될 수 있으므로 이 약의 감량을 고려해야 한다.', 'quote_ok'),
  (10, 4, '논문', 'HPS2-THRIVE randomized placebo-controlled trial: trial design, pre-specified muscle and liver outcomes (Eur Heart J 2013)', 'https://pubmed.ncbi.nlm.nih.gov/23444397/', '23444397', null, 'The risk of myopathy was increased by adding ERN/LRPT to simvastatin 40 mg daily (with or without ezetimibe)', 'pmid_ok_quote_ok'),
  (11, 5, '해외정부기관', 'NIASPAN (niacin extended-release) Prescribing Information, US FDA label 2022', 'https://www.accessdata.fda.gov/drugsatfda_docs/label/2022/020381s055lbl.pdf', null, null, 'Elevated uric acid levels have occurred with niacin therapy, therefore use with caution in patients predisposed to gout.', 'skipped'),
