  (431, 167, '논문', '2020 한국인 영양소 섭취기준: 아연 (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202226461024414.pdf', null, '10.4163/jnh.2022.55.4.441', '아연 평균필요량과 권장섭취량은 6–10 mg/day이고, 상한섭취량은 35 mg/day로 제시되고 있다.', 'no_pmid'),
  (432, 168, '논문', 'Inhibitory effects of zinc on magnesium balance and magnesium absorption in man (J Am Coll Nutr 1994)', 'https://pubmed.ncbi.nlm.nih.gov/7836627/', '7836627', null, 'Zn supplements of 142 mg/day decreased Mg absorption and the Mg balance significantly during all Ca intakes for the three groups combined.', 'pmid_ok_quote_ok'),
  (433, 169, '논문', 'Iodine-induced hyperthyroidism in a patient with a normal thyroid gland (Postgrad Med J 1986)', 'https://pubmed.ncbi.nlm.nih.gov/3748931/', '3748931', null, 'We report the case of a 72 year old female who developed clinical and laboratory evidence of hyperthyroidism while ingesting sea-kelp (Vitalia) tablets.', 'pmid_ok_quote_ok'),
  (434, 169, '논문', 'Iodine-induced hyperthyroidism (iodine-induced Basedow''s disease): a current disease picture (Schweiz Med Wochenschr 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10407936/', '10407936', null, 'Clinical features were predominantly tachyarrhythmias and heart failure, while 6 of 8 patients had goitre', 'pmid_ok_quote_ok'),
  (435, 169, '논문', 'Elemental Composition of Algae-Based Supplements by Energy Dispersive X-ray Fluorescence (Plants 2021)', 'https://pubmed.ncbi.nlm.nih.gov/34685850/', '34685850', null, 'the levels observed might well contribute to an excess in the human body, which can cause dysfunction of the thyroid gland.', 'pmid_ok_quote_ok'),
  (436, 170, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라) - 상의 대상', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', null, null, '철 함유제제(철제, MRI용 간장 조영제 등)를 투여중인 환자', 'quote_ok'),
  (437, 171, '논문', 'Studies on the bioavailability of zinc in humans: effects of heme and nonheme iron on the absorption of zinc (Am J Clin Nutr 1981)', 'https://pubmed.ncbi.nlm.nih.gov/7223699/', '7223699', null, 'a ratio of Fe/Zn of 1:1 slightly inhibited zinc absorption while Fe/Zn ratio of 2:1 and 3:1 substantially inhibited zinc uptake', 'pmid_ok_quote_ok'),
  (438, 171, '논문', 'Competitive inhibition of iron absorption by manganese and zinc in humans (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/2058577/', '2058577', null, 'a fivefold excess of zinc to iron (15 mgZn/3 mg Fe) reduced iron absorption by 56% when given in a water solution', 'pmid_ok_quote_ok'),
  (439, 171, '논문', 'Iron and zinc interactions in humans (Am J Clin Nutr 1998)', 'https://pubmed.ncbi.nlm.nih.gov/9701159/', '9701159', null, 'when iron and zinc are given in a meal, this effect is not observed', 'pmid_ok_quote_ok'),
  (440, 172, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', null, null, '이 약을 복용하는 동안 다음의 약을 복용하지 말 것. 1) 인산염, 칼슘염', 'quote_ok'),
  (441, 172, '식약처_의약품허가', '훼럼포유연질캡슐 사용상의 주의사항 - 5. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201805238', null, null, '1) 인산염, 칼슘염', 'quote_ok'),
  (442, 172, '논문', 'Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/1984335/', '1984335', null, 'Iron absorption was reduced by 50-60% at doses of 300-600 mg Ca.', 'pmid_ok_quote_ok'),
  (443, 172, '논문', 'Calcium supplementation: effect on iron absorption (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/1984334/', '1984334', null, 'All calcium supplements inhibited absorption of the iron supplement when taken with food.', 'pmid_ok_quote_ok'),
  (444, 173, '식약처_의약품허가', '디카맥스디플러스정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200802864', null, null, '이 약을 복용하는 동안 다음의 약을 복용하지 말 것. - 인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제', 'quote_ok'),
  (445, 173, '논문', 'Got calcium? Welcome to the calcium-alkali syndrome (J Am Soc Nephrol 2010)', 'https://pubmed.ncbi.nlm.nih.gov/20413609/', '20413609', null, 'The calcium-alkali syndrome is now the third most common cause of hospital admission for hypercalcemia', 'pmid_ok_quote_ok'),
  (446, 173, '논문', 'Calcium supplements with or without vitamin D and risk of cardiovascular events (BMJ 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21505219/', '21505219', null, 'Calcium supplements with or without vitamin D modestly increase the risk of cardiovascular events, especially myocardial infarction', 'pmid_ok_quote_ok'),
  (447, 174, '논문', 'Magnesium balance in adolescent females consuming a low- or high-calcium diet (Am J Clin Nutr 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8644692/', '8644692', null, 'alterations in magnesium utilization should not be anticipated in adolescent females consuming a high-calcium diet', 'pmid_ok_quote_ok'),
  (448, 175, '식약처_의약품허가', '라이트징크시럽(황산아연일수화물) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201206329', null, null, '이 약을 투여할 경우에는 인산염, 칼슘염, 경구용테트라사이클린계 제제, 제산제와 병용투여하지 않는다.', 'quote_ok'),
  (449, 175, '논문', 'High dietary calcium intakes reduce zinc absorption and balance in humans (Am J Clin Nutr 1997)', 'https://pubmed.ncbi.nlm.nih.gov/9174476/', '9174476', null, 'Zinc absorption was reduced significantly by 50% when the calcium supplement was given with the meal.', 'pmid_ok_quote_ok'),
  (450, 176, '논문', 'Intestinal absorption, serum clearance, and interactions between lutein and beta-carotene when administered to human adults in separate or combined oral doses (Am J Clin Nutr 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7661123/', '7661123', null, 'beta-carotene significantly reduced the serum AUC values for lutein to 54-61% of control values (P < 0.025)', 'pmid_ok_quote_ok'),
  (451, 177, '논문', 'Effects of vitamin E on stroke subtypes: meta-analysis of randomised controlled trials (BMJ 2010)', 'https://pubmed.ncbi.nlm.nih.gov/21051774/', '21051774', null, 'vitamin E increased the risk for haemorrhagic stroke by 22% and reduced the risk of ischaemic stroke by 10%', 'pmid_ok_quote_ok'),
  (452, 177, '논문', 'No impact of fish oil supplements on bleeding risk: a systematic review (Dan Med J 2017)', 'https://pubmed.ncbi.nlm.nih.gov/28552094/', '28552094', null, 'Fish oil exposure in surgical patients did not increase bleeding or blood transfusions either during or after surgery.', 'pmid_ok_quote_ok');
insert into public.new_nutrient_daily_limit (id, nutrient, limit_type, age_group, amount, unit, source_title, source_url, quote) values
  (1, '칼슘', 'upper', '19~50세', 2500.0, '밀리그램', 'Calcium in diet (MedlinePlus Medical Encyclopedia)', 'https://medlineplus.gov/ency/article/002412.htm', null),
  (2, '칼슘', 'upper', '50세 초과', 2000.0, '밀리그램', 'Calcium in diet (MedlinePlus Medical Encyclopedia)', 'https://medlineplus.gov/ency/article/002412.htm', null),
  (3, '셀레늄', 'upper', '성인', 400.0, '마이크로그램', '셀레늄의 2020 한국인 영양소 섭취기준 개정 및 권장식단의 셀레늄 함량 평가 (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202226461023414.pdf', '한국 성인의 셀레늄 상한섭취량은 400 µg/일로 결정하였다.'),
  (4, '아연', 'upper', '성인', 35.0, '밀리그램', '2020 한국인 영양소 섭취기준: 아연 (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202226461024414.pdf', '아연 평균필요량과 권장섭취량은 6–10 mg/day이고, 상한섭취량은 35 mg/day로 제시되고 있다.'),
  (5, '비타민A', 'mfds_label', '성인', 5000.0, '아이.유', '멀티비타원프리미엄정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200800955', '이 제품에 함유된 비타민A는 정상적인 식이에서 충분히 공급되므로 보조요법의 용량은 1일 5,000IU이상을 넘지 않도록 한다.'),
  (6, '비타민B6', 'mfds_label', '성인', 50.0, '밀리그램', '뉴로비정300밀리그램(피리독신염산염) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202200702', '피리독신을 1일 50 mg 이상의 용량으로 장기간 투여시 감각 이상(paresthesias) 등 말초신경병증이 보고된 바 있다.');
