insert into public.new_eyak_supplement_warning (item_seq, name, company, url, warning_text) values
  ('202300436', '비맥스제트정', '(주)녹십자', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202300436', '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.'),
  ('200709544', '임팩타민정', '(주)대웅제약', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200709544', '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.'),
  ('201508281', '벤포벨정', '(주)종근당', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201508281', '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제, 레보도파와 함께 복용하지 마십시오.'),
  ('200101738', '훼로바-유서방정(건조황산제일철)', '부광약품(주)', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200101738', '이 약을 복용하는 동안 인산염, 칼슘염, 경구용 테트라사이클린계 항생제, 제산제와 함께 복용하지 마십시오. / 철 함유제제(철제, MRI용 간장 조영제 등), 항알도스테론제, 트리암테렌, 디포스폰산 염류, 티록신, 세프디니르 제제, 살리실산, 페닐부타존, 옥시펜부타존, 퀴놀론계, 페니실라민, 콜레스티라민, 췌장엑스 및 비타민 E와 같은 제제, 200 mg 이상의 아스코르빈산(비타민 C)과 함께 복용 시 의사 또는 약사와 상의하십시오.');
