-- 병용 위해 조합 축약본: database/nutrient_interaction(184개) 중 new_drug(104)·new_health_food(100)에서
-- 실제로 짝이 생기는 조합 121개와 그 근거 340개, 조합마다 걸리는 제품(new_interaction_item_match).
-- 01_new_drug.sql, 02_new_health_food.sql을 먼저 실행한 뒤 실행한다(제품 이름을 붙여 보는 뷰가 두 테이블을 쓴다).
-- 구조는 database/nutrient_interaction.sql과 같고 테이블 이름 앞에 new_. 다시 실행하면 new_ 테이블만 지우고 새로 만든다.
-- 심각도: major 22 · moderate 65 · minor 34
-- 제품 짝: 약×영양제 6144쌍 · 영양제×영양제 8262쌍 (new_interaction_pair 뷰)

begin;

drop view if exists public.new_interaction_pair;
drop table if exists public.new_interaction_item_match;
drop table if exists public.new_eyak_supplement_warning;
drop table if exists public.new_nutrient_ingredient_map;
drop table if exists public.new_nutrient_daily_limit;
drop table if exists public.new_nutrient_interaction_source;
drop table if exists public.new_nutrient_interaction;

create table public.new_nutrient_interaction (
  id                  integer primary key,  -- 원본 nutrient_interaction.id 그대로
  category            text not null,  -- 비타민-의약품 / 미네랄-의약품 / 비타민-비타민 / 비타민-미네랄 / 미네랄-미네랄 / 비타민-기타영양제
  nutrient            text not null,  -- 문제 성분(예: 칼슘, 철분, 비타민B9(엽산))
  nutrient_condition  text,           -- 문제가 되는 용량·형태. 제품 함량이 없어 매칭에서는 판정하지 않았다
  counterpart         text not null,  -- 상대: 약은 일반명, 영양소는 nutrient와 같은 이름
  counterpart_class   text,
  counterpart_type    text not null,  -- drug / supplement_nutrient
  outcome_type        text not null,  -- 약효감소 / 약효증가_독성 / 영양소_흡수감소_결핍 / 영양소_과잉_독성 / 출혈위험 / 기타
  harmful_effect      text not null,
  causal_ingredient   text not null,
  mechanism           text not null,
  example_products    text,
  example_scenario    text,
  severity            text not null,  -- major / moderate / minor
  relation            text not null,  -- avoid / consult / separate_timing / caution / monitor
  management          text,
  evidence_level      text not null,
  confidence          text not null,  -- high / medium / low
  notes               text,
  dose_dependent      boolean not null  -- 축약본에만 있는 열: nutrient_condition에 용량·기간 조건이 있으면 true
);

create table public.new_nutrient_interaction_source (
  id               integer primary key,
  interaction_id   integer not null references public.new_nutrient_interaction(id) on delete cascade,
  kind             text not null,  -- 식약처_의약품허가 / 식약처_건강기능식품 / 식약처_기타 / 논문 / 해외정부기관
  title            text not null,
  url              text not null,
  pmid             text,
  doi              text,
  quote            text,
  verified         text not null   -- quote_ok / pmid_ok_quote_ok / pmid_ok / no_pmid / skipped
);

-- 과다 섭취 판정용 하루 기준량(원본 6행 전부)
create table public.new_nutrient_daily_limit (
  id            integer primary key,
  nutrient      text not null,
  limit_type    text not null,  -- upper / mfds_label
  age_group     text not null,
  amount        real not null,
  unit          text not null,
  source_title  text not null,
  source_url    text not null,
  quote         text
);

-- 의약품 성분명 → 영양소(원본 8행 전부)
create table public.new_nutrient_ingredient_map (
  ingredient_name  text primary key,
  nutrient         text not null,
  elemental_ratio  real,
  notes            text
);

-- e약은요에 영양제 병용 주의 문구가 있는 일반의약품(원본 database/eyak_supplement_warnings.csv 중 new_drug에 있는 것)
create table public.new_eyak_supplement_warning (
  item_seq      text primary key references public.new_drug(item_seq) on delete cascade,
  name          text not null,
  company       text,
  url           text not null,
  warning_text  text not null
);

-- 축약본에만 있는 테이블: 조합의 양쪽(nutrient 쪽 / counterpart 쪽)에 걸리는 제품
create table public.new_interaction_item_match (
  interaction_id      integer not null references public.new_nutrient_interaction(id) on delete cascade,
  side                text not null check (side in ('nutrient','counterpart')),
  item_type           text not null check (item_type in ('drug','health_food')),
  item_id             text not null,   -- drug: new_drug.item_seq / health_food: new_health_food.report_no
  matched_ingredient  text not null,   -- 걸린 성분·원재료 이름(원문 표기)
  match_basis         text not null,   -- 상대 약 이름 / 같은 계열(…) / 기능성 원재료 / 기능성 내용 표기 / 일반의약품 영양 성분
  primary key (interaction_id, side, item_type, item_id)
);







create index new_ni_nutrient_idx on public.new_nutrient_interaction (nutrient);
create index new_ni_counterpart_idx on public.new_nutrient_interaction (counterpart);
create index new_nis_interaction_idx on public.new_nutrient_interaction_source (interaction_id);
create index new_iim_item_idx on public.new_interaction_item_match (item_type, item_id);

-- 제품 짝: 한쪽은 nutrient 쪽, 다른 쪽은 counterpart 쪽에 걸린 서로 다른 제품. 약×약은 뺀다(앱 범위와 같음)
create view public.new_interaction_pair as
select i.id as interaction_id,
       case when a.item_type = 'drug' or b.item_type = 'drug' then '약×영양제' else '영양제×영양제' end as pair_kind,
       i.severity, i.relation, i.nutrient, i.counterpart,
       a.item_type as a_type, a.item_id as a_id, coalesce(ad.name, af.name) as a_name, a.matched_ingredient as a_ingredient,
       b.item_type as b_type, b.item_id as b_id, coalesce(bd.name, bf.name) as b_name, b.matched_ingredient as b_ingredient,
       b.match_basis as b_basis, i.dose_dependent, i.nutrient_condition, i.harmful_effect, i.management
from public.new_nutrient_interaction i
join public.new_interaction_item_match a on a.interaction_id = i.id and a.side = 'nutrient'
join public.new_interaction_item_match b on b.interaction_id = i.id and b.side = 'counterpart'
left join public.new_drug ad on a.item_type = 'drug' and ad.item_seq = a.item_id
left join public.new_health_food af on a.item_type = 'health_food' and af.report_no = a.item_id
left join public.new_drug bd on b.item_type = 'drug' and bd.item_seq = b.item_id
left join public.new_health_food bf on b.item_type = 'health_food' and bf.report_no = b.item_id
where not (a.item_type = b.item_type and a.item_id = b.item_id)
  and not (a.item_type = 'drug' and b.item_type = 'drug');

-- 앱(anon 키)에서는 읽기만 허용
alter table public.new_nutrient_interaction enable row level security;
alter table public.new_nutrient_interaction_source enable row level security;
alter table public.new_nutrient_daily_limit enable row level security;
alter table public.new_nutrient_ingredient_map enable row level security;
alter table public.new_eyak_supplement_warning enable row level security;
alter table public.new_interaction_item_match enable row level security;
create policy "public read" on public.new_nutrient_interaction for select using (true);
create policy "public read" on public.new_nutrient_interaction_source for select using (true);
create policy "public read" on public.new_nutrient_daily_limit for select using (true);
create policy "public read" on public.new_nutrient_ingredient_map for select using (true);
create policy "public read" on public.new_eyak_supplement_warning for select using (true);
create policy "public read" on public.new_interaction_item_match for select using (true);

commit;

